SET check_function_bodies=off;
CREATE SCHEMA auth;
CREATE SCHEMA extensions;
CREATE ROLE anon;CREATE ROLE authenticated;CREATE ROLE service_role BYPASSRLS;CREATE ROLE supabase_auth_admin;
CREATE EXTENSION pgcrypto WITH SCHEMA extensions;CREATE EXTENSION "uuid-ossp" WITH SCHEMA extensions;
SET search_path=public,extensions;
CREATE SCHEMA "smarter_private";
CREATE TYPE "auth"."factor_type" AS ENUM('totp','webauthn','phone');
CREATE TYPE "auth"."factor_status" AS ENUM('unverified','verified');
CREATE TYPE "auth"."aal_level" AS ENUM('aal1','aal2','aal3');
CREATE TYPE "auth"."code_challenge_method" AS ENUM('s256','plain');
CREATE TYPE "auth"."one_time_token_type" AS ENUM('confirmation_token','reauthentication_token','recovery_token','email_change_token_new','email_change_token_current','phone_change_token');
CREATE TYPE "auth"."oauth_registration_type" AS ENUM('dynamic','manual');
CREATE TYPE "auth"."oauth_authorization_status" AS ENUM('pending','approved','denied','expired');
CREATE TYPE "auth"."oauth_response_type" AS ENUM('code');
CREATE TYPE "auth"."oauth_client_type" AS ENUM('public','confidential');
CREATE TYPE "public"."member_role" AS ENUM('owner','admin','agent','member','super_agent','player');
CREATE TYPE "public"."game_type" AS ENUM('NLHE','PLO','PLO5','cash','tournament','sit_n_go');
CREATE TYPE "public"."member_status" AS ENUM('active','pending','suspended','banned');
CREATE TYPE "public"."game_variant" AS ENUM('nlh','flh','plo4','plo5','plo6','plo_hilo','plo8','short_deck','ofc','ofc_pineapple');
CREATE TYPE "public"."table_status" AS ENUM('waiting','running','paused','closed');
CREATE TYPE "public"."transaction_type" AS ENUM('deposit','withdrawal','buy_in','cash_out','agent_transfer','rake','bonus','refund');
