CREATE OR REPLACE FUNCTION public.fn_audit_actor_role(p_club_id uuid, p_actor uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.clubs c
                 WHERE c.id = p_club_id AND c.owner_id = p_actor) THEN 'owner'
    ELSE COALESCE(
      (SELECT CASE cm.role
                WHEN 'owner'       THEN 'owner'
                WHEN 'co_owner'    THEN 'co_owner'
                WHEN 'admin'       THEN 'admin'
                WHEN 'super_agent' THEN 'super_agent'
                WHEN 'agent'       THEN 'agent'
                WHEN 'sub_agent'   THEN 'sub_agent'
                WHEN 'player'      THEN 'player'
                ELSE 'system'
              END
         FROM public.club_members cm
        WHERE cm.club_id = p_club_id AND cm.user_id = p_actor
        LIMIT 1),
      'system')
  END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_spin jsonb;
  v_bbj_main numeric := 0; v_bbj_backup numeric := 0; v_bbj_promo numeric := 0;
  v_bbj_total numeric := 0; v_club_promo numeric := 0;
  v_keep_main numeric; v_keep_backup numeric; v_pool_id uuid; v_union_pool uuid; v_after numeric; v_treasury numeric;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_close');
  END IF;

  v_spin := public.fn_spin_absorb_club_pool_into_union(p_club_id, p_union_id);

  SELECT id, COALESCE(main_balance,0), COALESCE(backup_balance,0), COALESCE(promo_balance,0)
    INTO v_pool_id, v_bbj_main, v_bbj_backup, v_bbj_promo
    FROM public.bbj_pools
   WHERE club_id = p_club_id AND union_id IS NULL
   FOR UPDATE;

  IF v_pool_id IS NOT NULL THEN
    v_keep_main := public.fn_bbj_parked_reserve(v_pool_id,'main');
    v_keep_backup := public.fn_bbj_parked_reserve(v_pool_id,'backup');
    v_bbj_main := v_bbj_main-v_keep_main;
    v_bbj_backup := v_bbj_backup-v_keep_backup;
    IF v_bbj_main<0 OR v_bbj_backup<0 THEN
      RAISE EXCEPTION 'club jackpot bank cannot cover its parked obligations';
    END IF;
    v_bbj_total := v_bbj_main + v_bbj_backup + v_bbj_promo;
    SELECT id INTO v_union_pool FROM public.bbj_pools WHERE union_id = p_union_id LIMIT 1;

    IF v_bbj_total > 0 THEN
      v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bbj_total);
      IF v_after IS NULL THEN
        RAISE EXCEPTION 'cannot pay the % BBJ balance of club % into its treasury', v_bbj_total, p_club_id;
      END IF;

      -- bbj_promo_sweep so fn_bbj_conservation_check counts this as OUTFLOW.
      -- Without this row the gap moves by exactly v_bbj_total and a correct
      -- transfer reads as a money leak.
      INSERT INTO public.chip_transactions
        (id, club_id, amount, transaction_type, notes, balance_after, metadata)
      VALUES (gen_random_uuid(), p_club_id, v_bbj_total, 'bbj_promo_sweep',
              format('BBJ, backup and promo closed into the club main bank on joining union %s - the club keeps these funds. Play moves to the union pool; this money does not.', p_union_id),
              v_after,
              jsonb_build_object('reason','union_join','union_id',p_union_id,
                                 'bbj_main',v_bbj_main,'bbj_backup',v_bbj_backup,
                                 'bbj_promo',v_bbj_promo,'club_pool_id',v_pool_id));
    END IF;

    UPDATE public.bbj_pools
       SET main_balance = v_keep_main, backup_balance = v_keep_backup, promo_balance = 0,
           status = 'retired',
           merged_into_pool_id = COALESCE(merged_into_pool_id, v_union_pool),
           updated_at = now()
     WHERE id = v_pool_id;
  END IF;

  SELECT COALESCE(promo_balance,0) INTO v_club_promo
    FROM public.clubs WHERE id = p_club_id FOR UPDATE;

  IF v_club_promo > 0 THEN
    UPDATE public.clubs
       SET chip_treasury = COALESCE(chip_treasury,0) + v_club_promo,
           promo_balance = 0
     WHERE id = p_club_id
     RETURNING chip_treasury INTO v_treasury;

    INSERT INTO public.chip_transactions
      (id, club_id, amount, transaction_type, notes, balance_after, metadata)
    VALUES (gen_random_uuid(), p_club_id, v_club_promo, 'promo_closed_on_union_join',
            format('Club promo float closed into the main bank on joining union %s - the club keeps these funds to disburse at its own discretion', p_union_id),
            v_treasury,
            jsonb_build_object('reason','union_join','union_id',p_union_id));
  END IF;

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'spins', v_spin, 'bbj_swept', v_bbj_total, 'club_promo_swept', v_club_promo,
    'club_treasury_after', COALESCE(v_treasury, v_after));
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_clear_table_seats(p_table_id uuid, p_reopen boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cleared integer := 0;
  v_tournament uuid;
BEGIN
  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Table not found' USING ERRCODE='22023'; END IF;
  IF v_tournament IS NULL THEN
    RAISE EXCEPTION 'CASH_SEAT_CLEAR_REQUIRES_ENGINE_DEPARTURES' USING ERRCODE='55000';
  END IF;
  -- Only tournament cleanup reaches this point. Cash departures are engine-owned.
  PERFORM public.fn_cashout_seats_for_closing_table(p_table_id, 'seats cleared');

  UPDATE public.table_seats
     SET left_at = now(), is_sitting_out = false
   WHERE table_id = p_table_id AND left_at IS NULL;
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  UPDATE public.tables
     SET current_players = 0,
         status = CASE WHEN p_reopen AND status <> 'closed' THEN 'waiting' ELSE status END
   WHERE id = p_table_id;

  RETURN v_cleared;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_process_hand_position_stats(p_players jsonb, p_actions jsonb, p_winners jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order uuid[] := '{}';
  v_pre jsonb[] := '{}';
  v_uid uuid;
  v_n int;
  v_i int;
  v_pos text;
  v_raises int;
  v_player_raised boolean;
  v_vpip int; v_pfr int; v_3bet int; v_fold3 int;
  v_won int; v_profit numeric;
  a jsonb;
  v_raise_count_before int;
BEGIN
  IF p_players IS NULL OR jsonb_typeof(p_players) <> 'array' THEN
    RETURN;
  END IF;

  IF p_actions IS NOT NULL AND jsonb_typeof(p_actions) = 'array' THEN
    v_pre := ARRAY(
      SELECT e
        FROM jsonb_array_elements(p_actions) e
       WHERE e->>'stage' = 'preflop'
         AND (e->>'userId') IS NOT NULL
    );
  END IF;

  FOREACH a IN ARRAY v_pre LOOP
    v_uid := (a->>'userId')::uuid;
    IF NOT v_uid = ANY(v_order) THEN
      v_order := v_order || v_uid;
    END IF;
  END LOOP;

  v_n := array_length(v_order, 1);
  IF v_n IS NULL OR v_n < 2 THEN RETURN; END IF;

  FOR v_i IN 1..v_n LOOP
    v_uid := v_order[v_i];
    v_pos := CASE v_n - v_i
      WHEN 0 THEN 'BB'
      WHEN 1 THEN 'SB'
      WHEN 2 THEN 'BTN'
      WHEN 3 THEN 'CO'
      WHEN 4 THEN 'MP'
      ELSE 'UTG' END;

    v_vpip := 0; v_pfr := 0; v_3bet := 0; v_fold3 := 0;
    v_raises := 0; v_player_raised := false;

    FOREACH a IN ARRAY v_pre LOOP
      v_raise_count_before := v_raises;
      IF a->>'action' IN ('raise','bet') THEN v_raises := v_raises + 1; END IF;

      IF (a->>'userId')::uuid = v_uid THEN
        IF a->>'action' IN ('call','raise','bet')
           AND COALESCE((a->>'amount')::numeric, 0) > 0 THEN
          v_vpip := 1;
        END IF;
        IF a->>'action' IN ('raise','bet') THEN
          v_pfr := 1;
          IF v_raise_count_before >= 1 THEN v_3bet := 1; END IF;
          v_player_raised := true;
        END IF;
        IF a->>'action' = 'fold' AND v_player_raised
           AND v_raise_count_before >= 2 THEN
          v_fold3 := 1;
        END IF;
      END IF;
    END LOOP;

    SELECT COALESCE(sum((w->>'amount')::numeric), 0) INTO v_profit
      FROM jsonb_array_elements(COALESCE(p_winners, '[]'::jsonb)) w
     WHERE (w->>'userId')::uuid = v_uid;
    v_won := CASE WHEN v_profit > 0 THEN 1 ELSE 0 END;

    v_profit := v_profit - COALESCE((
      SELECT sum(mx) FROM (
        SELECT max(COALESCE((a2->>'amount')::numeric, 0)) AS mx
          FROM jsonb_array_elements(p_actions) a2
         WHERE (a2->>'userId')::uuid = v_uid
           AND a2->>'action' IN ('call','raise','bet')
         GROUP BY a2->>'stage'
      ) s), 0);

    INSERT INTO public.player_position_stats AS pps
      (user_id, position, hands_played, vpip_count, pfr_count, three_bet_count,
       fold_to_three_bet_count, hands_won, total_profit, updated_at)
    VALUES (v_uid, v_pos, 1, v_vpip, v_pfr, v_3bet, v_fold3, v_won,
            round(v_profit, 2), now())
    ON CONFLICT (user_id, position) DO UPDATE SET
      hands_played = pps.hands_played + 1,
      vpip_count = pps.vpip_count + EXCLUDED.vpip_count,
      pfr_count = pps.pfr_count + EXCLUDED.pfr_count,
      three_bet_count = pps.three_bet_count + EXCLUDED.three_bet_count,
      fold_to_three_bet_count = pps.fold_to_three_bet_count + EXCLUDED.fold_to_three_bet_count,
      hands_won = pps.hands_won + EXCLUDED.hands_won,
      total_profit = pps.total_profit + EXCLUDED.total_profit,
      updated_at = now();
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_rank_survivors(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ranked integer := 0;
  v_bound  integer;
BEGIN
  SELECT GREATEST(COUNT(*), COALESCE(MAX(position), 0))
    INTO v_bound
    FROM tournament_players
   WHERE tournament_id = p_tournament_id;

  IF COALESCE(v_bound, 0) = 0 THEN
    RETURN 0;
  END IF;

  WITH taken AS (
    SELECT DISTINCT position
      FROM tournament_players
     WHERE tournament_id = p_tournament_id
       AND position IS NOT NULL
  ),
  survivors AS (
    SELECT id,
           row_number() OVER (
             ORDER BY COALESCE(chips, 0) DESC,
                      COALESCE(chip_count, 0) DESC,
                      registered_at ASC,
                      id ASC
           ) AS rn
      FROM tournament_players
     WHERE tournament_id = p_tournament_id
       AND position IS NULL
  ),
  free AS (
    SELECT g AS pos, row_number() OVER (ORDER BY g) AS rn
      FROM generate_series(1, v_bound) g
     WHERE NOT EXISTS (SELECT 1 FROM taken tk WHERE tk.position = g)
  )
  UPDATE tournament_players tp
     SET position      = f.pos,
         status        = CASE WHEN f.pos = 1 THEN 'winner' ELSE 'eliminated' END,
         eliminated_at = CASE WHEN f.pos = 1 THEN tp.eliminated_at
                              ELSE COALESCE(tp.eliminated_at, now()) END
    FROM survivors s
    JOIN free f ON f.rn = s.rn
   WHERE tp.id = s.id;

  GET DIAGNOSTICS v_ranked = ROW_COUNT;
  RETURN v_ranked;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_set_member_role(p_club_id uuid, p_user_id uuid, p_role text, p_actor_user_id uuid DEFAULT NULL::uuid, p_commission_rate numeric DEFAULT NULL::numeric, p_player_rakeback_rate numeric DEFAULT NULL::numeric, p_is_prepaid boolean DEFAULT NULL::boolean, p_credit_limit numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor      uuid;
  v_old_role   text;
  v_actor_role text;
  v_allowed    text[];
  v_downline   int;
  v_agent_id   uuid;
  v_parent     uuid;
  v_set_upline boolean := false;
  v_is_agent   boolean;
  v_is_staff   boolean;
  v_comm       numeric;
  v_rake       numeric;
  v_prepaid    boolean;
  v_limit      numeric;
  v_have_row   boolean := false;
  v_fresh      boolean;
  v_cap_comm   numeric;
  v_cap_rake   numeric;
  v_cap_limit  numeric;
  v_float      numeric;
  v_owed       numeric;
  v_commission numeric;
  v_keeps_wallet boolean;
  v_club_name  text;
  v_label      text;
BEGIN
  -- IDENTITY. auth.uid() is the ONLY identity a browser can establish; it is
  -- NULL for anon, and a NULL here used to mean "believe p_actor_user_id".
  -- A caller-supplied actor is now accepted from a trusted backend only.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    IF COALESCE(auth.role(), 'service_role') = 'service_role'
       AND p_actor_user_id IS NOT NULL THEN
      v_actor := p_actor_user_id;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'actor identity required');
    END IF;
  END IF;

  IF p_role IS NULL OR p_role NOT IN
     ('co_owner','admin','super_agent','agent','sub_agent','player') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid role: ' || COALESCE(p_role,'null'));
  END IF;

  v_is_agent := p_role IN ('super_agent','agent','sub_agent');
  v_is_staff := p_role IN ('co_owner','admin');

  IF NOT v_is_agent
     AND (COALESCE(p_commission_rate, 0) <> 0 OR COALESCE(p_player_rakeback_rate, 0) <> 0) THEN
    RETURN jsonb_build_object('success', false,
      'error', CASE WHEN v_is_staff
                    THEN 'co owners and admins receive no rakeback, so no rate may be set for one'
                    ELSE 'only an agent role carries a commission or rakeback rate' END);
  END IF;

  -- Funding belongs to an agent role. Sending it with a demotion to player, or
  -- with a promotion to staff, is a caller mistake worth naming rather than
  -- quietly ignoring: it usually means the wrong role reached this call.
  IF NOT v_is_agent AND (p_is_prepaid IS NOT NULL OR p_credit_limit IS NOT NULL) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'only an agent role is funded prepaid or on a credit line');
  END IF;

  SELECT role INTO v_old_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id
     AND status IN ('active','approved')
   FOR UPDATE;

  IF v_old_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'target is not a member of this club');
  END IF;

  IF v_old_role = p_role THEN
    RETURN jsonb_build_object('success', true, 'unchanged', true, 'role', p_role);
  END IF;

  v_allowed := fn_club_grantable_roles(p_club_id, v_actor, p_user_id);
  IF NOT (p_role = ANY (v_allowed)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not permitted to set this role',
      'allowed', COALESCE(to_jsonb(v_allowed), '[]'::jsonb));
  END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = v_actor AND status IN ('active','approved');

  IF fn_club_role_rank(v_old_role) > fn_club_role_rank(p_role)
     AND v_old_role IN ('super_agent','agent','sub_agent') THEN
    SELECT count(*) INTO v_downline FROM club_members
     WHERE club_id = p_club_id AND agent_id = p_user_id;
    IF v_downline > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'this member still has ' || v_downline || ' player'
                 || CASE WHEN v_downline = 1 THEN '' ELSE 's' END
                 || ' reporting to them. Move them to another agent first.',
        'downline_count', v_downline);
    END IF;
  END IF;

  v_set_upline := v_actor_role IN ('super_agent','agent')
                  AND p_role IN ('agent','sub_agent');

  -- ---------------------------------------------------------------------------
  -- A DEMOTION MUST NOT STRAND MONEY
  -- ---------------------------------------------------------------------------
  -- Every role except 'player' may hold an agent wallet - Dan, 2026-08-31:
  -- "OWNERS AND CO OWNERS CAN AND SHOULD HAVE AGENT WALLETS." So moving an
  -- agent up to co-owner, or sideways to another agent tier, strands nothing:
  -- the wallet goes with them and they can still spend it.
  --
  -- Becoming a PLAYER is the one move that takes the wallet away.
  -- fn_club_bank_role then returns 'player', fn_agent_wallet_send refuses them
  -- outright, and fn_agent_wallet_claim_back with it - so whatever the row still
  -- holds becomes chips nobody can move and nobody is watching. 67 of the 111
  -- active agents hold float today, 6,726,000 chips between them.
  --
  -- The remedy already exists and is named in the refusal:
  -- fn_club_bank_claim_back pulls the float back into the club bank, keyed on an
  -- op_id and written to the ledger, and any owner, co-owner, admin or super
  -- agent may run it. A debt is not sweepable and must be settled instead -
  -- fn_apply_credit_payment pays credit_used down when the invoice is paid.
  v_keeps_wallet := p_role <> 'player';

  -- PHASE 7. What the club still owes this person, from the ledger the claim
  -- path settles - rather than from the agents column that migration drops,
  -- which nothing ever wrote. It said 26,859.87 across 5 agents on a day the
  -- ledger held 408,809.59 across 114, so 109 of those 114 were reported to the
  -- person changing their role as owed nothing at all. One partial-index lookup
  -- (agent_commissions_unsettled_idx).
  -- reads the ledger directly: this function has already authorized its
  -- actor through fn_club_grantable_roles above, and it is SECURITY DEFINER,
  -- so it does not need the guarded caller-facing RPC's door. That RPC now
  -- admits only self, club admin and above, an agent ancestor, or the
  -- service role, and THIS report must not be able to fail on it. Same
  -- SELECT, same partial index (agent_commissions_unsettled_idx).
  SELECT COALESCE(SUM(ac.amount), 0)::numeric INTO v_commission
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id
     AND ac.user_id = p_user_id
     AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at);

  -- v_old_role was checked against the three AGENT tiers here, which missed the
  -- people phase 2 deliberately gave wallets to. A co-owner or an admin holds an
  -- agent wallet by design - Dan: "OWNERS AND CO OWNERS CAN AND SHOULD HAVE
  -- AGENT WALLETS" - so demoting one straight to player took the wallet away
  -- with the float still in it, which is the exact defect this phase exists to
  -- stop. Any role that is not already 'player' can be holding one.
  IF NOT v_keeps_wallet AND v_old_role <> 'player' THEN
    SELECT COALESCE(a.agent_wallet_balance, 0), COALESCE(a.credit_used, 0)
      INTO v_float, v_owed
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;

    IF COALESCE(v_float, 0) > 0 OR COALESCE(v_owed, 0) > 0 THEN
      -- Name only what is actually outstanding. "holds 5,000 chips and owes
      -- 0.00" invites somebody to go looking for a debt that is not there.
      RETURN jsonb_build_object('success', false, 'needs_settlement', true,
        'error', 'this member cannot become a player yet: '
                 || CASE WHEN COALESCE(v_float, 0) > 0 AND COALESCE(v_owed, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips, and they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || '. Claim the chips back into the club bank and settle the debt first.'
                         WHEN COALESCE(v_float, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips. Claim them back into the club bank first, '
                              || 'because a player cannot spend an agent wallet.'
                         ELSE 'they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || ' on their credit line. Settle the invoice first.'
                    END,
        'agent_wallet_balance', COALESCE(v_float, 0),
        'credit_used', COALESCE(v_owed, 0),
        'unclaimed_commission', COALESCE(v_commission, 0));
    END IF;
  END IF;

  IF v_is_agent THEN
    SELECT a.commission_rate, a.player_rakeback_rate, a.is_prepaid, a.credit_limit
      INTO v_comm, v_rake, v_prepaid, v_limit
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    v_have_row := FOUND;

    -- B-01, Dan 2026-08-31: FORCE A FRESH CHOICE.
    --
    -- A member whose current club role is not an agent tier is being PROMOTED.
    -- Their agents row may still hold the commission, rakeback and credit line
    -- they carried before they were demoted, and a commercial term nobody has
    -- re-agreed does not come back by default - "getting this wrong costs
    -- money" was the whole of the question put to Dan. So on a promotion every
    -- term is taken from this call and from nowhere else.
    --
    -- Re-GRADING an existing agent (agent to super agent) is a different act:
    -- their terms are live, not stale, and carrying them forward when the
    -- caller sends nothing is what every existing caller already relies on.
    v_fresh := v_old_role NOT IN ('super_agent','agent','sub_agent');

    IF v_fresh THEN
      v_comm    := p_commission_rate;
      v_rake    := p_player_rakeback_rate;
      v_prepaid := p_is_prepaid;
      v_limit   := p_credit_limit;
    ELSE
      v_comm    := COALESCE(p_commission_rate, v_comm);
      v_rake    := COALESCE(p_player_rakeback_rate, v_rake);
      v_prepaid := COALESCE(p_is_prepaid, v_prepaid);
      v_limit   := COALESCE(p_credit_limit, v_limit);
    END IF;

    IF v_comm IS NULL OR v_rake IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_rates', true,
        'error', 'a commission rate and a player rakeback rate must be chosen when granting an agent role');
    END IF;
    IF v_comm < 0 OR v_comm > 0.70 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the commission rate must be between 0 and 0.70');
    END IF;
    IF v_rake < 0 OR v_rake > 0.50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the player rakeback rate must be between 0 and 0.50');
    END IF;
    IF v_rake > v_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the player rakeback rate cannot exceed the commission rate it is paid out of');
    END IF;

    -- Dan, 2026-08-31: "WHEN A AGENT IS PROMOTED ... THEY ALSO NEED TO BE
    -- ASSIGNED 'PRE PAID' OR CREDIT LINE, (AND IF SO, THEN HOW MUCH)".
    -- Before this, every promotion hardcoded credit_limit 0 and left is_prepaid
    -- at its column default of false, which is the one combination that can
    -- send nothing at all: not prepaid, and no line to draw on. Three agents
    -- are in exactly that state on production today.
    IF v_prepaid IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_funding', true,
        'error', 'choose prepaid or a credit line when granting an agent role');
    END IF;
    IF v_prepaid THEN
      IF COALESCE(v_limit, 0) <> 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a prepaid agent carries no credit line, so the limit must be 0');
      END IF;
      v_limit := 0;
    ELSE
      IF v_limit IS NULL THEN
        RETURN jsonb_build_object('success', false, 'needs_funding', true,
          'error', 'a credit agent needs a credit limit');
      END IF;
      IF v_limit <= 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a credit line must be greater than 0, or the agent should be prepaid');
      END IF;
    END IF;

    IF v_set_upline THEN
      SELECT id, commission_rate, player_rakeback_rate, credit_limit
        INTO v_parent, v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents WHERE club_id = p_club_id AND user_id = v_actor;
    ELSIF v_have_row THEN
      SELECT p.commission_rate, p.player_rakeback_rate, p.credit_limit
        INTO v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents a JOIN agents p ON p.id = a.parent_agent_id
       WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    END IF;

    IF v_cap_comm IS NOT NULL AND v_comm > v_cap_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the commission rate cannot exceed the upline rate of ' || v_cap_comm);
    END IF;
    IF v_cap_rake IS NOT NULL AND v_rake > v_cap_rake THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the player rakeback rate cannot exceed the upline rate of ' || v_cap_rake);
    END IF;
    -- An upline cannot lend downward what it does not itself hold.
    IF v_cap_limit IS NOT NULL AND v_limit > v_cap_limit THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the credit limit cannot exceed the upline limit of ' || v_cap_limit);
    END IF;
  END IF;

  PERFORM set_config('app.club_role_change', 'on', true);

  UPDATE club_members
     SET role                = p_role,
         agent_id            = CASE WHEN v_set_upline THEN v_actor ELSE agent_id END,
         player_rakeback_pct = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_pct END,
         rakeback_rate       = CASE WHEN v_is_staff THEN 0 ELSE rakeback_rate END,
         commission_rate     = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
         updated_at          = now()
   WHERE club_id = p_club_id AND user_id = p_user_id;

  PERFORM set_config('app.club_role_change', '', true);

  IF v_is_agent THEN
    SELECT id INTO v_agent_id FROM agents
     WHERE club_id = p_club_id AND user_id = p_user_id;

    IF v_agent_id IS NOT NULL THEN
      UPDATE agents
         SET role = p_role, status = 'active',
             parent_agent_id = COALESCE(v_parent, parent_agent_id),
             commission_rate = v_comm, player_rakeback_rate = v_rake,
             is_prepaid = v_prepaid, credit_limit = v_limit,
             updated_at = now()
       WHERE id = v_agent_id;
    ELSE
      INSERT INTO agents (club_id, user_id, role, status, parent_agent_id,
                          commission_rate, player_rakeback_rate,
                          is_prepaid, credit_limit, credit_used)
      VALUES (p_club_id, p_user_id, p_role, 'active', v_parent, v_comm, v_rake,
              v_prepaid, v_limit, 0)
      RETURNING id INTO v_agent_id;
    END IF;
  ELSE
    -- Suspend the row only when the member can no longer hold a wallet. A
    -- promotion to co-owner or admin used to suspend it too, which contradicted
    -- the rule that staff hold agent wallets and left the club bank funding a
    -- row marked inactive.
    -- Active while they can hold a wallet, suspended when they cannot. Keyed on
    -- the role they are BECOMING, for the same reason the guard above is: a
    -- co-owner demoted to player left an ACTIVE agents row behind, so a player
    -- still read as an agent - fn_player_rakeback_rate joins that row on
    -- status = 'active'.
    UPDATE agents
       SET status = CASE WHEN p_role = 'player' AND v_old_role <> 'player'
                         THEN 'suspended' ELSE status END,
           commission_rate      = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
           player_rakeback_rate = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_rate END,
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = p_user_id;
  END IF;

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id,
                           club_id, before_state, after_state, reason)
  VALUES (v_actor, COALESCE(v_actor_role, 'platform_admin'), 'set_member_role',
          'club_member', p_user_id, p_club_id,
          jsonb_build_object('role', v_old_role),
          jsonb_build_object('role', p_role, 'upline_set', v_set_upline,
                             'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
                             'is_prepaid', v_prepaid, 'credit_limit', v_limit,
                             'funding_rechosen', COALESCE(v_fresh, false)),
          'Role changed via fn_club_set_member_role');

  -- ---------------------------------------------------------------------------
  -- TELL THE PERSON IT HAPPENED
  -- ---------------------------------------------------------------------------
  -- Until now the only announcement was masterBus.emit('MEMBER_ROLE_CHANGED'),
  -- a browser-local event. It reaches the tabs of whoever performed the change
  -- and nobody else, so the person whose role actually changed found out when a
  -- button appeared or vanished. notifications is the estate's real channel:
  -- 11,362 rows, four RLS policies, rendered by NotificationDropdown, the
  -- header store and NotificationsPage.
  --
  -- Failing to notify must never fail the role change. The role is the fact;
  -- the notice is a courtesy, and a courtesy that can roll back a promotion is
  -- worse than no courtesy at all.
  SELECT name INTO v_club_name FROM clubs WHERE id = p_club_id;
  v_label := CASE p_role
               WHEN 'co_owner' THEN 'Co Owner'
               WHEN 'admin' THEN 'Admin'
               WHEN 'super_agent' THEN 'Super Agent'
               WHEN 'agent' THEN 'Agent'
               WHEN 'sub_agent' THEN 'Sub Agent'
               ELSE 'Player'
             END;
  BEGIN
    PERFORM public.fn_raise_notification(
      p_user_id,
      'club_role_changed',
      'Your Role Changed In ' || COALESCE(v_club_name, 'Your Club'),
      'You Are Now ' || v_label || '.'
        || CASE WHEN v_is_agent
                THEN ' Your Commission Is ' || trim(to_char(v_comm * 100, 'FM990.00'))
                     || ' Percent And Your Player Rakeback Is '
                     || trim(to_char(v_rake * 100, 'FM990.00')) || ' Percent.'
                     || CASE WHEN v_prepaid THEN ' You Are Prepaid.'
                             ELSE ' Your Credit Line Is '
                                  || trim(to_char(v_limit, 'FM999,999,999,990.00')) || ' Chips.'
                        END
                ELSE '' END,
      '/clubs/' || p_club_id::text,
      jsonb_build_object(
        'club_id', p_club_id, 'old_role', v_old_role, 'new_role', p_role,
        'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
        'is_prepaid', v_prepaid, 'credit_limit', v_limit));
  EXCEPTION WHEN OTHERS THEN
    -- Swallowed on purpose, and only here. The role change is already durable.
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'old_role', v_old_role, 'new_role', p_role,
    'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
    'is_prepaid', v_prepaid, 'credit_limit', v_limit,
    -- Commission the CLUB owes THEM. It does not block the demotion: the agents
    -- row survives with the figure intact, so nothing is lost by moving the
    -- role, and there is no payout path to send them to yet (phase 6 builds
    -- one). Blocking here would strand the club, not the money. Reported so the
    -- caller can say it out loud rather than discover it later.
    'unclaimed_commission', COALESCE(v_commission, 0),
    'reports_to', CASE WHEN v_set_upline THEN v_actor ELSE NULL END);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_house_board_allows_automation(p_club_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- DERIVED FIRST: the platform club is the house board, and always will be, without anybody
  -- remembering to add it to a list. This is the half that cannot rot.
  SELECT COALESCE((SELECT c.is_platform FROM public.clubs c WHERE c.id = p_club_id), false)
     -- LEGACY, AND IT IS DEBT: four chip house boards that predate clubs.is_platform and carry no
     -- flag of their own. Give them one and these four lines delete themselves.
     OR p_club_id = ANY (ARRAY[
          'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,   -- Club JAQK
          'a0000000-0000-0000-0000-000000000001'::uuid,   -- SHARK CLUB
          'fade0000-0000-0000-0000-000000000001'::uuid,   -- Midway Union
          '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid    -- Deep Stack Society
        ]);
$function$;
CREATE OR REPLACE FUNCTION public.fn_platform_frozen()
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
           SELECT 1
             FROM public.engine_maintenance_break b
            WHERE b.enforce_freeze
              AND b.announced_at < clock_timestamp() + INTERVAL '30 seconds'
              AND (
                (
                  b.phase = 'last_hand'
                  AND b.break_started_at IS NULL
                  AND b.break_ends_at IS NULL
                  AND b.announced_at + INTERVAL '2 minutes' <= clock_timestamp()
                )
                OR (
                  b.phase = 'counting_down'
                  AND b.break_started_at IS NOT NULL
                  AND b.break_ends_at IS NOT NULL
                  AND b.break_started_at >= b.announced_at
                  AND b.break_ends_at > b.break_started_at
                  AND b.break_ends_at < b.announced_at + INTERVAL '15 minutes'
                )
              )
         )
         OR COALESCE(
           public.fn_active_maintenance_release_boundary() > clock_timestamp(),
           false
         );
$function$;
CREATE OR REPLACE FUNCTION public.fn_freeze_bypass_active()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(current_setting('app.freeze_bypass', TRUE), '') = 'on';
$function$;
CREATE OR REPLACE FUNCTION public.fn_managed_game_contract_document(p_kind text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_kind
    WHEN 'table' THEN p_row - ARRAY[
      'current_players', 'status', 'created_at', 'updated_at', 'deleted_at',
      'lifecycle', 'role', 'main_index', 'opened_at', 'live_at',
      'break_started_at', 'break_eligible_since', 'promote_pending',
      'deleted_by', 'is_deleted', 'current_hand_id', 'hand_number',
      'last_activity_at', 'tournament_id', 'engine_instance_id',
      'first_button_seat', 'bomb_pot_manual_pending', 'bomb_pot_sched_state',
      'bomb_pot_next_due_at', 'engine_lease_owner', 'engine_lease_expires_at', 'seat_game_scope', 'seat_admission_key'
    ]::text[]
    WHEN 'tournament' THEN jsonb_strip_nulls(
      jsonb_build_object(
        'id', p_row -> 'id', 'club_id', p_row -> 'club_id',
        'union_id', p_row -> 'union_id', 'name', p_row -> 'name',
        'description', p_row -> 'description',
        'short_description', p_row -> 'short_description',
        'game_type', p_row -> 'game_type', 'variant', p_row -> 'variant',
        'tournament_type', p_row -> 'tournament_type',
        'buy_in_amount', p_row -> 'buy_in_amount',
        'buy_in_fee', p_row -> 'buy_in_fee',
        'starting_chips', p_row -> 'starting_chips',
        'max_players', p_row -> 'max_players',
        'min_players', p_row -> 'min_players',
        'blind_structure', p_row -> 'blind_structure',
        'payout_structure', p_row -> 'payout_structure',
        'payout_percent', p_row -> 'payout_percent',
        'payout_math_version', CASE WHEN p_row->>'payout_math_version'='2' THEN p_row->'payout_math_version' END,
        'payout_unit_cents', CASE WHEN p_row->>'payout_math_version'='2' THEN p_row->'payout_unit_cents' END,
        'guaranteed_prize', p_row -> 'guaranteed_prize'
      ) || jsonb_build_object(
        'late_reg_levels', p_row -> 'late_reg_levels',
        'late_reg_mins', p_row -> 'late_reg_mins',
        'rebuy_levels', p_row -> 'rebuy_levels',
        'start_time', p_row -> 'start_time',
        'is_rebuy', p_row -> 'is_rebuy',
        'is_reentry', p_row -> 'is_reentry',
        'rebuy_cost', p_row -> 'rebuy_cost',
        'rebuy_chips', p_row -> 'rebuy_chips',
        'max_rebuys', p_row -> 'max_rebuys',
        'max_reentries', p_row -> 'max_reentries',
        'free_buy', p_row -> 'free_buy',
        'add_on_available', p_row -> 'add_on_available',
        'addon_from_start', p_row -> 'addon_from_start',
        'addon_cost', p_row -> 'addon_cost',
        'addon_chips', p_row -> 'addon_chips',
        'addon_levels', p_row -> 'addon_levels',
        'addon_break_minutes', p_row -> 'addon_break_minutes'
      ) || jsonb_build_object(
        'is_bounty', p_row -> 'is_bounty',
        'bounty_amount', p_row -> 'bounty_amount',
        'is_pko', p_row -> 'is_pko',
        'is_mystery_bounty', p_row -> 'is_mystery_bounty',
        'mystery_bounty_min', p_row -> 'mystery_bounty_min',
        'mystery_bounty_max', p_row -> 'mystery_bounty_max',
        'mystery_bounty_profile', p_row -> 'mystery_bounty_profile',
        'mystery_bounty_activation', p_row -> 'mystery_bounty_activation',
        'mystery_bounty_activation_value', p_row -> 'mystery_bounty_activation_value',
        'mystery_bounty_pool_percent', p_row -> 'mystery_bounty_pool_percent',
        'mystery_bounty_regular_pool_percent', p_row -> 'mystery_bounty_regular_pool_percent',
        'mystery_bounty_top_percent', p_row -> 'mystery_bounty_top_percent',
        'spin_type', p_row -> 'spin_type',
        'satellite_target_id', p_row -> 'satellite_target_id',
        'satellite_target', p_row -> 'satellite_target',
        'satellite_seats', p_row -> 'satellite_seats'
      ) || jsonb_build_object(
        'is_xmtt', p_row -> 'is_xmtt',
        'is_private', p_row -> 'is_private',
        'is_vip_only', p_row -> 'is_vip_only',
        'ban_chat', p_row -> 'ban_chat',
        'all_in_or_fold', p_row -> 'all_in_or_fold',
        'label_as_new', p_row -> 'label_as_new',
        'hide_club_name', p_row -> 'hide_club_name',
        'action_time_seconds', p_row -> 'action_time_seconds',
        'table_size', p_row -> 'table_size',
        'accelerated_mtt', p_row -> 'accelerated_mtt',
        'big_blind_ante', p_row -> 'big_blind_ante',
        'authorized_to_register', p_row -> 'authorized_to_register',
        'early_bird_enabled', p_row -> 'early_bird_enabled',
        'early_bird_chips', p_row -> 'early_bird_chips',
        'bubble_protection', p_row -> 'bubble_protection',
        'final_table_deal_enabled', p_row -> 'final_table_deal_enabled',
        'restart_every_minutes', p_row -> 'restart_every_minutes',
        'synchronized_breaks', p_row -> 'synchronized_breaks'
      ) || jsonb_build_object(
        'is_multi_day', p_row -> 'is_multi_day',
        'total_days', p_row -> 'total_days',
        'is_pinned', p_row -> 'is_pinned',
        'schedule_id', p_row -> 'schedule_id'
      )
    )
    ELSE '{}'::jsonb
  END
$function$;
CREATE OR REPLACE FUNCTION public.fn_managed_game_contract_hash(p_contract jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT encode(extensions.digest(convert_to(p_contract::text, 'UTF8'), 'sha256'), 'hex')
$function$;
CREATE OR REPLACE FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_recipient_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope_kind text; v_scope_id uuid; v_union_id uuid;
BEGIN
  IF p_union_id IS NOT NULL THEN
    v_scope_kind := 'union'; v_scope_id := p_union_id; v_union_id := p_union_id;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT s.scope_kind,s.scope_id,s.union_id
      INTO v_scope_kind,v_scope_id,v_union_id
      FROM public.fn_game_management_scope(p_club_id) s;
  END IF;
  INSERT INTO public.game_management_events(
    event_type,scope_kind,scope_id,club_id,union_id,recipient_id,
    entity_type,entity_id,command_id,actor_id,payload
  ) VALUES (
    p_event_type,v_scope_kind,v_scope_id,p_club_id,v_union_id,p_recipient_id,
    p_entity_type,p_entity_id,p_command_id,auth.uid(),COALESCE(p_payload,'{}'::jsonb)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text DEFAULT 'admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_asset text := lower(btrim(COALESCE(p_asset, '')));
  v_dest  text := lower(btrim(COALESCE(p_destination, '')));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_class text := lower(btrim(COALESCE(p_class, 'admin')));
  v_holder uuid;
  v_prior jsonb; v_before numeric; v_after numeric; v_label text;
  v_supply numeric; v_chip_id uuid; v_dia_id uuid; v_actorlb text; v_result jsonb;
  v_pol public.ca_mint_policy%ROWTYPE;
  v_cap numeric; v_roll numeric; v_24h numeric;
BEGIN
  -- The trigger door (2026-09-08, DIAMOND-RULINGS 17 / roadmap 1.3): handle_new_user and the
  -- other seeders fire inside a trigger owned by the database itself, where auth.role() is
  -- NULL. The database's own code may mint; a browser never reaches this branch because a
  -- SECURITY DEFINER trigger runs as the owner and a client session is never at depth > 0.
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND NOT (pg_trigger_depth() > 0
              AND current_user IN ('postgres', 'supabase_admin', 'supabase_auth_admin')) THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;

  IF v_asset NOT IN ('chips', 'diamonds') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'asset_must_be_chips_or_diamonds');
  END IF;
  IF v_asset = 'chips' AND v_dest NOT IN ('club', 'union') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chips_are_issued_to_a_club_or_union_wallet_only');
  END IF;
  IF v_asset = 'diamonds' AND v_dest NOT IN ('player', 'house') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_issued_to_a_player_or_to_the_house_only');
  END IF;
  -- The foundation's issuance_class list (diamond_transactions_issuance_class_chk).
  -- Recorded on the diamond journal row; carried but unused for chips, which have
  -- their own ledger.
  IF v_class NOT IN ('purchased', 'promotional', 'earned', 'transferred', 'seeded',
                     'refund', 'spend', 'bridge', 'deletion', 'admin', 'arena',
                     'house', 'unknown') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_issuance_class', 'class', v_class);
  END IF;
  IF v_asset = 'diamonds' AND v_dest = 'house' THEN
    IF p_target_id IS NOT NULL AND p_target_id <> c_house THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_house_target_is_the_house_sentinel_or_null');
    END IF;
  ELSIF p_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_to_two_decimals');
  END IF;
  IF v_asset = 'diamonds' AND p_amount <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_whole_numbers');
  END IF;
  -- Kill switch (standard 3.4 layer 6, review D11): a human-opened diamond_issuance freeze
  -- refuses diamond minting until it is cleared. Burns and chips are untouched.
  IF v_asset = 'diamonds' AND EXISTS (SELECT 1 FROM public.ca_payout_freeze f
                                        WHERE f.scope = 'diamond_issuance' AND f.cleared_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamond_issuance_frozen');
  END IF;
  -- THE POLICY (ca_mint_policy): a per-operation cap and a rolling 24-hour
  -- ceiling, both refused here with a reason the operator can read, and
  -- refused again at commit by the constraint trigger for chips whatever the
  -- door. 24h issuance is read from the register with the advisory lock held
  -- below, so two operators cannot both fit under the ceiling at once.
  SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
  v_cap  := CASE WHEN v_asset = 'chips' THEN v_pol.per_operation_cap_chips ELSE v_pol.per_operation_cap_diamonds END;
  v_roll := CASE WHEN v_asset = 'chips' THEN v_pol.rolling_24h_cap_chips ELSE v_pol.rolling_24h_cap_diamonds END;
  IF p_amount > v_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_over_the_single_mint_cap',
                              'cap', v_cap, 'requested', p_amount);
  END IF;
  IF length(v_reason) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'issuance_needs_a_real_reason');
  END IF;
  IF COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_key_required');
  END IF;

  SELECT result INTO v_prior FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  END IF;
  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_ca_mint', v_actor);

  PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:' || v_asset));

  v_24h := public.fn_ca_mint_issued_24h(v_asset) + p_amount;
  IF v_24h > v_roll THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'over_the_rolling_24h_issuance_ceiling',
                              'ceiling', v_roll, 'issued_24h', v_24h - p_amount, 'requested', p_amount);
  END IF;

  IF v_asset = 'diamonds' THEN
    IF v_dest = 'house' THEN
      INSERT INTO public.ca_diamond_house (id, balance)
      VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
      SELECT COALESCE(balance, 0) INTO v_before
        FROM public.ca_diamond_house WHERE id = 1 FOR UPDATE;
      UPDATE public.ca_diamond_house
         SET balance = COALESCE(balance, 0) + p_amount, updated_at = now()
       WHERE id = 1 RETURNING balance INTO v_after;
      v_label  := 'the house';
      v_holder := c_house;
      -- No diamond_transactions row: that journal is keyed by a user (two FKs to
      -- auth.users and profiles) and the house is not one. ca_mint_ledger is the
      -- record of a house-side issuance.
    ELSE
      SELECT COALESCE(diamonds, 0), COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
        INTO v_before, v_label FROM public.profiles WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'player_not_found');
      END IF;
      UPDATE public.profiles SET diamonds = COALESCE(diamonds, 0) + p_amount
       WHERE id = p_target_id RETURNING diamonds INTO v_after;
      -- The op id is the journal reference (DR4: a credit carries its reference), so the earn
      -- ledger files a promotional mint under its engine by prefix (signup: -> signup).
      INSERT INTO public.diamond_transactions
        (user_id, type, transaction_type, amount, balance_after, description, source,
         metadata, counterparty, issuance_class, reference_id)
      VALUES (p_target_id, 'earn', 'mint', p_amount, v_after,
              'The Mint: ' || v_reason, 'the_mint',
              jsonb_build_object('minted_by', v_actor, 'op_id', p_op_id),
              'issuance', v_class, p_op_id)
      RETURNING id INTO v_dia_id;
      v_holder := p_target_id;
    END IF;
  ELSE
    -- The leg is declared WITH A KEY and found by that key: never by shape.
    PERFORM public.fn_ca_declare_ledger('mint', 'issuance_reserve', NULL, NULL, 'mint:' || p_op_id, NULL);
    IF v_dest = 'club' THEN
      SELECT COALESCE(chip_treasury, 0), name INTO v_before, v_label
        FROM public.clubs WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
      END IF;
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount
       WHERE id = p_target_id RETURNING chip_treasury INTO v_after;
      INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
      VALUES (p_target_id, v_actor, NULL, p_amount, 'treasury_mint',
              'The Mint: ' || v_reason, v_after);
    ELSE
      SELECT name INTO v_label FROM public.unions WHERE id = p_target_id;
      IF v_label IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'union_not_found');
      END IF;
      INSERT INTO public.union_wallets (union_id, created_at, updated_at)
      VALUES (p_target_id, now(), now()) ON CONFLICT (union_id) DO NOTHING;
      SELECT COALESCE(chip_balance, 0) INTO v_before
        FROM public.union_wallets WHERE union_id = p_target_id FOR UPDATE;
      UPDATE public.union_wallets
         SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
       WHERE union_id = p_target_id RETURNING chip_balance INTO v_after;
    END IF;
    SELECT id INTO v_chip_id FROM public.chip_ledger WHERE idempotency_key = 'mint:' || p_op_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_idempotency_key', '', true);
    IF v_chip_id IS NULL THEN
      RAISE EXCEPTION 'fn_ca_mint: the balance moved but no journal leg was written for key mint:% - refusing to register an issuance the journal does not carry', p_op_id;
    END IF;
    v_holder := p_target_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = v_asset;
  SELECT COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
    INTO v_actorlb FROM public.profiles WHERE id = v_actor;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id)
  VALUES
    (p_op_id, 'mint', v_asset, v_dest, v_holder, v_label, p_amount,
     v_before, v_after, v_supply, v_reason, v_actor, v_actorlb, v_chip_id, v_dia_id);

  v_result := jsonb_build_object(
    'ok', true, 'replayed', false, 'action', 'mint',
    'asset', v_asset, 'destination', v_dest, 'issuance_class', v_class,
    'target_id', v_holder, 'target_label', v_label, 'amount', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'supply_after', v_supply,
    'ledger_id', v_chip_id, 'issued_24h_after', v_24h, 'rolling_24h_cap', v_roll,
    'minted_by', v_actor, 'reason', v_reason, 'op_id', p_op_id);

  UPDATE public.ca_op_claims SET result = v_result, finalized_at = now()
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_apply_club_ladder(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_members integer;
  v_level   smallint;
  v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_club_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club_id) THEN RETURN; END IF;

  SELECT public.fn_get_club_realtime_member_count(p_club_id) INTO v_members;
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(*) FILTER (WHERE role IN ('admin','manager')),
         count(*) FILTER (WHERE role = 'super_agent'),
         count(*) FILTER (WHERE role IN ('agent','sub_agent'))
    INTO v_admins, v_supers, v_agents
    FROM public.club_members
   WHERE club_id = p_club_id
     AND (status IS NULL OR status IN ('active','approved'));
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.clubs SET
    member_count               = v_members,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    admin_count                = v_admins,
    super_agent_count          = v_supers,
    agent_count                = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_club_id
    AND (member_count IS DISTINCT FROM v_members
      OR level IS DISTINCT FROM v_level
      OR player_level IS DISTINCT FROM v_level
      OR admin_count IS DISTINCT FROM v_admins
      OR super_agent_count IS DISTINCT FROM v_supers
      OR agent_count IS DISTINCT FROM v_agents
      OR player_threshold_current IS DISTINCT FROM public.fn_club_level_min_members(v_level)
      OR player_threshold_next IS DISTINCT FROM public.fn_club_level_min_members(v_level + 1));
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_apply_union_ladder(p_union_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_members bigint;
  v_level   smallint;
  v_clubs integer; v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_union_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.unions WHERE id = p_union_id) THEN RETURN; END IF;

  SELECT member_count INTO v_members
    FROM public.fn_batch_union_realtime_member_counts(ARRAY[p_union_id]);
  v_members := COALESCE(v_members, 0);
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(DISTINCT uc.club_id),
         COALESCE(sum(c.admin_count), 0),
         COALESCE(sum(c.super_agent_count), 0),
         COALESCE(sum(c.agent_count), 0)
    INTO v_clubs, v_admins, v_supers, v_agents
    FROM public.union_clubs uc
    JOIN public.clubs c ON c.id = uc.club_id
   WHERE uc.union_id = p_union_id;
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.unions SET
    member_count               = v_members,
    total_players              = v_members,
    club_count                 = v_clubs,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    total_admins               = v_admins,
    total_super_agents         = v_supers,
    total_agents               = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_union_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ca_hand_player_facts_one(p_hand_id uuid, p_user uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, hand_id uuid, created_at timestamp with time zone, is_cash boolean, tournament_id uuid, game_variant text, big_blind numeric, small_blind numeric, n_players integer, seat_position text, my_blind numeric, won_amt numeric, is_winner boolean, invested_actions numeric, aggro_cnt integer, call_cnt integer, vpip boolean, pfr boolean, folded boolean, three_bet boolean, three_bet_opp boolean, faced_three_bet boolean, folded_to_three_bet boolean, cbet_opp boolean, cbet_made boolean, showdown boolean, hand_secs numeric, profit numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH my_hands AS MATERIALIZED (
  SELECT h.id, h.tournament_id,
         lower(coalesce(h.game_variant, 'nlh')) AS game_variant,
         coalesce(h.big_blind, 0)::numeric   AS big_blind,
         coalesce(h.small_blind, 0)::numeric AS small_blind,
         coalesce(h.pot_size, 0)::numeric    AS pot_size,
         h.button_seat, h.created_at, h.started_at, h.ended_at,
         h.players,
         coalesce(h.actions, '[]'::jsonb) AS actions,
         coalesce(h.winners, '[]'::jsonb) AS winners
  FROM hand_history h
  WHERE h.id = p_hand_id
),
acts AS MATERIALIZED (
  SELECT mh.id AS hand_id, x.ord,
         x.act->>'userId' AS auid, x.act->>'stage' AS stage,
         lower(x.act->>'action') AS action,
         coalesce((x.act->>'amount')::numeric, 0) AS amount,
         coalesce((x.act->>'dead')::boolean, false) AS dead_flag
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.actions) WITH ORDINALITY x(act, ord)
),
players_all AS (
  SELECT mh.id AS hand_id, pl->>'userId' AS puid, (pl->>'seat')::int AS seat
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.players) pl
),
seatmap AS (
  SELECT hand_id, array_agg(seat ORDER BY seat) AS seats
  FROM players_all GROUP BY hand_id
),
-- The ONLY thing p_user narrows.
seated AS (
  SELECT hand_id, puid::uuid AS uid, seat AS my_seat
  FROM players_all
  WHERE puid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    AND (p_user IS NULL OR puid = p_user::text)
),
folders AS (
  SELECT DISTINCT hand_id, auid FROM acts WHERE action = 'fold' AND auid IS NOT NULL
),
no_fold AS (
  SELECT p.hand_id,
         count(*) FILTER (WHERE f.auid IS NULL AND p.puid IS NOT NULL) AS no_fold_players
  FROM players_all p
  LEFT JOIN folders f ON f.hand_id = p.hand_id AND f.auid = p.puid
  GROUP BY p.hand_id
),
pf_raise AS (
  SELECT hand_id, ord, auid FROM acts
  WHERE stage = 'preflop' AND action IN ('raise','all_in','allin')
),
pf_ranked AS (
  SELECT hand_id, ord, auid,
         first_value(auid) OVER w AS first_actor,
         first_value(ord)  OVER w AS first_ord,
         last_value(auid)  OVER (PARTITION BY hand_id ORDER BY ord
                                 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_actor
  FROM pf_raise
  WINDOW w AS (PARTITION BY hand_id ORDER BY ord)
),
hand_pf AS (
  SELECT hand_id,
         min(first_ord)   AS first_ord,
         min(first_actor) AS first_actor,
         min(last_actor)  AS last_pf_raiser,
         min(ord) FILTER (WHERE auid IS DISTINCT FROM first_actor) AS first_other_ord
  FROM pf_ranked GROUP BY hand_id
),
flop_first AS (
  SELECT DISTINCT ON (hand_id) hand_id, auid AS first_flop_bettor
  FROM acts WHERE stage = 'flop' AND action IN ('bet','all_in','allin')
  ORDER BY hand_id, ord
),
-- ── MONEY. actions[].amount is NOT one unit (src/utils/handReplay.ts:16-35):
--    bet / raise / all_in  -> raise-TO level for the street (CUMULATIVE)
--    call, blind posts     -> chips actually added           (INCREMENTAL)
--    return                -> uncalled chips handed back     (SUBTRACT)
--    ante (or dead=true)   -> in the pot, NOT in the live bet level
-- Computed for EVERY seat in the hand, not just p_user: the uncalled-bet
-- inference below needs the whole table's bet levels.
money_acts AS (
  SELECT a.hand_id, a.auid, a.stage, a.ord, a.amount,
         CASE
           WHEN a.action IN ('bet','raise','all_in','allin') THEN 'to'
           WHEN a.action = 'return' THEN 'ret'
           WHEN a.action IN ('call','sb','bb','post','post_sb','post_bb','blind',
                             'small_blind','big_blind','straddle','ante') THEN 'inc'
           ELSE 'none'
         END AS kind,
         (a.dead_flag OR a.action = 'ante') AS dead,
         a.action IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind') AS is_blind_post
  FROM acts a
  WHERE a.auid IS NOT NULL
),
hand_log_shape AS (
  SELECT hand_id,
         bool_or(is_blind_post) AS has_posts,
         bool_or(kind = 'ret')  AS has_returns
  FROM money_acts GROUP BY hand_id
),
-- Position-implied blind for every seat (the rows written before
-- FORCED_BETS_POSTED carry no post rows, so the blinds have to be synthesised
-- exactly as src/utils/handReplay.ts does when !logHasBlinds).
seat_blind AS (
  SELECT p.hand_id, p.puid AS auid, p.seat,
         CASE
           WHEN ofs.pos_offset IS NULL THEN 0
           WHEN array_length(sm.seats, 1) = 2 THEN
             CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
           WHEN ofs.pos_offset = 1 THEN mh.small_blind
           WHEN ofs.pos_offset = 2 THEN mh.big_blind
           ELSE 0
         END AS implied_blind
  FROM players_all p
  JOIN my_hands mh ON mh.id = p.hand_id
  JOIN seatmap sm ON sm.hand_id = p.hand_id
  CROSS JOIN LATERAL (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR p.seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, p.seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
  WHERE p.puid IS NOT NULL
),
money_w AS (
  SELECT m.*,
         max(ord) FILTER (WHERE kind = 'to')
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_to_ord,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND NOT dead)
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 0) AS inc_cum,
         row_number() OVER (PARTITION BY hand_id, auid, stage ORDER BY ord DESC) AS rn_desc
  FROM money_acts m
),
street_committed_raw AS (
  SELECT w.hand_id, w.auid, w.stage,
         CASE WHEN w.last_to_ord IS NULL THEN w.inc_cum
              ELSE t.amount + (w.inc_cum - t.inc_cum) END AS committed,
         (w.last_to_ord IS NOT NULL) AS to_level
  FROM money_w w
  LEFT JOIN money_w t ON t.hand_id = w.hand_id AND t.auid = w.auid
                     AND t.stage = w.stage AND t.ord = w.last_to_ord
  WHERE w.rn_desc = 1
),
-- Seed the blinds into preflop when the log has no post rows. A player whose
-- preflop bet level is a raise-TO already has the blind inside it.
street_committed AS (
  SELECT r.hand_id, r.auid, r.stage,
         r.committed
           + CASE WHEN r.stage = 'preflop' AND NOT r.to_level AND NOT coalesce(hs.has_posts, false)
                  THEN coalesce(sb.implied_blind, 0) ELSE 0 END AS committed
  FROM street_committed_raw r
  LEFT JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  LEFT JOIN seat_blind sb ON sb.hand_id = r.hand_id AND sb.auid = r.auid
  UNION ALL
  -- Blind seats that never acted (walk, or a fold with no logged row).
  SELECT sb.hand_id, sb.auid, 'preflop', sb.implied_blind
  FROM seat_blind sb
  LEFT JOIN hand_log_shape hs ON hs.hand_id = sb.hand_id
  LEFT JOIN street_committed_raw r
         ON r.hand_id = sb.hand_id AND r.auid = sb.auid AND r.stage = 'preflop'
  WHERE sb.implied_blind > 0
    AND NOT coalesce(hs.has_posts, false)
    AND r.hand_id IS NULL
),
-- An uncalled bet on a log that does not record returns: the street's top
-- contributor's excess over the next highest was matched by nobody.
street_rank AS (
  SELECT sc.hand_id, sc.stage, sc.auid, sc.committed,
         row_number() OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS rn,
         lead(sc.committed) OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS next_committed
  FROM street_committed sc
),
inferred_ret AS (
  SELECT r.hand_id, r.auid,
         sum(r.committed - coalesce(r.next_committed, 0)) AS inferred
  FROM street_rank r
  JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  WHERE r.rn = 1 AND NOT hs.has_returns
    AND r.committed - coalesce(r.next_committed, 0) > 0.005
  GROUP BY r.hand_id, r.auid
),
money_extras AS (
  SELECT hand_id, auid,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND dead), 0) AS dead_money,
         coalesce(sum(amount) FILTER (WHERE kind = 'ret'), 0) AS returned,
         coalesce(sum(amount) FILTER (WHERE is_blind_post AND NOT dead), 0) AS posted_blind
  FROM money_acts GROUP BY hand_id, auid
),
money_per_player AS (
  SELECT sc.hand_id, sc.auid,
         sum(sc.committed) AS live_committed
  FROM street_committed sc GROUP BY sc.hand_id, sc.auid
),
-- THE STORED POT ARBITRATES THE INFERENCE (handReplay.ts, same rule): if the
-- rebuild WITH inferred returns misses pot_size and the rebuild WITHOUT them
-- lands on it, the inference was wrong for this hand and is withdrawn.
--
-- Per-hand totals are GROUPed once and joined, never re-scanned per hand:
-- the correlated form this replaced walked the whole CTE for every hand,
-- which is quadratic in the window and is why the range form took 10 s for
-- four minutes of hands (2026-09-04). Same numbers, hash joins.
pot_live AS (
  SELECT hand_id, sum(live_committed) AS s FROM money_per_player GROUP BY hand_id
),
pot_extras AS (
  SELECT hand_id, sum(dead_money - returned) AS s FROM money_extras GROUP BY hand_id
),
pot_inferred AS (
  SELECT hand_id, sum(inferred) AS s FROM inferred_ret GROUP BY hand_id
),
hand_pot_check AS (
  SELECT mh.id AS hand_id,
         mh.pot_size,
         coalesce(pl.s, 0) + coalesce(px.s, 0) AS pot_without,
         coalesce(pi.s, 0) AS inferred_total
  FROM my_hands mh
  LEFT JOIN pot_live     pl ON pl.hand_id = mh.id
  LEFT JOIN pot_extras   px ON px.hand_id = mh.id
  LEFT JOIN pot_inferred pi ON pi.hand_id = mh.id
),
inference_ok AS (
  SELECT hand_id,
         NOT (inferred_total > 0
              AND abs((pot_without - inferred_total) - pot_size) >= 0.02
              AND abs(pot_without - pot_size) < 0.02) AS use_inference
  FROM hand_pot_check
),
per_player_base AS (
  SELECT s.hand_id, s.uid, s.my_seat,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('call','bet','raise','all_in','allin')), false) AS vpip,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')), false) AS pfr,
    count(*) FILTER (WHERE a.action IN ('bet','raise','all_in','allin'))::int AS aggro_cnt,
    count(*) FILTER (WHERE a.action = 'call')::int AS call_cnt,
    coalesce(bool_or(a.action = 'fold'), false) AS folded,
    coalesce(bool_or(a.stage = 'flop'), false) AS acted_on_flop,
    min(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_first_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_last_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action NOT IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind','ante','straddle','return')) AS my_last_pf_any,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action = 'fold') AS my_last_pf_fold
  FROM seated s
  LEFT JOIN acts a ON a.hand_id = s.hand_id AND a.auid = s.uid::text
  GROUP BY s.hand_id, s.uid, s.my_seat
),
with_first_other AS (
  SELECT b.*,
    CASE WHEN hp.first_actor IS DISTINCT FROM b.uid::text
         THEN hp.first_ord ELSE hp.first_other_ord END AS first_other_pf_raise,
    hp.last_pf_raiser
  FROM per_player_base b
  LEFT JOIN hand_pf hp ON hp.hand_id = b.hand_id
),
reraise AS (
  SELECT b.hand_id, b.uid, min(p.ord) AS reraise_after_me
  FROM with_first_other b
  JOIN pf_raise p ON p.hand_id = b.hand_id
  WHERE p.auid IS DISTINCT FROM b.uid::text AND p.ord > b.my_first_pf_raise
  GROUP BY b.hand_id, b.uid
)
SELECT
  d.uid, mh.id, mh.created_at,
  (mh.tournament_id IS NULL), mh.tournament_id, mh.game_variant,
  mh.big_blind, mh.small_blind, array_length(sm.seats, 1),
  pos.seat_position,
  -- my_blind: what the log says was posted when it says anything, else the
  -- blind the position implies (rows written before FORCED_BETS_POSTED).
  inv.my_blind,
  w.won_amt, w.is_winner,
  -- invested_actions EXCLUDES the blind above, so `invested_actions + my_blind`
  -- keeps meaning "everything this seat put in", as every reader assumes.
  inv.total_invested - inv.my_blind,
  d.aggro_cnt, d.call_cnt, d.vpip, d.pfr, d.folded,
  coalesce(d.my_last_pf_raise > d.first_other_pf_raise, false),
  coalesce(d.my_last_pf_any   > d.first_other_pf_raise, false),
  (r.reraise_after_me IS NOT NULL),
  coalesce(d.my_last_pf_fold > r.reraise_after_me, false),
  coalesce(d.last_pf_raiser = d.uid::text AND d.acted_on_flop, false),
  coalesce(d.last_pf_raiser = d.uid::text AND ff.first_flop_bettor = d.uid::text, false),
  (NOT d.folded AND nf.no_fold_players >= 2),
  CASE
    WHEN mh.started_at IS NOT NULL AND mh.ended_at IS NOT NULL
    THEN GREATEST(0, LEAST(1800, EXTRACT(epoch FROM (mh.ended_at - mh.started_at))))::numeric
    ELSE 45
  END,
  (w.won_amt - inv.total_invested)
FROM with_first_other d
JOIN my_hands mh ON mh.id = d.hand_id
JOIN seatmap  sm ON sm.hand_id = d.hand_id
JOIN no_fold  nf ON nf.hand_id = d.hand_id
LEFT JOIN reraise    r  ON r.hand_id  = d.hand_id AND r.uid = d.uid
LEFT JOIN flop_first ff ON ff.hand_id = d.hand_id
LEFT JOIN money_per_player mp ON mp.hand_id = d.hand_id AND mp.auid = d.uid::text
LEFT JOIN money_extras     mx ON mx.hand_id = d.hand_id AND mx.auid = d.uid::text
LEFT JOIN inferred_ret     ir ON ir.hand_id = d.hand_id AND ir.auid = d.uid::text
LEFT JOIN hand_log_shape   hs ON hs.hand_id = d.hand_id
LEFT JOIN inference_ok     io ON io.hand_id = d.hand_id
CROSS JOIN LATERAL (
  SELECT
    coalesce(sum((w1->>'amount')::numeric) FILTER (WHERE w1->>'userId' = d.uid::text), 0) AS won_amt,
    count(*) FILTER (WHERE w1->>'userId' = d.uid::text) > 0 AS is_winner
  FROM jsonb_array_elements(mh.winners) w1
) w
CROSS JOIN LATERAL (
  SELECT
    CASE
      WHEN ofs.pos_offset IS NULL THEN 0
      WHEN array_length(sm.seats, 1) = 2 THEN
        CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
      WHEN ofs.pos_offset = 1 THEN mh.small_blind
      WHEN ofs.pos_offset = 2 THEN mh.big_blind
      ELSE 0
    END AS my_blind,
    CASE
      WHEN ofs.pos_offset IS NULL THEN 'UNK'
      WHEN array_length(sm.seats, 1) = 2 THEN CASE WHEN ofs.pos_offset = 0 THEN 'BTN' ELSE 'BB' END
      WHEN ofs.pos_offset = 0 THEN 'BTN'
      WHEN ofs.pos_offset = 1 THEN 'SB'
      WHEN ofs.pos_offset = 2 THEN 'BB'
      WHEN ofs.pos_offset = array_length(sm.seats, 1) - 1 THEN 'CO'
      WHEN ofs.pos_offset = 3 THEN 'UTG'
      WHEN ofs.pos_offset = 4 AND array_length(sm.seats, 1) >= 8 THEN 'UTG+1'
      ELSE 'MP'
    END AS seat_position
  FROM (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR d.my_seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, d.my_seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
) pos
CROSS JOIN LATERAL (
  -- Everything this seat put in: live bet levels per street (blinds seeded
  -- when the log has no post rows), plus dead money, minus what came back -
  -- recorded, or inferred when the log predates recorded returns.
  SELECT coalesce(mp.live_committed, 0)
       + coalesce(mx.dead_money, 0)
       - coalesce(mx.returned, 0)
       - CASE WHEN coalesce(io.use_inference, true) THEN coalesce(ir.inferred, 0) ELSE 0 END AS total_invested,
         CASE WHEN coalesce(hs.has_posts, false) THEN coalesce(mx.posted_blind, 0) ELSE pos.my_blind END AS my_blind
) inv;
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_management_readiness_for_row(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid := NULLIF(p_row ->> 'id', '')::uuid;
  v_club uuid := NULLIF(p_row ->> 'club_id', '')::uuid;
  v_row_union uuid := NULLIF(p_row ->> 'union_id', '')::uuid;
  v_union uuid;
  v_private boolean := COALESCE((p_row ->> 'is_private')::boolean, false);
  v_enforce boolean;
  v_floor numeric;
  v_bank numeric;
  v_bank_type text;
  v_exposure numeric;
  v_guaranteed numeric := COALESCE(NULLIF(p_row ->> 'guaranteed_prize', '')::numeric, 0);
  v_pool numeric := COALESCE(NULLIF(p_row ->> 'prize_pool', '')::numeric, 0);
  v_effective_guarantee numeric;
  v_seat_guarantee numeric := 0;
  v_required numeric;
  v_short numeric;
  v_locked boolean;
  v_complete boolean;
  v_status text := upper(COALESCE(p_row ->> 'status', ''));
  v_variant text := lower(COALESCE(p_row ->> 'variant', ''));
  v_tournament_type text := upper(COALESCE(p_row ->> 'tournament_type', ''));
  v_target uuid := COALESCE(
    NULLIF(p_row ->> 'satellite_target_id', ''),
    NULLIF(p_row ->> 'satellite_target', '')
  )::uuid;
  v_satellite_seats integer := COALESCE(
    NULLIF(p_row ->> 'satellite_seats', '')::integer,
    0
  );
  v_is_satellite boolean := v_variant = 'satellite'
    OR v_tournament_type = 'SATELLITE'
    OR v_target IS NOT NULL;
  v_target_found boolean := false;
  v_blinds jsonb;
  v_payouts jsonb;
BEGIN
  IF v_id IS NULL OR v_club IS NULL THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  SELECT COALESCE(c.guarantee_enforcement_enabled, true),
         COALESCE(c.guarantee_treasury_floor, 0)
    INTO v_enforce, v_floor
    FROM public.clubs c
   WHERE c.id = v_club;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  v_union := CASE WHEN v_private THEN NULL ELSE v_row_union END;

  IF v_is_satellite AND v_satellite_seats > 0 AND v_target IS NOT NULL THEN
    SELECT round(
             (COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0))
             * v_satellite_seats,
             2
           )
      INTO v_seat_guarantee
      FROM public.tournaments t
     WHERE t.id = v_target;
    v_target_found := FOUND;
    v_seat_guarantee := COALESCE(v_seat_guarantee, 0);
  END IF;

  v_effective_guarantee := greatest(v_guaranteed, v_seat_guarantee);

  IF v_union IS NOT NULL THEN
    v_bank_type := 'union';
    v_floor := 0;
    SELECT COALESCE(uw.chip_balance, 0)
      INTO v_bank
      FROM public.union_wallets uw
     WHERE uw.union_id = v_union;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.union_id = v_union
       AND NOT COALESCE(t.is_private, false)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  ELSE
    v_bank_type := 'club';
    SELECT COALESCE(c.chip_treasury, 0)
      INTO v_bank
      FROM public.clubs c
     WHERE c.id = v_club;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.club_id = v_club
       AND (COALESCE(t.is_private, false) OR t.union_id IS NULL)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  END IF;

  v_required := greatest(v_effective_guarantee - v_pool, 0);
  v_short := greatest(
    COALESCE(v_floor, 0) + COALESCE(v_exposure, 0) + v_required - v_bank,
    0
  );
  v_locked := EXISTS (
    SELECT 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = v_id
  );

  v_blinds := CASE
    WHEN jsonb_typeof(p_row -> 'blind_structure') = 'array'
      THEN p_row -> 'blind_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'blind_structure')
  END;
  v_payouts := CASE
    WHEN jsonb_typeof(p_row -> 'payout_structure') = 'array'
      THEN p_row -> 'payout_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'payout_structure')
  END;

  v_complete := NULLIF(trim(COALESCE(p_row ->> 'name', '')), '') IS NOT NULL
    AND (
      NULLIF(p_row ->> 'start_time', '') IS NOT NULL
      OR v_tournament_type IN ('SNG', 'SPIN')
      OR v_variant IN ('sng', 'spin')
    )
    AND COALESCE(NULLIF(p_row ->> 'starting_chips', '')::numeric, 0) > 0
    AND COALESCE(NULLIF(p_row ->> 'max_players', '')::integer, 0) >= 2
    AND COALESCE(NULLIF(p_row ->> 'buy_in_amount', '')::numeric, 0) >= 0
    AND jsonb_array_length(v_blinds) > 0
    AND (
      jsonb_array_length(v_payouts) > 0
      OR v_tournament_type = 'SPIN'
      OR v_variant = 'spin'
    )
    AND (
      NOT v_is_satellite
      OR (v_satellite_seats > 0 AND v_target IS NOT NULL AND v_target_found)
    );

  RETURN jsonb_build_object(
    'state', CASE
      WHEN v_status IN ('COMPLETED', 'CANCELLED', 'CANCELED') THEN 'closed'
      WHEN NOT v_complete THEN 'incomplete'
      WHEN v_enforce AND v_short > 0 THEN 'funding_blocked'
      ELSE 'ready'
    END,
    'can_start', v_status NOT IN ('COMPLETED', 'CANCELLED', 'CANCELED')
      AND v_complete
      AND (NOT v_enforce OR v_short = 0),
    'contract_locked', v_locked,
    'guarantee_enforced', v_enforce,
    'guaranteed_prize', v_guaranteed,
    'satellite_seat_guarantee', v_seat_guarantee,
    'effective_guarantee', v_effective_guarantee,
    'current_prize_pool', v_pool,
    'overlay_required', v_required,
    'bank_type', v_bank_type,
    'bank_balance', v_bank,
    'bank_floor', COALESCE(v_floor, 0),
    'other_live_exposure', COALESCE(v_exposure, 0),
    'short_by', v_short
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_has_unsettled_bounties(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.state='pending'
    )
    OR EXISTS (
      -- `settled` is only a cache of the marker trigger's last verdict. The
      -- canonical ledger/award can never be allowed to drift underneath it:
      -- finalisation re-proves the complete generation marker every time.
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.state='settled'
         AND NOT public.fn_bounty_obligation_has_complete_marker(o.id)
    )
    OR EXISTS (
      SELECT 1 FROM public.tournament_bounty_awards a
       WHERE a.tournament_id=p_tournament_id AND a.status IN ('reserved','revealed','paid')
    );
$function$;
CREATE OR REPLACE FUNCTION public.fn_check_atomic_satellite_finish(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch public.tournament_satellite_settlement_batches%ROWTYPE;
  v_count integer;
  v_depth integer;
  v_amount numeric;
  v_fingerprint text;
  v_bad integer;
  v_winner uuid;
  v_t public.tournaments%ROWTYPE;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_rake_expected numeric;
  v_rake_rows integer;
  v_rake_amount numeric;
  v_rake_destination text;
  v_rake_settled_at timestamptz;
  v_rake_attributed_at timestamptz;
  v_bounty public.tournament_bounty_completion_receipts%ROWTYPE;
BEGIN
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_batch FROM public.tournament_satellite_settlement_batches
   WHERE tournament_id=p_tournament_id;
  IF NOT FOUND OR v_batch.settled_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_batch_not_settled');
  END IF;
  SELECT count(*)::integer,COALESCE(max(e.position),0),
         round(COALESCE(sum(e.ticket_value+e.remainder_value),0),2),
         md5(COALESCE(string_agg(
           concat_ws(':',e.position,e.award_kind,
             COALESCE(e.target_tournament_id::text,''),e.ticket_value,e.remainder_value,
             e.source_pool,e.entry_closed_at::text),'|' ORDER BY e.position),''))
    INTO v_count,v_depth,v_amount,v_fingerprint
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id;
  IF ROW(v_batch.entitlement_count,v_batch.award_depth,v_batch.amount_owed,
         v_batch.plan_fingerprint)
     IS DISTINCT FROM ROW(v_count,v_depth,v_amount,v_fingerprint) THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_batch_plan_conflict');
  END IF;
  SELECT (array_agg(tp.user_id ORDER BY tp.user_id))[1] INTO v_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.status='winner' AND tp.position=1;
  IF v_winner IS DISTINCT FROM v_batch.winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_winner_conflict');
  END IF;
  SELECT count(*)::integer INTO v_bad
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_batch.outcomes) o
        WHERE COALESCE(o->>'position','')~'^[0-9]+$'
          AND (o->>'position')::integer=e.position
          AND COALESCE(o->>'user_id','')=(SELECT tp.user_id::text
            FROM public.tournament_players tp
            WHERE tp.tournament_id=p_tournament_id AND tp.position=e.position)
          AND CASE WHEN COALESCE(o->>'ticket_value','')~'^[0-9]+([.][0-9]+)?$'
                   THEN round((o->>'ticket_value')::numeric,2) ELSE -1 END
              =e.ticket_value
          AND CASE WHEN COALESCE(o->>'remainder_value','')~'^[0-9]+([.][0-9]+)?$'
                   THEN round((o->>'remainder_value')::numeric,2) ELSE -1 END
              =e.remainder_value
     );
  IF v_bad>0 OR jsonb_array_length(v_batch.outcomes)<>v_count OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_batch.outcomes) o
     GROUP BY o->>'position' HAVING count(*)<>1
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_outcome_set_incomplete');
  END IF;

  -- Prove each promised ticket is exactly one in-kind seat or one paid place,
  -- never both; prove residual cash through its distinct obligation key.
  SELECT count(*)::integer INTO v_bad
    FROM public.tournament_satellite_entitlements e
    JOIN public.tournament_players finisher
      ON finisher.tournament_id=e.tournament_id AND finisher.position=e.position
    CROSS JOIN LATERAL (
      SELECT o FROM jsonb_array_elements(v_batch.outcomes) o
       WHERE (o->>'position')::integer=e.position LIMIT 1
    ) outcome
   WHERE e.tournament_id=p_tournament_id AND (
     finisher.status NOT IN ('winner','eliminated')
     OR round(COALESCE(finisher.prize,0),2)<>
          round(e.ticket_value+e.remainder_value,2)
     OR (e.ticket_value>0 AND (
       (outcome.o->>'ticket_delivery') NOT IN ('seat','cash')
       OR ((outcome.o->>'ticket_delivery')='seat')<>((
         SELECT count(*)=1 FROM public.tournament_payouts po
          JOIN public.tournament_players target_seat
            ON target_seat.id::text=po.metadata->>'registration_id'
         WHERE po.tournament_id=p_tournament_id AND po.user_id=finisher.user_id
           AND po.position=e.position AND po.source='satellite_seat'
           AND round(po.amount,2)=e.ticket_value
           AND CASE WHEN COALESCE(po.metadata->>'pool_transfer','')~'^[0-9]+([.][0-9]+)?$'
                    THEN round((po.metadata->>'pool_transfer')::numeric,2) ELSE -1 END
               =e.ticket_value
           AND CASE WHEN COALESCE(po.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                    THEN round((po.metadata->>'unbacked')::numeric,2) ELSE -1 END=0
           AND round(
             CASE WHEN COALESCE(po.metadata->>'target_buy_in','')~'^[0-9]+([.][0-9]+)?$'
                  THEN (po.metadata->>'target_buy_in')::numeric ELSE -1 END
             +CASE WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                   THEN (po.metadata->>'target_fee')::numeric ELSE -1 END,2)
               =e.ticket_value
           AND target_seat.user_id=finisher.user_id
           AND target_seat.source_satellite_id=p_tournament_id
           AND (SELECT count(*) FROM public.chip_ledger l
                 WHERE l.idempotency_key='tourney:'||p_tournament_id::text
                       ||':seat:'||finisher.user_id::text||':pool_transfer'
                   AND l.from_type='prize_liability'
                   AND l.from_entity_id=p_tournament_id
                   AND l.to_type='prize_liability'
                   AND l.to_entity_id=e.target_tournament_id
                   AND round(l.amount,2)=e.ticket_value
                   AND l.metadata->>'registration_id'=target_seat.id::text
                   AND CASE WHEN COALESCE(l.metadata->>'moved','')~'^[0-9]+([.][0-9]+)?$'
                            THEN round((l.metadata->>'moved')::numeric,2) ELSE -1 END
                       =e.ticket_value
                   AND CASE WHEN COALESCE(l.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                            THEN round((l.metadata->>'unbacked')::numeric,2) ELSE -1 END=0)=1
           AND (SELECT count(*) FROM public.rake_records rr
                 WHERE rr.tournament_id=e.target_tournament_id
                   AND rr.source='fn_award_satellite_seat'
                   AND rr.metadata->>'satellite_id'=p_tournament_id::text
                   AND rr.metadata->>'user_id'=finisher.user_id::text
                   AND rr.metadata->>'registration_id'=target_seat.id::text
                   AND round(rr.rake_amount,2)=round(
                     CASE WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                          THEN (po.metadata->>'target_fee')::numeric ELSE -1 END,2)
                   AND round(COALESCE(rr.pot_size,0),2)=e.ticket_value)
               =CASE WHEN CASE
                   WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                     THEN (po.metadata->>'target_fee')::numeric ELSE -1 END>0
                 THEN 1 ELSE 0 END
       ))
       OR ((outcome.o->>'ticket_delivery')='cash')<>((
         SELECT count(*)=1 FROM public.tournament_obligations obl
          WHERE obl.tournament_id=p_tournament_id AND obl.kind='place'
            AND obl.place=e.position AND obl.user_id=finisher.user_id
            AND round(obl.amount_owed,2)=e.ticket_value
            AND round(obl.amount_paid,2)=e.ticket_value
            AND obl.settled_at IS NOT NULL))
     ))
     OR (e.award_kind='cash' AND (
       SELECT count(*) FROM public.tournament_obligations obl
        WHERE obl.tournament_id=p_tournament_id AND obl.kind='place'
          AND obl.place=e.position AND obl.user_id=finisher.user_id
          AND round(obl.amount_owed,2)=e.remainder_value
          AND round(obl.amount_paid,2)=e.remainder_value
          AND obl.settled_at IS NOT NULL)<>1)
     OR (e.ticket_value>0 AND e.remainder_value>0 AND (
       SELECT count(*) FROM public.tournament_obligations obl
        WHERE obl.tournament_id=p_tournament_id
          AND obl.kind='satellite_remainder' AND obl.place IS NULL
          AND obl.user_id=finisher.user_id
          AND round(obl.amount_owed,2)=e.remainder_value
          AND round(obl.amount_paid,2)=e.remainder_value
          AND obl.settled_at IS NOT NULL)<>1)
   );
  IF v_bad>0 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_money_evidence_incomplete',
                              'invalid_entitlements',v_bad);
  END IF;

  -- COMPLETED cannot outrun the common money prerequisites. The caller runs
  -- rake/bounty settlement first, while this checker independently proves the
  -- durable receipts inside the same transaction as the terminal status flip.
  SELECT GREATEST(round(COALESCE(sum(rr.rake_amount),0),2),0)
    INTO v_rake_expected
    FROM public.rake_records rr
   WHERE rr.tournament_id=p_tournament_id AND rr.is_tournament;
  SELECT count(*)::integer,(array_agg(rs.amount ORDER BY rs.tournament_id))[1],
         (array_agg(rs.destination ORDER BY rs.tournament_id))[1],
         (array_agg(rs.settled_at ORDER BY rs.tournament_id))[1],
         (array_agg(rs.attributed_at ORDER BY rs.tournament_id))[1]
    INTO v_rake_rows,v_rake_amount,v_rake_destination,
         v_rake_settled_at,v_rake_attributed_at
    FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id=p_tournament_id;
  IF v_rake_rows<>1 OR v_rake_settled_at IS NULL
     OR v_rake_attributed_at IS NULL OR v_rake_destination='pending'
     OR abs(round(COALESCE(v_rake_amount,0),2)-v_rake_expected)>0.005 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_rake_not_settled',
      'expected',v_rake_expected,'recorded',v_rake_amount,
      'destination',v_rake_destination,'attributed_at',v_rake_attributed_at);
  END IF;

  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
      RETURN jsonb_build_object('ok',false,
                                'reason','satellite_bounty_obligations_pending');
    END IF;
    SELECT * INTO v_bounty
      FROM public.tournament_bounty_completion_receipts b
     WHERE b.tournament_id=p_tournament_id;
    IF NOT FOUND OR v_bounty.winner_user_id IS DISTINCT FROM v_winner
       OR v_bounty.pool_finalized_at IS NULL
       OR COALESCE((v_bounty.pool_result->>'ok')::boolean,false) IS NOT TRUE
       OR (COALESCE(v_t.is_mystery_bounty,false)
           AND COALESCE(v_t.mystery_bounty_stage,'pending')<>'pending'
           AND (v_bounty.mystery_settled_at IS NULL
                OR COALESCE((v_bounty.mystery_result->>'ok')::boolean,false) IS NOT TRUE
                OR COALESCE((v_bounty.mystery_result->>'balanced')::boolean,false) IS NOT TRUE)) THEN
      RETURN jsonb_build_object('ok',false,
                                'reason','satellite_bounty_not_certified');
    END IF;
  END IF;

  SELECT * INTO v_escrow FROM public.tournament_escrow
   WHERE tournament_id=p_tournament_id;
  IF NOT FOUND THEN
    IF COALESCE(v_t.prize_pool,0)<>0 OR COALESCE(v_t.bounty_pool,0)<>0
       OR COALESCE(v_t.total_rake,0)<>0
       OR EXISTS (SELECT 1 FROM public.tournament_payouts po
                   WHERE po.tournament_id=p_tournament_id) THEN
      RETURN jsonb_build_object('ok',false,'reason','satellite_escrow_evidence_missing');
    END IF;
  ELSIF abs(round(v_escrow.prize_balance,2))>0.005
     OR abs(round(v_escrow.bounty_balance,2))>0.005
     OR abs(round(v_escrow.fee_balance,2))>0.005 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_escrow_not_zero',
      'prize_balance',v_escrow.prize_balance,
      'bounty_balance',v_escrow.bounty_balance,
      'fee_balance',v_escrow.fee_balance);
  END IF;
  RETURN jsonb_build_object('ok',true,'reason',NULL,
    'tournament_id',p_tournament_id,'winner_user_id',v_batch.winner_user_id,
    'entitlement_count',v_count,'award_depth',v_depth,'amount_settled',v_amount,
    'plan_fingerprint',v_fingerprint);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_finish_kind(p_tournament_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches d
       WHERE d.tournament_id = p_tournament_id
    ) THEN 'final_table_deal'
    WHEN lower(COALESCE(t.variant,'')) = 'satellite'
      OR upper(COALESCE(t.tournament_type,'')) = 'SATELLITE'
      OR t.satellite_target_id IS NOT NULL THEN 'satellite'
    ELSE 'normal'
  END
  FROM public.tournaments t
  WHERE t.id = p_tournament_id;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_verify_terminal_final_deal_batch(p_tournament_id uuid, p_require_terminal boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_t public.tournaments%ROWTYPE;
 v_b public.tournament_final_table_deal_batches%ROWTYPE;
 v_e public.tournament_escrow%ROWTYPE;
 v_ob public.tournament_obligations%ROWTYPE;
 v_input jsonb; v_tail jsonb; v_ladder jsonb; v_expected jsonb;
 v_field integer; v_ladder_count integer; v_max_place integer;
 v_place_total numeric; v_deal_cents bigint; v_chips numeric;
 v_bubble numeric:=0; v_bubble_user uuid;
 v_line record; v_amount numeric; v_paid numeric; v_count integer;
 v_not_pool text[]:=ARRAY['satellite_seat','bounty','mystery_bounty',
  'bounty_residual','own_bounty','mystery_bounty_residual'];
BEGIN
 SELECT * INTO STRICT v_t FROM public.tournaments WHERE id=p_tournament_id;
 SELECT * INTO STRICT v_b FROM public.tournament_final_table_deal_batches
  WHERE tournament_id=p_tournament_id;
 IF v_b.contract_version<>2 OR v_b.settled_at IS NULL
  OR v_b.source IS DISTINCT FROM 'engine.fn_settle_tournament_final_table_deal'
  OR v_t.prize_pool_finalized IS DISTINCT FROM true
  OR v_t.prize_pool IS NULL OR v_t.prize_pool<=0
  OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
  OR v_t.prize_pool<>round(v_t.prize_pool,2)
  OR v_t.prize_pool<COALESCE(v_t.guaranteed_prize,0)
  OR lower(COALESCE(v_t.variant,''))='satellite'
  OR upper(COALESCE(v_t.tournament_type,''))='SATELLITE'
  OR v_t.satellite_target_id IS NOT NULL OR v_t.satellite_target IS NOT NULL
 THEN RAISE EXCEPTION 'canonical final deal is not a settled funded cash batch'; END IF;
 SELECT count(*) INTO v_field FROM public.tournament_players WHERE tournament_id=p_tournament_id;
 IF v_field<>v_b.field_count OR v_b.live_count>v_field
  OR v_b.live_count>v_t.table_size OR v_b.live_count<2
  OR (SELECT count(DISTINCT position) FROM public.tournament_players
   WHERE tournament_id=p_tournament_id)<>v_field
  OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id
   AND status='winner' AND position=1 AND user_id=v_b.chip_leader
   AND eliminated_at IS NULL AND elimination_sequence IS NULL)<>1
  OR EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
   AND (position IS NULL OR position<1 OR position>v_field
    OR status NOT IN ('winner','eliminated')
    OR (position>1 AND (status<>'eliminated' OR eliminated_at IS NULL
     OR elimination_sequence IS NULL OR elimination_sequence<=0))
    OR (status='winner' AND position<>1)))
  OR (SELECT count(DISTINCT elimination_sequence) FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND status='eliminated')<>v_field-1
  OR EXISTS(SELECT 1 FROM (SELECT position,
   row_number() OVER(ORDER BY elimination_sequence DESC,id)+1 expected
   FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND status='eliminated') q WHERE position<>expected)
 THEN RAISE EXCEPTION 'canonical final deal durable standings differ'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',tp.user_id,'club_id',tp.club_id,
  'chips',tp.chips,'registered_at',extract(epoch FROM tp.registered_at))
  ORDER BY tp.chips DESC,tp.registered_at ASC NULLS LAST,tp.user_id),'[]'::jsonb),
  sum(tp.chips)
 INTO v_input,v_chips FROM public.tournament_players tp
 WHERE tp.tournament_id=p_tournament_id AND tp.position<=v_b.live_count;
 IF v_input IS DISTINCT FROM v_b.live_input_snapshot
  OR md5(v_input::text) IS DISTINCT FROM v_b.live_input_fingerprint
  OR jsonb_array_length(v_input)<>v_b.live_count OR v_chips IS NULL OR v_chips<=0
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_input) x
   WHERE x->>'chips' IS NULL OR (x->>'chips')::numeric<0
    OR x->>'chips' IN ('NaN','Infinity','-Infinity'))
  OR (v_input->0->>'user_id')::uuid IS DISTINCT FROM v_b.chip_leader
  OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=v_b.deal_table_id
    AND tournament_id=p_tournament_id)
 THEN RAISE EXCEPTION 'canonical final deal immutable input differs'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',tp.id,'user_id',tp.user_id,
  'club_id',tp.club_id,'position',tp.position,'eliminated_at',extract(epoch FROM tp.eliminated_at),
  'elimination_sequence',tp.elimination_sequence) ORDER BY tp.position),'[]'::jsonb)
 INTO v_tail FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
  AND tp.position>v_b.live_count;
 IF md5(v_tail::text) IS DISTINCT FROM v_b.prior_standings_fingerprint
 THEN RAISE EXCEPTION 'canonical final deal prior standings differ'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('place',a.place,'amount',a.amount)
  ORDER BY a.place),'[]'::jsonb),count(*),max(a.place),
  COALESCE(sum(a.amount) FILTER(WHERE a.place>v_b.live_count),0)
 INTO v_ladder,v_ladder_count,v_max_place,v_place_total
 FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
 IF v_ladder_count=0 OR v_ladder_count<>v_b.structure_place_count
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_ladder) x
    WHERE (x->>'amount')::numeric<0
     OR (x->>'amount')::numeric<>round((x->>'amount')::numeric,2))
 THEN RAISE EXCEPTION 'canonical final deal structure differs'; END IF;
 IF v_t.bubble_protection AND v_max_place+1<=v_field AND v_max_place+1>v_b.live_count THEN
  v_bubble:=v_t.buy_in_amount;
  IF v_bubble IS NULL OR v_bubble<=0 OR v_bubble::text IN ('NaN','Infinity','-Infinity')
   OR v_bubble<>round(v_bubble,2) THEN RAISE EXCEPTION 'canonical final deal Bubble amount invalid'; END IF;
  SELECT user_id INTO STRICT v_bubble_user FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND position=v_max_place+1 AND status='eliminated';
 END IF;
 v_deal_cents:=round((v_t.prize_pool-v_place_total-v_bubble)*100)::bigint;
 IF v_deal_cents<=0 THEN RAISE EXCEPTION 'canonical final deal residual invalid'; END IF;
 WITH live AS (
  SELECT (x->>'user_id')::uuid user_id,(x->>'club_id')::uuid club_id,ord::integer place,
   floor((x->>'chips')::numeric*v_deal_cents/v_chips)::bigint cents
  FROM jsonb_array_elements(v_input) WITH ORDINALITY z(x,ord)
 ), all_lines AS (
  SELECT 'final_table_deal' kind,place,user_id,club_id,
   cents+CASE WHEN place=1 THEN v_deal_cents-(SELECT sum(cents) FROM live) ELSE 0 END cents
   FROM live
  UNION ALL
  SELECT 'place',(x->>'place')::integer,tp.user_id,tp.club_id,
   round((x->>'amount')::numeric*100)::bigint
  FROM jsonb_array_elements(v_ladder) x JOIN public.tournament_players tp
   ON tp.tournament_id=p_tournament_id AND tp.position=(x->>'place')::integer
  WHERE (x->>'place')::integer>v_b.live_count AND (x->>'amount')::numeric>0
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'place',place,
  'user_id',user_id,'club_id',club_id,'cents',cents) ORDER BY place),'[]'::jsonb)
 INTO v_expected FROM all_lines;
 IF v_b.plan IS DISTINCT FROM v_expected OR v_b.plan_fingerprint IS DISTINCT FROM md5(v_expected::text)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x WHERE (x->>'cents')::bigint<=0)
  OR v_b.place_amount IS DISTINCT FROM v_place_total
  OR v_b.deal_amount IS DISTINCT FROM v_deal_cents::numeric/100
  OR v_b.amount_owed IS DISTINCT FROM v_t.prize_pool-v_bubble
  OR v_b.deal_line_count<>v_b.live_count
  OR v_b.place_line_count<>jsonb_array_length(v_expected)-v_b.live_count
  OR v_b.escrow_prize_after IS DISTINCT FROM 0::numeric
  OR v_b.escrow_prize_before IS DISTINCT FROM v_b.amount_moved
  OR v_b.amount_moved<0 OR v_b.amount_moved>v_t.prize_pool
 THEN RAISE EXCEPTION 'canonical final deal plan or escrow proof differs'; END IF;
 FOR v_line IN SELECT (x->>'kind') kind,(x->>'place')::integer place,
  (x->>'user_id')::uuid user_id,(x->>'cents')::numeric/100 amount
  FROM jsonb_array_elements(v_expected) x
 LOOP
  SELECT * INTO STRICT v_ob FROM public.tournament_obligations o WHERE
   o.tournament_id=p_tournament_id AND o.kind=v_line.kind
   AND (CASE WHEN v_line.kind='place' THEN o.place=v_line.place
    ELSE o.place IS NULL AND o.user_id=v_line.user_id END);
  IF v_ob.user_id IS DISTINCT FROM v_line.user_id OR v_ob.amount_owed IS DISTINCT FROM v_line.amount
   OR v_ob.amount_paid IS DISTINCT FROM v_line.amount OR v_ob.settled_at IS NULL
   OR (v_line.kind='final_table_deal' AND (v_ob.source IS DISTINCT FROM 'final_table_deal'
    OR v_ob.adjustment_id IS NOT NULL))
  THEN RAISE EXCEPTION 'canonical final deal obligation differs at place %',v_line.place; END IF;
  SELECT COALESCE(sum(p.amount),0),count(*) INTO v_paid,v_count FROM public.tournament_payouts p
   WHERE p.tournament_id=p_tournament_id AND p.user_id=v_line.user_id
    AND (CASE WHEN v_line.kind='place' THEN p.position=v_line.place
      AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)) AND p.source<>'final_table_deal'
     ELSE p.position IS NULL AND p.source='final_table_deal' END);
  IF v_paid IS DISTINCT FROM v_line.amount OR v_count<1
   OR (v_line.kind='final_table_deal' AND v_count<>1)
  THEN RAISE EXCEPTION 'canonical final deal payout differs at place %',v_line.place; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.tournament_obligations o
  WHERE o.tournament_id=p_tournament_id AND o.kind IN ('place','final_table_deal')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x
    WHERE o.kind=x->>'kind' AND o.user_id=(x->>'user_id')::uuid
     AND (CASE WHEN o.kind='place' THEN o.place=(x->>'place')::integer ELSE o.place IS NULL END)))
 THEN RAISE EXCEPTION 'canonical final deal has uncontracted debt'; END IF;
 SELECT count(*) INTO v_count FROM public.tournament_obligations
  WHERE tournament_id=p_tournament_id AND kind='bubble_protection';
 IF v_bubble>0 THEN
  SELECT * INTO STRICT v_ob FROM public.tournament_obligations
   WHERE tournament_id=p_tournament_id AND kind='bubble_protection';
  IF v_count<>1 OR v_ob.place IS NOT NULL OR v_ob.user_id IS DISTINCT FROM v_bubble_user
   OR v_ob.amount_owed IS DISTINCT FROM v_bubble OR v_ob.amount_paid IS DISTINCT FROM v_bubble
   OR v_ob.settled_at IS NULL OR v_ob.source IS NULL
   OR v_ob.source NOT IN ('engine.eliminatePlayer','engine.atomicPlaceSettlement',
    'engine.fn_settle_tournament_places','engine.fn_settle_tournament_bubble_protection')
   OR v_b.bubble_contract_required IS DISTINCT FROM true
   OR v_b.bubble_obligation_id IS DISTINCT FROM v_ob.id
   OR v_b.bubble_user_id IS DISTINCT FROM v_bubble_user
   OR v_b.bubble_source IS DISTINCT FROM v_ob.source
   OR v_b.bubble_amount_owed IS DISTINCT FROM v_bubble
   OR v_b.bubble_amount_paid_before<0 OR v_b.bubble_amount_paid_before>v_bubble
   OR (SELECT COALESCE(sum(amount),0) FROM public.tournament_payouts
    WHERE tournament_id=p_tournament_id AND source='bubble_protection') IS DISTINCT FROM v_bubble
  THEN RAISE EXCEPTION 'canonical final deal Bubble proof differs'; END IF;
 ELSIF v_count<>0 OR v_b.bubble_contract_required IS DISTINCT FROM false
  OR v_b.bubble_obligation_id IS NOT NULL OR v_b.bubble_user_id IS NOT NULL
  OR v_b.bubble_source IS NOT NULL OR v_b.bubble_amount_owed<>0 OR v_b.bubble_amount_paid_before<>0
 THEN RAISE EXCEPTION 'canonical final deal has uncontracted Bubble'; END IF;
 IF EXISTS(SELECT 1 FROM public.tournament_payouts p WHERE p.tournament_id=p_tournament_id
  AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)) AND
   (p.amount IS NULL OR p.amount<=0 OR p.amount::text IN ('NaN','Infinity','-Infinity')
    OR p.amount<>round(p.amount,2) OR p.idempotency_key IS NULL
    OR NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency k WHERE
     k.key=p.idempotency_key AND k.user_id=p.user_id AND k.amount=p.amount)
    OR NOT(
     (p.source='bubble_protection' AND p.position IS NULL AND p.user_id=v_bubble_user AND v_bubble>0)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x WHERE p.user_id=(x->>'user_id')::uuid
      AND CASE WHEN x->>'kind'='place' THEN p.position=(x->>'place')::integer
        AND p.source<>'final_table_deal' AND p.source<>'bubble_protection'
       ELSE p.position IS NULL AND p.source='final_table_deal' END))))
  OR (SELECT COALESCE(sum(p.amount),0) FROM public.tournament_payouts p
   WHERE p.tournament_id=p_tournament_id AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)))
    IS DISTINCT FROM v_t.prize_pool
  OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
   AND tp.prize IS DISTINCT FROM COALESCE((SELECT sum(p.amount) FROM public.tournament_payouts p
    WHERE p.tournament_id=p_tournament_id AND p.user_id=tp.user_id
     AND NOT(COALESCE(p.source,'')=ANY(v_not_pool))),0))
 THEN RAISE EXCEPTION 'canonical final deal wallet proof or cache differs'; END IF;
 -- Every obligation-scoped wallet credit must retain its exact payout witness.
 -- This also rejects an extra spent key hidden behind otherwise-correct totals.
 IF EXISTS(SELECT 1 FROM public.tournament_obligations o
  JOIN public.wallet_credit_idempotency k
   ON k.key LIKE 'tourney:'||p_tournament_id::text||':obl:'||o.id::text||':%'
  WHERE o.tournament_id=p_tournament_id AND o.kind IN ('place','final_table_deal','bubble_protection')
   AND NOT EXISTS(SELECT 1 FROM public.tournament_payouts p
    WHERE p.tournament_id=p_tournament_id AND p.idempotency_key=k.key
     AND p.user_id=k.user_id AND p.user_id=o.user_id AND p.amount=k.amount
     AND CASE WHEN o.kind='place' THEN p.position=o.place
       AND NOT(COALESCE(p.source,'')=ANY(v_not_pool))
       AND p.source NOT IN ('final_table_deal','bubble_protection')
      ELSE p.position IS NULL AND p.source=o.kind END))
 THEN RAISE EXCEPTION 'canonical final deal has an orphaned wallet credit'; END IF;
 SELECT * INTO STRICT v_e FROM public.tournament_escrow WHERE tournament_id=p_tournament_id;
 IF v_e.enforced IS DISTINCT FROM true OR v_e.prize_balance IS DISTINCT FROM 0::numeric
  OR (p_require_terminal AND (v_e.bounty_balance IS DISTINCT FROM 0::numeric
   OR v_e.fee_balance IS DISTINCT FROM 0::numeric OR v_e.closed_at IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.tournament_finish_receipts f
    WHERE f.tournament_id=p_tournament_id AND f.finish_kind='final_table_deal'
     AND f.winner_user_id=v_b.chip_leader)
   OR EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
    WHERE t.tournament_id=p_tournament_id AND (s.left_at IS NULL OR s.status IS DISTINCT FROM 'left'))))
 THEN RAISE EXCEPTION 'canonical final deal has open custody, seats or missing finish claim'; END IF;
 RETURN jsonb_build_object('ok',true,'contract_version',2,'plan_fingerprint',v_b.plan_fingerprint,
  'place_amount',v_place_total,'deal_amount',v_deal_cents::numeric/100,'bubble_amount',v_bubble,
  'chip_leader',v_b.chip_leader);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_satellite_target_is_deliverable(p_target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Mirrors the admission refusal in fn_settle_satellite_tournament_pre_money_path_gate
  -- exactly: every flag must be a known false, and neither Spin spelling.
  -- A missing target is not deliverable either (the authority refuses it).
  SELECT COALESCE((
    SELECT t.is_bounty IS FALSE
       AND t.is_pko IS FALSE
       AND t.is_mystery_bounty IS FALSE
       AND t.is_premium_spin IS FALSE
       AND lower(COALESCE(t.variant, '')) <> 'spin'
       AND upper(COALESCE(t.tournament_type, '')) <> 'SPIN'
      FROM public.tournaments t
     WHERE t.id = p_target_id
  ), false)
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_mtt_blind_contract(p_structure text, p_starting_chips integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  levels jsonb; r jsonb; i integer:=0; played integer:=0;
  sb numeric; bb numeric; ante numeric; mins numeric; secs numeric; opening numeric;
  previous_sb numeric:=-1; previous_bb numeric:=-1; speed text;
BEGIN
  IF p_starting_chips IS NULL OR p_starting_chips<=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: starting stack must be a positive whole number' USING ERRCODE='22023';
  END IF;
  BEGIN levels:=p_structure::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: unreadable ladder' USING ERRCODE='22023';
  END;
  IF levels IS NULL OR jsonb_typeof(levels)<>'array' THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(levels)=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(levels) LOOP
    i:=i+1;
    IF jsonb_typeof(r)<>'object' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % must be an object',i USING ERRCODE='22023';
    END IF;
    IF r ? 'isBreak' AND jsonb_typeof(r->'isBreak')<>'boolean' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has an invalid break flag',i USING ERRCODE='22023';
    END IF;
    mins:=public.fn_ca_blind_contract_number(COALESCE(NULLIF(r->'durationMinutes','null'::jsonb),r->'duration_minutes'));
    secs:=public.fn_ca_blind_contract_number(r->'duration');
    IF COALESCE(mins,0)<=0 AND COALESCE(secs,0)<=0 THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive duration',i USING ERRCODE='22023';
    END IF;
    sb:=public.fn_ca_blind_contract_number(r->'smallBlind');
    bb:=public.fn_ca_blind_contract_number(r->'bigBlind');
    ante:=CASE WHEN r ? 'ante' THEN public.fn_ca_blind_contract_number(r->'ante') ELSE 0 END;
    IF sb IS NULL OR bb IS NULL OR ante IS NULL THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has invalid blinds or ante',i USING ERRCODE='22023';
    END IF;
    IF r->'isBreak'='true'::jsonb THEN
      IF i=1 OR sb<>0 OR bb<>0 OR ante<>0 THEN
        RAISE EXCEPTION 'Invalid tournament blind structure: level % is not a valid break',i USING ERRCODE='22023';
      END IF;
      CONTINUE;
    END IF;
    IF bb<=0 OR sb>bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive big blind at least as large as its small blind',i USING ERRCODE='22023';
    END IF;
    IF sb<previous_sb OR bb<previous_bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % decreases the blinds',i USING ERRCODE='22023';
    END IF;
    IF played=0 THEN opening:=CASE WHEN mins>0 THEN mins ELSE secs/60 END; END IF;
    previous_sb:=sb; previous_bb:=bb; played:=played+1;
  END LOOP;
  IF played=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  speed:=CASE WHEN opening<=2 THEN 'hyper_turbo' WHEN opening<=5 THEN 'turbo' WHEN opening>=12 THEN 'slow' ELSE 'standard' END;
  RETURN jsonb_build_object('blind_speed',speed,'is_turbo',speed IN ('turbo','hyper_turbo'));
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_accounting_agreement_terms(p_entity_type text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
 SELECT CASE WHEN p_row IS NULL THEN NULL ELSE
  (SELECT jsonb_object_agg(e.key,e.value) FROM jsonb_each(p_row) e
    WHERE e.key=ANY(CASE p_entity_type
      WHEN 'agents' THEN ARRAY['id','club_id','user_id','parent_agent_id','role','status','commission_rate','player_rakeback_rate','is_prepaid']
      WHEN 'club_members' THEN ARRAY['club_id','user_id','agent_id','parent_agent_id','role','status','is_active','commission_rate','rakeback_rate','player_rakeback_pct']
      WHEN 'union_clubs' THEN ARRAY['id','club_id','union_id','club_commission_rate','rate_cash','rate_mtt','rate_sng','rate_spin','rate_satellite']
      ELSE ARRAY[]::text[] END)) END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_live_table_count(p_club_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT count(*)::int
    FROM tables t
   WHERE t.tournament_id IS NULL
     AND t.is_deleted IS NOT TRUE
     AND t.status NOT IN ('closed', 'deleted')
     AND (
       -- the club's own games (private club games included)
       t.club_id = p_club_id
       -- plus the union's games, if this club belongs to one
       OR t.union_id = (SELECT uc.union_id FROM union_clubs uc
                         WHERE uc.club_id = p_club_id LIMIT 1)
       -- the union's own container row: its games are keyed by union_id
       OR t.union_id = p_club_id
     );
$function$;
CREATE OR REPLACE FUNCTION public.fn_seat_club_for_user(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_union uuid; v_table_club uuid;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM public.tables t WHERE t.id = p_table_id;
  IF v_union IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.user_id = p_user_id AND cm.club_id = v_table_club
         AND cm.status IN ('active','approved')
    ) THEN RETURN v_table_club; END IF;
    RETURN public.fn_player_home_club(p_user_id, p_preferred_club);
  END IF;
  RETURN public.fn_seat_club_for_user_membership_unchecked(
    p_user_id, p_table_id, p_preferred_club
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_refresh_club_activity_counts(p_club_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    UPDATE public.clubs c
       SET active_players = coalesce(p.n, 0),
           active_tables  = coalesce(t.n, 0)
      FROM public.clubs base
      LEFT JOIN LATERAL (
        -- Mirrors fn_batch_active_player_counts exactly: members of this club
        -- who are seated, not away, at a table that is not in a terminal state.
        SELECT count(DISTINCT ts.user_id) AS n
          FROM public.club_members cm
          JOIN public.table_seats ts
            ON ts.user_id = cm.user_id
           AND ts.left_at IS NULL
           AND coalesce(ts.is_away, false) = false
          JOIN public.tables tb
            ON tb.id = ts.table_id
           AND lower(coalesce(tb.status,'')) NOT IN ('closed','completed','cancelled','finished')
         WHERE cm.club_id = base.id
           AND cm.status = 'active'
      ) p ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n
          FROM public.tables tb2
         WHERE tb2.club_id = base.id
           AND lower(coalesce(tb2.status,'')) NOT IN ('closed','completed','cancelled','finished')
      ) t ON true
     WHERE c.id = base.id
       AND (p_club_id IS NULL OR base.id = p_club_id);
$function$;
CREATE OR REPLACE FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table      uuid;
  v_seats      integer := 0;
  v_seat_first boolean := false;
  v_is_spin    boolean := false;
  v_cap        integer := 0;
  v_variant    text := '';
  v_book       jsonb;
BEGIN
  -- This is an AFTER-seat helper. It must never acquire a new global lock
  -- after PostgreSQL already owns the changed seat row. Every legitimate
  -- create/revive root pre-acquires terminal -> mission -> launch -> tournament,
  -- and the earliest BEFORE trigger refuses a raw writer that did not.
  SELECT (lower(COALESCE(t.variant, '')) = 'spin'
          OR COALESCE(t.max_players, 0) <= 2),
         lower(COALESCE(t.variant, '')) = 'spin',
         COALESCE(t.max_players, 0),
         COALESCE(t.variant, '')
    INTO v_seat_first, v_is_spin, v_cap, v_variant
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Freeze the complete table/seat set before choosing the occupied table.
  -- UUID order is deterministic across every transaction using this owner.
  PERFORM tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY tb.id
   FOR UPDATE;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
     AND s.left_at IS NULL
   ORDER BY s.table_id, s.seat_number, s.id
   FOR UPDATE OF s;

  v_table := public.fn_tournament_primary_table(p_tournament_id);

  IF v_table IS NULL THEN
    IF COALESCE(v_seat_first, false) THEN
      SELECT count(*) INTO v_seats
        FROM public.table_seats s
        JOIN public.tables tb ON tb.id = s.table_id
       WHERE tb.tournament_id = p_tournament_id
         AND s.left_at IS NULL;
      UPDATE public.tournaments SET current_players = v_seats
       WHERE id = p_tournament_id
         AND current_players IS DISTINCT FROM v_seats;
      RETURN v_seats;
    END IF;
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_seats
    FROM public.table_seats
   WHERE table_id = v_table AND left_at IS NULL;

  UPDATE public.tables SET current_players = v_seats
   WHERE id = v_table
     AND current_players IS DISTINCT FROM v_seats;

  IF COALESCE(v_seat_first, false) THEN
    UPDATE public.tournaments SET current_players = v_seats
     WHERE id = p_tournament_id
       AND current_players IS DISTINCT FROM v_seats;
  END IF;

  IF v_is_spin AND v_cap > 0 AND v_seats >= v_cap THEN
    v_book := public.fn_spin_book_entry(p_tournament_id);
    IF COALESCE((v_book->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid third seat could not book Spin %: %',
        p_tournament_id,v_book USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF COALESCE(v_seat_first, false)
     AND v_cap > 0 AND v_seats >= v_cap THEN
    BEGIN
      PERFORM realtime.send(
        jsonb_build_object(
          'tournament_id', p_tournament_id,
          'variant', v_variant,
          'max_players', v_cap,
          'paid_seats', v_seats,
          'filled_at', now()
        ),
        'seat_first_ready',
        'seat_first',
        false
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'fn_sync_seat_first_player_count: realtime.send failed for %: %',
        p_tournament_id, SQLERRM;
    END;
  END IF;

  RETURN v_seats;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_union_join_blockers(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_treasury    numeric := 0;
  v_club_promo  numeric := 0;
  v_people      numeric := 0;
  v_people_n    int     := 0;
  v_horses      numeric := 0;
  v_horses_n    int     := 0;
  v_agents      numeric := 0;
  v_agents_n    int     := 0;
  v_felt        numeric := 0;
  v_felt_n      int     := 0;
  v_bbj         numeric := 0;
  v_total       numeric := 0;
BEGIN
  SELECT COALESCE(chip_treasury, 0), COALESCE(promo_balance, 0)
    INTO v_treasury, v_club_promo
    FROM clubs WHERE id = p_club_id;

  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_people, v_people_n
    FROM (
      SELECT COALESCE(cm.chip_balance,0) + COALESCE(cm.held_chips,0)
           + COALESCE(cm.locked_chips,0) + COALESCE(cm.promo_balance,0) AS bal
        FROM club_members cm
        LEFT JOIN profiles p ON p.id = cm.user_id
       WHERE cm.club_id = p_club_id
         AND NOT COALESCE(cm.is_bot, false)
         AND NOT COALESCE(p.is_horse, false)
    ) s;

  -- Reported, never blocking. Dan 2026-08-26: "horses keep all there chips."
  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_horses, v_horses_n
    FROM (
      SELECT COALESCE(cm.chip_balance,0) + COALESCE(cm.held_chips,0)
           + COALESCE(cm.locked_chips,0) + COALESCE(cm.promo_balance,0) AS bal
        FROM club_members cm
        LEFT JOIN profiles p ON p.id = cm.user_id
       WHERE cm.club_id = p_club_id
         AND (COALESCE(cm.is_bot, false) OR COALESCE(p.is_horse, false))
    ) s;

  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_agents, v_agents_n
    FROM (
      SELECT COALESCE(a.business_balance,0) + COALESCE(a.player_balance,0)
           + COALESCE(a.promo_balance,0) AS bal
        FROM agents a WHERE a.club_id = p_club_id
    ) s;

  -- Chips on the felt still block: a hand in progress is a player's money.
  -- A horse's seat is excluded along with the rest of its bankroll.
  SELECT COALESCE(SUM(ts.stack), 0), COUNT(*)
    INTO v_felt, v_felt_n
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    LEFT JOIN profiles p ON p.id = ts.user_id
   WHERE t.club_id = p_club_id
     AND ts.left_at IS NULL
     AND COALESCE(ts.stack, 0) <> 0
     AND NOT COALESCE(p.is_horse, false);

  SELECT COALESCE(SUM(COALESCE(main_balance,0) + COALESCE(backup_balance,0)
                    + COALESCE(promo_balance,0)), 0)
    INTO v_bbj
    FROM bbj_pools WHERE club_id = p_club_id AND union_id IS NULL;

  -- v_horses is deliberately absent from this sum.
  v_total := v_treasury + v_club_promo + v_people + v_agents + v_felt + v_bbj;

  RETURN jsonb_build_object(
    'club_id',         p_club_id,
    'is_empty',        (v_total = 0),
    'total',           v_total,
    'club_treasury',   v_treasury,
    'club_promo',      v_club_promo,
    'member_wallets',  v_people,
    'member_count',    v_people_n,
    'horse_wallets',   v_horses,
    'horse_count',     v_horses_n,
    'horses_block',    false,
    'agent_wallets',   v_agents,
    'agent_count',     v_agents_n,
    'chips_on_felt',   v_felt,
    'open_seats',      v_felt_n,
    'bbj_pool',        v_bbj
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_caller_is_engine()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
  -- The engine and every server-side job authenticate as service_role. A NULL
  -- means there is no PostgREST request context at all - psql, pg_cron, a
  -- migration - which is equally trusted. A browser can never produce NULL:
  -- reaching `authenticated` requires a verified JWT and PostgREST always sets
  -- request.jwt.claims from it.
  --
  -- NOT current_user. Inside a SECURITY DEFINER body current_user is the
  -- function OWNER for the browser and the engine alike, which is what made an
  -- earlier guard on club_members a silent no-op.
  SELECT COALESCE(auth.role(), 'service_role') = 'service_role';
$function$;
CREATE OR REPLACE FUNCTION public.fn_raise_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_user_id IS NULL OR p_title IS NULL OR btrim(p_title) = '' THEN RETURN; END IF;
  INSERT INTO public.notifications (user_id, type, title, message, link, data)
  VALUES (p_user_id, p_type, p_title, p_message, p_link, COALESCE(p_data, '{}'::jsonb));
END; $function$;
CREATE OR REPLACE FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text DEFAULT 'table closed'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tournament uuid;
BEGIN
  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE='22023';
  END IF;
  IF v_tournament IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'skipped','tournament_table');
  END IF;
  -- This read-only assertion is also reached from authorized administrator
  -- close RPCs. It must not require an engine JWT when it moves no money.
  IF EXISTS (SELECT 1 FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL) THEN
    RAISE EXCEPTION 'CASH_TABLE_CLOSE_REQUIRES_ENGINE_DEPARTURES' USING ERRCODE='55000';
  END IF;
  RETURN jsonb_build_object('ok',true,'players_paid',0,
    'chips_returned',0,'reason_text',coalesce(p_reason,'table closed'));
END;
$function$;
CREATE OR REPLACE FUNCTION public.ca_reporting_tournament_clubs_for_user(p_user_id uuid)
 RETURNS TABLE(club_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT h.club_id
    FROM (
      SELECT DISTINCT ON (uc.union_id) cm.club_id, uc.union_id
        FROM public.club_members cm
        JOIN public.union_clubs uc ON uc.club_id = cm.club_id
       WHERE cm.user_id = p_user_id
       ORDER BY uc.union_id, cm.joined_at ASC NULLS LAST, cm.club_id
    ) h
  UNION
  SELECT cm.club_id
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id
     AND NOT EXISTS (
       SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = cm.club_id
     );
$function$;
CREATE OR REPLACE FUNCTION public.ca_refresh_reporting_rollups(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_base jsonb; v_cash jsonb;
BEGIN
  v_base:=public.ca_refresh_reporting_rollups_base(p_start,p_end);
  v_cash:=public.ca_refresh_reporting_cash_rollup(p_start,p_end);
  RETURN v_base || jsonb_build_object('cash_repair',v_cash);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_class text := p_classification;
  v_sev   text := lower(COALESCE(p_severity,'critical'));
  v_stable text;
BEGIN
  IF NOT public.fn_ca_is_midway_scope(
    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)
  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')
  ON CONFLICT (source) DO NOTHING;

  IF v_class IS NULL OR v_class NOT IN (
      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',
      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',
      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',
      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',
      'cross_club_posting','cross_union_posting','unauthorized_adjustment',
      'historical_migration','unknown') THEN
    v_class := 'unknown';
  END IF;
  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;

  UPDATE public.ca_drift_incidents
     SET occurrences  = occurrences + 1,
         last_seen_at = now(),
         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),
         actual_amount      = COALESCE(p_actual, actual_amount),
         expected_amount    = COALESCE(p_expected, expected_amount),
         suspected_cause    = COALESCE(p_suspected_cause, suspected_cause),
         metadata           = COALESCE(p_metadata, metadata)
   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
   RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,
            'discrepancy', p_discrepancy));
    RETURN v_id;
  END IF;

  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).
     A sweep that puts the date in its key defeats the exact-match fold above
     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:
     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.

     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`
     is an hourly bucket where each bucket is a DIFFERENT event, so folding on
     the key alone would hide real ones. A standing condition re-reports the
     same number; a new event reports a new one. Same detector, same key
     without its period label, same discrepancy - then and only then is it the
     same finding said twice. */
  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);
  IF v_stable <> p_dedupe_key THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE status <> 'resolved'
       AND source = p_source
       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable
       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)
     RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'rotated_key', p_dedupe_key,
        'note', 'same condition under a new period label; folded rather than re-filed'));
      RETURN v_id;
    END IF;
  END IF;

  /* DETECTOR STORM CAP (2026-09-09). One source cannot own the board.
     Reached only after the exact-key fold and the stable-key fold above have
     both declined to absorb this finding, i.e. it really would be a NEW row. */
  IF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE source = p_source AND status <> 'resolved') >= 25 THEN
    UPDATE public.ca_drift_incidents
       SET occurrences = occurrences + 1, last_seen_at = now()
     WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      INSERT INTO public.ca_drift_incidents (
        classification, severity, layer, source, dedupe_key,
        discrepancy_amount, suspected_cause, metadata)
      VALUES ('unknown', v_sev, COALESCE(p_layer,'unknown'), p_source,
        'storm:' || p_source, 0,
        'DETECTOR STORM: this source has 25 or more open incidents, so further findings are counted here rather than filed as new rows. Every occurrence is still in financial_alerts and in this incident event log. Fix the detector, or the condition behind it, then resolve this.',
        jsonb_build_object('storm', true, 'capped_from', p_dedupe_key))
      ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
      RETURNING id INTO v_id;
      IF v_id IS NULL THEN
        UPDATE public.ca_drift_incidents
           SET occurrences = occurrences + 1, last_seen_at = now()
         WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
         RETURNING id INTO v_id;
      END IF;
    END IF;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'capped_dedupe_key', p_dedupe_key,
        'discrepancy', p_discrepancy, 'suspected_cause', p_suspected_cause,
        'note', 'counted on the storm incident: this source is over its open-incident cap'));
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_drift_incidents (
    classification, severity, layer, source, dedupe_key,
    union_id, club_id, entity_type, entity_id, table_id, tournament_id,
    hand_id, settlement_id, wallet_ids, transaction_ids,
    expected_amount, actual_amount, discrepancy_amount,
    ledger_balanced, suspected_cause, metadata)
  VALUES (
    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,
    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,
    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,
    p_expected, p_actual, COALESCE(p_discrepancy, 0),
    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb))
  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
     RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (v_id, 'created', jsonb_build_object('source', p_source));

  BEGIN
    PERFORM public.fn_raise_server_financial_alert(
      v_sev, 'drift_incident:' || p_source,
      v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips',
      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  IF p_severity = 'info' THEN
    NULL;
  ELSIF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE created_at > now() - interval '2 minutes') >= 10 THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));
  ELSE
    PERFORM public.fn_ca_incident_notify(
      v_id, 'notified',
      to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class,
      false);
  END IF;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  DECLARE v_state text; v_msg text;
  BEGIN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;
    BEGIN
      INSERT INTO public.ca_incident_file_failures
        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_places int;
  v_pct    numeric;
  v_out    jsonb;
BEGIN
  v_pct := CASE WHEN p_percent IN (10,15,20) THEN p_percent ELSE 10 END;

  -- at least one place, never more places than players
  v_places := GREATEST(1, LEAST(COALESCE(p_entrants,0),
                                ceil(COALESCE(p_entrants,0) * v_pct / 100.0)::int));
  IF COALESCE(p_entrants,0) <= 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH w AS (
    SELECT i AS place, 1.0 / power(i, 0.8) AS weight
      FROM generate_series(1, v_places) i
  ), n AS (
    SELECT place, weight, 100.0 * weight / SUM(weight) OVER () AS exact
      FROM w
  ), f AS (
    SELECT place, exact,
           floor(exact * 100) / 100 AS floored,
           (exact * 100) - floor(exact * 100) AS frac
      FROM n
  ), r AS (
    -- largest remainder: hand the leftover cents to the biggest fractions, so
    -- the structure sums to exactly 100.00 for any field size
    SELECT place, floored,
           row_number() OVER (ORDER BY frac DESC, place ASC) AS rk,
           round((100.0 - SUM(floored) OVER ()) * 100)::int AS cents_left
      FROM f
  )
  SELECT jsonb_agg(
           jsonb_build_object('place', place,
                              'percentage', floored + CASE WHEN rk <= cents_left THEN 0.01 ELSE 0 END)
           ORDER BY place)
    INTO v_out
    FROM r;

  RETURN COALESCE(v_out, '[]'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_is_free_buy_event(p_buy_in_amount numeric, p_buy_in_fee numeric, p_tournament_type text, p_variant text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(p_buy_in_amount, 0) = 0
     AND COALESCE(p_buy_in_fee, 0) = 0
     AND upper(COALESCE(p_tournament_type, 'MTT')) = 'MTT'
     AND lower(COALESCE(p_variant, 'freezeout')) NOT IN ('spin', 'sng');
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_incident(p_rule text, p_severity text, p_user_id uuid, p_amount numeric, p_writer text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sev text := COALESCE(p_severity, 'info');
BEGIN
  -- Fixture accounts are not players (docs/DIAMOND-RULINGS.md): a rule filed against one is info
  -- unless it is critical. Horses are players and are never fixtures.
  IF v_sev <> 'critical' AND p_user_id IS NOT NULL AND public.fn_ca_is_fixture_account(p_user_id) THEN
    v_sev := 'info';
  END IF;
  INSERT INTO public.ca_diamond_incidents (rule, severity, user_id, amount, writer, detail)
  VALUES (p_rule, v_sev, p_user_id, p_amount, p_writer,
          COALESCE(p_detail, '{}'::jsonb) || CASE WHEN v_sev <> COALESCE(p_severity, 'info')
                                                  THEN jsonb_build_object('severity_requested', p_severity, 'fixture_account', true)
                                                  ELSE '{}'::jsonb END);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_diamond_incident could not record % (%): %', p_rule, p_writer, SQLERRM;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_player_restricted(p_user_id uuid, p_scope text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_user_id is null or p_scope is null then
    return false;
  end if;

  return exists (
    select 1
      from public.ca_player_restrictions r
     where r.user_id = p_user_id
       and r.status = 'active'
       and (r.expires_at is null or r.expires_at > now())
       and (r.scope = p_scope or r.scope = 'account')
  );
exception
  when others then
    -- SECTION 0 RULE 3, FAIL OPEN. A player refused a seat because a
    -- lookup broke is a support ticket about something nobody chose.
    return false;
end;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_player_restriction_for(p_user_id uuid, p_scope text)
 RETURNS ca_player_restrictions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select r.*
    from public.ca_player_restrictions r
   where r.user_id = p_user_id
     and r.status = 'active'
     and (r.expires_at is null or r.expires_at > now())
     and (r.scope = p_scope or r.scope = 'account')
   order by (r.scope = 'account') desc, r.applied_at asc
   limit 1;
$function$;
CREATE OR REPLACE FUNCTION public.fn_union_slugify(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT NULLIF(
    trim(BOTH '-' FROM regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g')),
    ''
  );
$function$;
CREATE OR REPLACE FUNCTION public.fn_can_create_union(p_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.union_creators c WHERE c.user_id = p_user_id);
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_rule_mode(p_rule text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE((SELECT m.mode FROM public.ca_diamond_rule_modes m WHERE m.rule = p_rule), 'log');
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_payout_key_is_place_evidence(p_tournament_id uuid, p_idempotency_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place'
       AND p_idempotency_key LIKE
           'tourney:' || p_tournament_id::text || ':obl:' || o.id::text || ':%'
  );
$function$;
CREATE OR REPLACE FUNCTION public.fn_check_atomic_final_table_deal(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t                         record;
  v_batch                     public.tournament_final_table_deal_batches%ROWTYPE;
  v_line_count                integer := 0;
  v_place_lines               integer := 0;
  v_deal_lines                integer := 0;
  v_distinct_places           integer := 0;
  v_distinct_deal_users       integer := 0;
  v_distinct_deal_ranks       integer := 0;
  v_min_deal_rank             integer := 0;
  v_max_deal_rank             integer := 0;
  v_place_cents               bigint := 0;
  v_deal_cents                bigint := 0;
  v_obligation_mismatches     integer := 0;
  v_extra_obligations         integer := 0;
  v_evidence_mismatches       integer := 0;
  v_unexpected_place_evidence integer := 0;
  v_unexpected_deal_evidence  integer := 0;
  v_prize_mismatches          integer := 0;
  v_standing_mismatches       integer := 0;
  v_prior_count               integer := 0;
  v_prior_missing_bust_time   integer := 0;
  v_prior_canonical_mismatches integer := 0;
  v_prior_standings_fingerprint text;
  v_player_count              integer := 0;
  v_unranked                  integer := 0;
  v_distinct_positions        integer := 0;
  v_min_position              integer := 0;
  v_max_position              integer := 0;
  v_winners                   integer := 0;
  v_winner_at_one             integer := 0;
  v_nonterminal               integer := 0;
  v_missing_bust_time         integer := 0;
  v_snapshot_count            integer := 0;
  v_snapshot_distinct_players integer := 0;
  v_snapshot_distinct_users   integer := 0;
  v_snapshot_distinct_seats   integer := 0;
  v_snapshot_wrong_tables     integer := 0;
  v_snapshot_input_mismatches integer := 0;
  v_snapshot_share_mismatches integer := 0;
  v_bubble_user               uuid;
  v_bubble_holders            integer := 0;
  v_bubble_obligations        integer := 0;
  v_bubble_matching           integer := 0;
  v_bubble_owed               numeric := 0;
  v_bubble_paid               numeric := 0;
  v_bubble_evidence           numeric := 0;
  v_bubble_conflicts          integer := 0;
  v_bubble_obligation_id      uuid;
  v_bubble_source             text;
  v_bubble_settled_at         timestamptz;
  v_bubble_obligation_present boolean := false;
  v_bubble_payout_present     boolean := false;
  v_bubble_required           boolean := false;
  v_bubble_shape_valid        boolean := false;
  v_escrow                    public.tournament_escrow%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required');
  END IF;

  SELECT t.id, t.status, round(COALESCE(t.prize_pool, 0), 2) AS prize_pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guaranteed_prize,
         COALESCE(t.prize_pool_finalized, false) AS prize_pool_finalized,
         COALESCE(t.bubble_protection, false) AS bubble_protection,
         round(COALESCE(t.buy_in_amount, 0), 2) AS buy_in_amount
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  SELECT * INTO v_batch
    FROM public.tournament_final_table_deal_batches b
   WHERE b.tournament_id = p_tournament_id;
  IF NOT FOUND OR v_batch.settled_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_batch_is_not_settled');
  END IF;
  IF md5(v_batch.live_input_snapshot::text)
       <> v_batch.live_input_fingerprint THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'atomic_deal_live_input_fingerprint_changed');
  END IF;
  IF md5(jsonb_build_object(
                            'bubble_contract_required', v_batch.bubble_contract_required,
                            'bubble_obligation_id', v_batch.bubble_obligation_id,
                            'bubble_user_id', v_batch.bubble_user_id,
                            'bubble_source', v_batch.bubble_source,
                            'bubble_amount_owed',
                              round(COALESCE(v_batch.bubble_amount_owed, 0) * 100)::bigint,
                            'bubble_amount_paid_before',
                              round(COALESCE(v_batch.bubble_amount_paid_before, 0) * 100)::bigint,
                            'deal_table_id', v_batch.deal_table_id,
                            'live_input_fingerprint', v_batch.live_input_fingerprint,
                            'prior_standings_fingerprint',
                              v_batch.prior_standings_fingerprint,
                            'plan', v_batch.plan)::text)
       <> v_batch.plan_fingerprint THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_plan_fingerprint_changed');
  END IF;
  IF NOT v_t.prize_pool_finalized
     OR v_t.prize_pool + 0.005 < v_t.guaranteed_prize THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prize_pool_is_not_funded_and_finalized');
  END IF;

  SELECT * INTO v_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id;
  IF NOT FOUND OR NOT v_escrow.enforced
     OR v_batch.escrow_prize_after IS NULL
     OR abs(v_batch.escrow_prize_before - v_batch.amount_moved
            - v_batch.escrow_prize_after) > 0.005
     OR abs(round(v_escrow.prize_balance, 2)
            - v_batch.escrow_prize_after) > 0.005 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'atomic_deal_escrow_proof_is_invalid');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(v_batch.plan) e
     WHERE jsonb_typeof(e) <> 'object'
        OR COALESCE(e->>'kind', '') NOT IN ('place', 'final_table_deal')
        OR COALESCE(e->>'user_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR COALESCE(e->>'cents', '') !~ '^[0-9]+$'
        OR ((e->>'kind') = 'place'
            AND (COALESCE(e->>'place', '') !~ '^[1-9][0-9]*$'
                 OR e->>'rank' IS NOT NULL))
        OR ((e->>'kind') = 'final_table_deal'
            AND (e->>'place' IS NOT NULL
                 OR COALESCE(e->>'rank', '') !~ '^[1-9][0-9]*$'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_plan_is_malformed');
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE x.kind = 'place'),
         count(*) FILTER (WHERE x.kind = 'final_table_deal'),
         count(DISTINCT x.place) FILTER (WHERE x.kind = 'place'),
         count(DISTINCT x.user_id) FILTER (WHERE x.kind = 'final_table_deal'),
         count(DISTINCT x.rank) FILTER (WHERE x.kind = 'final_table_deal'),
         COALESCE(min(x.rank) FILTER (WHERE x.kind = 'final_table_deal'), 0),
         COALESCE(max(x.rank) FILTER (WHERE x.kind = 'final_table_deal'), 0),
         COALESCE(sum(x.cents) FILTER (WHERE x.kind = 'place'), 0),
         COALESCE(sum(x.cents) FILTER (WHERE x.kind = 'final_table_deal'), 0)
    INTO v_line_count, v_place_lines, v_deal_lines, v_distinct_places,
         v_distinct_deal_users, v_distinct_deal_ranks,
         v_min_deal_rank, v_max_deal_rank, v_place_cents, v_deal_cents
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer);

  IF v_line_count <> v_batch.place_line_count + v_batch.deal_line_count
     OR v_place_lines <> v_batch.place_line_count
     OR v_deal_lines <> v_batch.deal_line_count
     OR v_distinct_places <> v_place_lines
     OR v_distinct_deal_users <> v_deal_lines
     OR v_distinct_deal_ranks <> v_deal_lines
     OR v_min_deal_rank <> 1 OR v_max_deal_rank <> v_deal_lines
     OR v_deal_lines <> v_batch.live_count
     OR v_place_cents <> round(v_batch.place_amount * 100)::bigint
     OR v_deal_cents <> round(v_batch.deal_amount * 100)::bigint
     OR v_place_cents + v_deal_cents <> round(v_batch.amount_owed * 100)::bigint
     OR round(v_batch.amount_owed * 100)::bigint <> round(v_t.prize_pool * 100)::bigint
     OR NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_batch.plan)
           AS leader(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE leader.kind = 'final_table_deal' AND leader.rank = 1
          AND leader.user_id = v_batch.chip_leader
     ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_header_disagrees_with_plan');
  END IF;

  /* Re-derive every deal share from the frozen pre-deal inputs. The live
     players are terminal by the time this verifier runs, and their physical
     seats may be torn down after completion, so the immutable snapshot is the
     allocation source while the frozen player columns prove that the snapshot
     still names the same chips and tie-break inputs. */
  IF jsonb_array_length(v_batch.live_input_snapshot) <> v_batch.live_count
     OR EXISTS (
       SELECT 1
         FROM jsonb_array_elements(v_batch.live_input_snapshot) e
        WHERE jsonb_typeof(e) <> 'object'
           OR COALESCE(e->>'player_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'user_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'seat_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'table_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'chips', '') !~ '^[0-9]+([.][0-9]+)?$'
           OR (e->>'chips')::numeric <= 0
           OR COALESCE(e->>'seat_stack', '') !~ '^[0-9]+([.][0-9]+)?$'
           OR (e->>'seat_stack')::numeric IS DISTINCT FROM (e->>'chips')::numeric
           OR COALESCE(e->>'registered_at_utc', '') !~
              '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}$'
           OR COALESCE(e->>'rebuys', '') !~ '^[0-9]+$'
           OR jsonb_typeof(e->'add_on') IS DISTINCT FROM 'boolean'
     ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_live_input_is_malformed');
  END IF;

  SELECT count(*), count(DISTINCT s.player_id), count(DISTINCT s.user_id),
         count(DISTINCT s.seat_id),
         count(*) FILTER (WHERE s.table_id IS DISTINCT FROM v_batch.deal_table_id)
    INTO v_snapshot_count, v_snapshot_distinct_players,
         v_snapshot_distinct_users, v_snapshot_distinct_seats,
         v_snapshot_wrong_tables
    FROM jsonb_to_recordset(v_batch.live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric);

  SELECT count(*) INTO v_snapshot_input_mismatches
    FROM jsonb_to_recordset(v_batch.live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric)
    LEFT JOIN public.tournament_players tp
      ON tp.id = s.player_id AND tp.tournament_id = p_tournament_id
     AND tp.user_id = s.user_id
   WHERE tp.id IS NULL
      OR tp.chips IS DISTINCT FROM s.chips
      OR to_char(tp.registered_at AT TIME ZONE 'UTC',
                 'YYYY-MM-DD"T"HH24:MI:SS.US') IS DISTINCT FROM s.registered_at_utc
      OR COALESCE(tp.rebuys, 0) IS DISTINCT FROM s.rebuys
      OR COALESCE(tp.add_on, false) IS DISTINCT FROM s.add_on;

  WITH input AS (
    SELECT s.user_id, s.chips, s.registered_at_utc,
           row_number() OVER (
             ORDER BY s.chips DESC, s.registered_at_utc ASC, s.user_id ASC
           )::integer AS rank,
           floor(s.chips / sum(s.chips) OVER ()
                 * round(v_batch.deal_amount * 100)::bigint)::bigint AS floor_cents
      FROM jsonb_to_recordset(v_batch.live_input_snapshot)
        AS s(player_id uuid, user_id uuid, chips numeric,
             registered_at_utc text, rebuys integer, add_on boolean,
             seat_id uuid, table_id uuid, seat_stack numeric)
  ), expected AS (
    SELECT i.user_id, i.rank,
           i.floor_cents + CASE WHEN i.rank = 1 THEN
             round(v_batch.deal_amount * 100)::bigint
               - sum(i.floor_cents) OVER ()
             ELSE 0 END AS cents
      FROM input i
  ), actual AS (
    SELECT x.user_id, x.rank, x.cents
      FROM jsonb_to_recordset(v_batch.plan)
        AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
     WHERE x.kind = 'final_table_deal'
  )
  SELECT count(*) INTO v_snapshot_share_mismatches
    FROM expected e
    FULL JOIN actual a USING (user_id)
   WHERE e.user_id IS NULL OR a.user_id IS NULL
      OR e.rank IS DISTINCT FROM a.rank
      OR e.cents IS DISTINCT FROM a.cents;

  SELECT count(*) INTO v_obligation_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    LEFT JOIN public.tournament_obligations o
      ON o.tournament_id = p_tournament_id
     AND o.kind = x.kind
     AND o.user_id = x.user_id
     AND ((x.kind = 'place' AND o.place = x.place)
          OR (x.kind = 'final_table_deal' AND o.place IS NULL))
   WHERE o.id IS NULL
      OR round(o.amount_owed * 100)::bigint <> x.cents
      OR round(o.amount_paid * 100)::bigint <> x.cents
      OR o.settled_at IS NULL;

  SELECT count(*) INTO v_extra_obligations
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind IN ('place', 'final_table_deal')
     AND NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_batch.plan)
           AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE x.kind = o.kind AND x.user_id = o.user_id
          AND ((x.kind = 'place' AND x.place = o.place)
               OR (x.kind = 'final_table_deal' AND o.place IS NULL))
     );

  SELECT count(*) INTO v_evidence_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    CROSS JOIN LATERAL (
      SELECT round(COALESCE(sum(p.amount), 0) * 100)::bigint AS cents
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.user_id = x.user_id
         AND ((x.kind = 'place'
               AND p.position = x.place
               AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                                 'late_reg_adjustment', 'clawback', 'spin_backpay',
                                 'overlay_backpay')
                    OR EXISTS (
                      SELECT 1 FROM public.tournament_obligations eo
                       WHERE eo.tournament_id = p_tournament_id
                         AND eo.kind = 'place' AND eo.place = x.place
                         AND eo.user_id = x.user_id
                         AND p.idempotency_key LIKE
                           'tourney:' || p_tournament_id::text || ':obl:' ||
                           eo.id::text || ':%'
                    )))
              OR (x.kind = 'final_table_deal'
                  AND p.position IS NULL
                  AND p.source = 'final_table_deal'))
    ) evidence
   WHERE evidence.cents <> x.cents;

  SELECT count(*) INTO v_unexpected_place_evidence
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.position IS NOT NULL
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR EXISTS (
                SELECT 1 FROM public.tournament_obligations eo
                 WHERE eo.tournament_id = p_tournament_id
                   AND eo.kind = 'place' AND eo.place = p.position
                   AND eo.user_id = p.user_id
                   AND p.idempotency_key LIKE
                     'tourney:' || p_tournament_id::text || ':obl:' ||
                     eo.id::text || ':%'
              ))
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE NOT EXISTS (
     SELECT 1
       FROM jsonb_to_recordset(v_batch.plan)
         AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
      WHERE x.kind = 'place' AND x.place = evidence.position
        AND x.user_id = evidence.user_id
   );

  SELECT count(*) INTO v_unexpected_deal_evidence
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'final_table_deal'
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE evidence.position IS NOT NULL
      OR NOT EXISTS (
        SELECT 1
          FROM jsonb_to_recordset(v_batch.plan)
            AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
         WHERE x.kind = 'final_table_deal' AND x.user_id = evidence.user_id
      );

  SELECT count(*) INTO v_prize_mismatches
    FROM public.tournament_players tp
    CROSS JOIN LATERAL (
      SELECT COALESCE(sum(x.cents), 0) AS cents
        FROM jsonb_to_recordset(v_batch.plan)
          AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
       WHERE x.user_id = tp.user_id
    ) expected
   WHERE tp.tournament_id = p_tournament_id
     AND round(COALESCE(tp.prize, 0) * 100)::bigint <> expected.cents;

  SELECT count(*) INTO v_standing_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    LEFT JOIN public.tournament_players tp
      ON tp.tournament_id = p_tournament_id AND tp.user_id = x.user_id
   WHERE tp.id IS NULL
      OR (x.kind = 'place'
          AND (tp.position IS DISTINCT FROM x.place OR tp.status <> 'eliminated'
               OR tp.eliminated_at IS NULL))
      OR (x.kind = 'final_table_deal'
          AND (tp.position IS DISTINCT FROM x.rank
               OR tp.status <> CASE WHEN x.rank = 1 THEN 'winner' ELSE 'eliminated' END
               OR (x.rank = 1 AND tp.eliminated_at IS NOT NULL)
               OR (x.rank > 1 AND tp.eliminated_at IS NULL)));

  SELECT count(*), count(*) FILTER (WHERE tp.position IS NULL),
         count(DISTINCT tp.position), COALESCE(min(tp.position), 0),
         COALESCE(max(tp.position), 0),
         count(*) FILTER (WHERE tp.status = 'winner'),
         count(*) FILTER (WHERE tp.status = 'winner' AND tp.position = 1),
         count(*) FILTER (WHERE tp.status NOT IN ('winner', 'eliminated')),
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.eliminated_at IS NULL)
    INTO v_player_count, v_unranked, v_distinct_positions,
         v_min_position, v_max_position, v_winners, v_winner_at_one,
         v_nonterminal, v_missing_bust_time
   FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* Ranks below the live chop belong to players who busted before the deal.
     Their exact suffix is determined by bust time, then immutable row id for
     equal timestamps: earliest bust finishes last. Recompute both the mapping
     and the stable UTC fingerprint on every verifier call. */
  WITH prior AS (
    SELECT tp.id, tp.user_id, tp.position, tp.eliminated_at,
           v_batch.field_count - (row_number() OVER (
             ORDER BY tp.eliminated_at ASC, tp.id ASC
           ))::integer + 1 AS canonical_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position > v_batch.live_count
  )
  SELECT count(*),
         count(*) FILTER (WHERE p.eliminated_at IS NULL),
         count(*) FILTER (WHERE p.position IS DISTINCT FROM p.canonical_position),
         md5(COALESCE(jsonb_agg(jsonb_build_object(
           'id', p.id, 'user_id', p.user_id, 'position', p.position,
           'eliminated_at_utc', to_char(
             p.eliminated_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US'))
           ORDER BY p.position, p.id), '[]'::jsonb)::text)
    INTO v_prior_count, v_prior_missing_bust_time,
         v_prior_canonical_mismatches, v_prior_standings_fingerprint
    FROM prior p;

  SELECT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.tournament_id = p_tournament_id
              AND o.kind = 'bubble_protection'
         ), EXISTS (
           SELECT 1 FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'bubble_protection'
         )
    INTO v_bubble_obligation_present, v_bubble_payout_present;
  v_bubble_shape_valid := v_t.buy_in_amount > 0
    AND v_batch.structure_place_count > 0
    AND v_player_count > v_batch.structure_place_count;
  v_bubble_required := (v_t.bubble_protection AND v_bubble_shape_valid)
    OR v_bubble_obligation_present OR v_bubble_payout_present;

  IF v_bubble_required AND v_bubble_shape_valid THEN
    SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
      INTO v_bubble_holders, v_bubble_user
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_batch.structure_place_count + 1;

    SELECT count(*),
           count(*) FILTER (WHERE o.user_id = v_bubble_user AND o.place IS NULL),
           COALESCE(max(o.amount_owed) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0),
           COALESCE(max(o.amount_paid) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0)
      INTO v_bubble_obligations, v_bubble_matching, v_bubble_owed, v_bubble_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'bubble_protection';

    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_bubble_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user AND p.position IS NULL
       AND p.source = 'bubble_protection';

    SELECT count(*) INTO v_bubble_conflicts
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p.source = 'bubble_protection'
           AND (p.position IS NOT NULL OR p.user_id IS DISTINCT FROM v_bubble_user)
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) unexpected_bubble;

    IF v_bubble_obligations = 1 AND v_bubble_matching = 1 THEN
      SELECT o.id, o.source, o.amount_owed, o.amount_paid, o.settled_at
        INTO v_bubble_obligation_id, v_bubble_source, v_bubble_owed,
             v_bubble_paid, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user;
    END IF;
  END IF;

  IF v_obligation_mismatches > 0 OR v_extra_obligations > 0
     OR v_evidence_mismatches > 0 OR v_unexpected_place_evidence > 0
     OR v_unexpected_deal_evidence > 0 OR v_prize_mismatches > 0
     OR v_standing_mismatches > 0
     OR v_prior_count <> v_batch.field_count - v_batch.live_count
     OR v_prior_missing_bust_time > 0
     OR v_prior_canonical_mismatches > 0
     OR v_prior_standings_fingerprint IS DISTINCT FROM
          v_batch.prior_standings_fingerprint
     OR v_player_count <> v_batch.field_count OR v_unranked > 0
     OR v_distinct_positions <> v_player_count
     OR v_min_position <> 1 OR v_max_position <> v_player_count
     OR v_winners <> 1 OR v_winner_at_one <> 1 OR v_nonterminal > 0
     OR v_missing_bust_time > 0
     OR v_snapshot_count <> v_batch.live_count
     OR v_snapshot_distinct_players <> v_batch.live_count
     OR v_snapshot_distinct_users <> v_batch.live_count
     OR v_snapshot_distinct_seats <> v_batch.live_count
     OR v_snapshot_wrong_tables > 0
     OR v_snapshot_input_mismatches > 0
     OR v_snapshot_share_mismatches > 0
     OR v_batch.bubble_contract_required IS DISTINCT FROM v_bubble_required
     OR (v_bubble_required
         AND (NOT v_bubble_shape_valid
              OR v_bubble_holders <> 1 OR v_bubble_user IS NULL
              OR v_bubble_obligations <> 1 OR v_bubble_matching <> 1
              OR v_bubble_obligation_id IS DISTINCT FROM v_batch.bubble_obligation_id
              OR v_bubble_user IS DISTINCT FROM v_batch.bubble_user_id
              OR v_bubble_source IS DISTINCT FROM v_batch.bubble_source
              OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicFinalTableDeal')
              OR abs(v_bubble_owed - v_t.buy_in_amount) > 0.005
              OR abs(v_bubble_owed - v_batch.bubble_amount_owed) > 0.005
              OR v_bubble_paid + 0.005 < v_batch.bubble_amount_paid_before
              OR v_bubble_paid + 0.005 < v_bubble_owed
              OR abs(v_bubble_paid - v_bubble_evidence) > 0.005
              OR v_bubble_settled_at IS NULL
              OR v_bubble_conflicts > 0))
     OR (NOT v_bubble_required
         AND (v_batch.bubble_obligation_id IS NOT NULL
              OR v_batch.bubble_user_id IS NOT NULL
              OR v_batch.bubble_source IS NOT NULL
              OR abs(v_batch.bubble_amount_owed) > 0.005
              OR abs(v_batch.bubble_amount_paid_before) > 0.005)) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_deal_evidence_is_incomplete',
      'obligation_mismatches', v_obligation_mismatches,
      'extra_obligations', v_extra_obligations,
      'evidence_mismatches', v_evidence_mismatches,
      'unexpected_place_evidence', v_unexpected_place_evidence,
      'unexpected_deal_evidence', v_unexpected_deal_evidence,
      'prize_mismatches', v_prize_mismatches,
      'standing_mismatches', v_standing_mismatches,
      'prior_players', v_prior_count,
      'prior_eliminated_without_time', v_prior_missing_bust_time,
      'prior_canonical_mismatches', v_prior_canonical_mismatches,
      'prior_standings_fingerprint_matches',
        v_prior_standings_fingerprint IS NOT DISTINCT FROM
          v_batch.prior_standings_fingerprint,
      'players', v_player_count, 'unranked', v_unranked,
      'distinct_positions', v_distinct_positions,
      'rank_range', jsonb_build_array(v_min_position, v_max_position),
      'winners', v_winners, 'winner_at_one', v_winner_at_one,
      'nonterminal', v_nonterminal,
      'eliminated_without_time', v_missing_bust_time,
      'live_input_rows', v_snapshot_count,
      'live_input_mismatches', v_snapshot_input_mismatches,
      'share_rederivation_mismatches', v_snapshot_share_mismatches,
      'bubble_obligations', v_bubble_obligations,
      'bubble_required', v_bubble_required,
      'bubble_shape_valid', v_bubble_shape_valid,
      'bubble_obligation_present', v_bubble_obligation_present,
      'bubble_payout_present', v_bubble_payout_present,
      'bubble_conflicts', v_bubble_conflicts);
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', NULL,
                            'tournament_id', p_tournament_id,
                            'deal_table_id', v_batch.deal_table_id,
                            'bubble_contract_required', v_batch.bubble_contract_required,
                            'chip_leader', v_batch.chip_leader,
                            'players', v_batch.live_count,
                            'amount_owed', v_batch.amount_owed,
                            'completed', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_verification_failed',
                            'detail', SQLERRM, 'sqlstate', SQLSTATE);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_finish_readiness(p_tournament_id uuid, p_winner_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_finish public.tournament_finish_receipts%ROWTYPE;
  v_kind text;
  v_failures jsonb := '[]'::jsonb;
  v_winner_count integer := 0;
  v_position_one_count integer := 0;
  v_canonical_winner uuid;
  v_position_one_winner uuid;
  v_open_players integer := 0;
  v_unranked integer := 0;
  v_duplicate_positions integer := 0;
  v_unsettled_obligations integer := 0;
  v_bad_place_evidence integer := 0;
  v_bad_player_prizes integer := 0;
  v_place_owed numeric := 0;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_escrow_found boolean := false;
  v_rake_expected numeric := 0;
  v_rake_recorded numeric;
  v_rake_destination text;
  v_rake_settled_at timestamptz;
  v_rake_attributed_at timestamptz;
  v_rake_found boolean := false;
  v_bounty public.tournament_bounty_completion_receipts%ROWTYPE;
  v_place_batch public.tournament_place_settlement_batches%ROWTYPE;
  v_deal public.tournament_final_table_deal_batches%ROWTYPE;
  v_satellite public.tournament_satellite_settlement_batches%ROWTYPE;
  v_domain_check jsonb;
  v_modern_place boolean := false;
  v_modern_deal boolean := false;
  v_bad_satellite_seats integer := 0;
  v_bad_satellite_outcomes integer := 0;
  v_satellite_award_gaps integer := 0;
BEGIN
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found',
      'failures',jsonb_build_array(jsonb_build_object('code','tournament_not_found')));
  END IF;
  v_kind := public.fn_tournament_finish_kind(p_tournament_id);
  IF v_kind='normal' THEN
    SELECT COALESCE((to_jsonb(b)->>'contract_version')::integer,1)=2
      INTO v_modern_place FROM public.tournament_place_settlement_batches b
     WHERE b.tournament_id=p_tournament_id;
  ELSIF v_kind='final_table_deal' THEN
    SELECT COALESCE((to_jsonb(b)->>'contract_version')::integer,1)=2
      INTO v_modern_deal FROM public.tournament_final_table_deal_batches b
     WHERE b.tournament_id=p_tournament_id;
  END IF;
  v_modern_place:=COALESCE(v_modern_place,false);
  v_modern_deal:=COALESCE(v_modern_deal,false);


  SELECT * INTO v_finish FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','finish_claim_missing'));
  ELSIF v_finish.winner_user_id IS DISTINCT FROM p_winner_user_id
     OR v_finish.finish_kind IS DISTINCT FROM v_kind THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','finish_claim_conflict','claimed_winner',v_finish.winner_user_id,
      'claimed_kind',v_finish.finish_kind,'observed_kind',v_kind));
  END IF;

  SELECT count(*), (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_winner_count, v_canonical_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'winner' AND tp.position = 1;
  SELECT count(*), (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_position_one_count, v_position_one_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id AND tp.position = 1;
  IF v_winner_count <> 1 OR v_position_one_count <> 1
     OR v_canonical_winner IS DISTINCT FROM p_winner_user_id
     OR v_position_one_winner IS DISTINCT FROM p_winner_user_id THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','canonical_winner_not_proven','winner_rows',v_winner_count,
      'position_one_rows',v_position_one_count,'observed_winner',v_canonical_winner,
      'requested_winner',p_winner_user_id));
  END IF;

  SELECT count(*) FILTER (WHERE tp.status IN ('registered','playing')),
         count(*) FILTER (WHERE tp.position IS NULL)
    INTO v_open_players, v_unranked
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_duplicate_positions
    FROM (
      SELECT tp.position FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position IS NOT NULL
       GROUP BY tp.position HAVING count(*) <> 1
    ) duplicates;
  IF v_open_players <> 0 OR v_unranked <> 0 OR v_duplicate_positions <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','standings_not_terminal','open_players',v_open_players,
      'unranked_players',v_unranked,'duplicate_positions',v_duplicate_positions));
  END IF;
  IF COALESCE(v_t.on_break,false) THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','terminal_break_flag_set'));
  END IF;

  SELECT count(*) INTO v_unsettled_obligations
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND abs(round(COALESCE(o.amount_paid,0),2)
           - round(COALESCE(o.amount_owed,0),2)) > 0.005;
  IF v_unsettled_obligations <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','unsettled_obligations','count',v_unsettled_obligations));
  END IF;

  -- Satellite prize history is one combined entitlement row (ticket value plus
  -- an optional cash remainder). Its format checker proves both constituent
  -- receipts exactly; comparing that cache to either receipt alone would
  -- falsely reject a short-field last-seat winner. The generic relation stays
  -- an independent certificate for every other format.
  IF v_kind <> 'satellite' AND NOT v_modern_place AND NOT v_modern_deal THEN
    SELECT count(*) INTO v_bad_place_evidence
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND o.amount_owed > 0
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = o.tournament_id
            AND tp.position = o.place AND tp.user_id = o.user_id
            AND abs(round(COALESCE(tp.prize,0),2) - round(o.amount_owed,2)) <= 0.005
       );
    SELECT count(*) INTO v_bad_player_prizes
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND round(COALESCE(tp.prize,0),2) > 0
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = tp.tournament_id AND o.kind = 'place'
            AND o.place = tp.position AND o.user_id = tp.user_id
            AND abs(round(o.amount_paid,2) - round(COALESCE(tp.prize,0),2)) <= 0.005
            AND abs(round(o.amount_owed,2) - round(o.amount_paid,2)) <= 0.005
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = tp.tournament_id AND o.kind = 'final_table_deal'
            AND o.user_id = tp.user_id
            AND abs(round(o.amount_paid,2) - round(COALESCE(tp.prize,0),2)) <= 0.005
            AND abs(round(o.amount_owed,2) - round(o.amount_paid,2)) <= 0.005
       );
  END IF;
  IF v_bad_place_evidence <> 0 OR v_bad_player_prizes <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','prize_evidence_mismatch','place_obligations',v_bad_place_evidence,
      'player_prizes',v_bad_player_prizes));
  END IF;

  IF v_kind = 'normal' THEN
    SELECT * INTO v_place_batch
      FROM public.tournament_place_settlement_batches b
     WHERE b.tournament_id = p_tournament_id;
    IF NOT FOUND OR v_place_batch.settled_at IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_place_batch_not_settled'));
    END IF;

    IF v_modern_place THEN
      BEGIN
        v_domain_check:=public.fn_ca_verify_terminal_place_batch(p_tournament_id,true);
        IF COALESCE((v_domain_check->>'ok')::boolean,false) IS NOT TRUE THEN
          RAISE EXCEPTION 'canonical place proof refused';
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_failures:=v_failures||jsonb_build_array(jsonb_build_object(
          'code','canonical_place_batch_not_proven','detail',SQLERRM));
      END;
    END IF;

    SELECT round(COALESCE(sum(o.amount_owed),0),2) INTO v_place_owed
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place';
    IF NOT v_modern_place AND abs(v_place_owed - round(COALESCE(v_t.prize_pool,0),2)) > 0.005 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','prize_pool_not_fully_obligated','prize_pool',v_t.prize_pool,
        'place_obligations',v_place_owed));
    END IF;
    IF round(COALESCE(v_t.guaranteed_prize,0),2)
         > round(COALESCE(v_t.prize_pool,0),2) + 0.005 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','guarantee_not_funded','guarantee',v_t.guaranteed_prize,
        'prize_pool',v_t.prize_pool));
    END IF;
  END IF;

  SELECT * INTO v_escrow FROM public.tournament_escrow
   WHERE tournament_id = p_tournament_id;
  v_escrow_found := FOUND;
  IF NOT v_escrow_found THEN
    IF COALESCE(v_t.prize_pool,0) <> 0 OR COALESCE(v_t.bounty_pool,0) <> 0
       OR COALESCE(v_t.total_rake,0) <> 0
       OR EXISTS (SELECT 1 FROM public.tournament_payouts po
                   WHERE po.tournament_id = p_tournament_id) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','escrow_evidence_missing'));
    END IF;
  ELSIF abs(round(v_escrow.prize_balance,2)) > 0.005
     OR abs(round(v_escrow.bounty_balance,2)) > 0.005
     OR abs(round(v_escrow.fee_balance,2)) > 0.005 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','escrow_not_zero','prize_balance',v_escrow.prize_balance,
      'bounty_balance',v_escrow.bounty_balance,'fee_balance',v_escrow.fee_balance));
  END IF;

  SELECT GREATEST(round(COALESCE(sum(rr.rake_amount),0),2),0) INTO v_rake_expected
    FROM public.rake_records rr
   WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament;
  SELECT amount,destination,settled_at,attributed_at
    INTO v_rake_recorded,v_rake_destination,v_rake_settled_at,v_rake_attributed_at
    FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id;
  v_rake_found := FOUND;
  IF NOT v_rake_found OR v_rake_settled_at IS NULL
     OR v_rake_attributed_at IS NULL OR v_rake_destination = 'pending'
     OR abs(round(COALESCE(v_rake_recorded,0),2) - v_rake_expected) > 0.005 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','rake_not_settled','expected',v_rake_expected,
      'recorded',CASE WHEN v_rake_found THEN v_rake_recorded ELSE NULL END,
      'destination',CASE WHEN v_rake_found THEN v_rake_destination ELSE NULL END,
      'attributed_at',CASE WHEN v_rake_found THEN v_rake_attributed_at ELSE NULL END));
  END IF;

  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','pending_bounty_obligations'));
    END IF;
    SELECT * INTO v_bounty FROM public.tournament_bounty_completion_receipts
     WHERE tournament_id = p_tournament_id;
    IF NOT FOUND OR v_bounty.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR v_bounty.pool_finalized_at IS NULL
       OR COALESCE((v_bounty.pool_result->>'ok')::boolean,false) IS NOT TRUE THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','bounty_pool_not_certified'));
    END IF;
    IF COALESCE(v_t.is_mystery_bounty,false)
       AND COALESCE(v_t.mystery_bounty_stage,'pending') <> 'pending'
       AND (v_bounty.mystery_settled_at IS NULL
            OR COALESCE((v_bounty.mystery_result->>'ok')::boolean,false) IS NOT TRUE
            OR COALESCE((v_bounty.mystery_result->>'balanced')::boolean,false) IS NOT TRUE) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','mystery_bounty_not_certified'));
    END IF;
  END IF;

  IF v_kind = 'final_table_deal' THEN
    SELECT * INTO v_deal FROM public.tournament_final_table_deal_batches
     WHERE tournament_id = p_tournament_id;
    IF NOT FOUND OR v_deal.chip_leader IS DISTINCT FROM p_winner_user_id
       OR v_deal.settled_at IS NULL OR v_deal.escrow_prize_after IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_final_table_deal_batch_not_settled'));
    ELSE
      IF v_modern_deal THEN
        BEGIN
          v_domain_check:=public.fn_ca_verify_terminal_final_deal_batch(p_tournament_id,true);
        EXCEPTION WHEN OTHERS THEN
          v_domain_check:=jsonb_build_object('ok',false,'reason',SQLERRM);
        END;
      ELSE
        v_domain_check := public.fn_check_atomic_final_table_deal(p_tournament_id);
      END IF;
      IF COALESCE((v_domain_check->>'ok')::boolean,false) IS NOT TRUE THEN
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'code','atomic_final_table_deal_not_proven','detail',v_domain_check));
      END IF;
    END IF;
  END IF;

  IF v_kind = 'satellite' THEN
    SELECT * INTO v_satellite
      FROM public.tournament_satellite_settlement_batches b
     WHERE b.tournament_id = p_tournament_id;
    IF NOT FOUND OR v_satellite.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR v_satellite.settled_at IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_satellite_batch_not_settled'));
    ELSE
      v_domain_check := public.fn_check_atomic_satellite_finish(p_tournament_id);
      IF COALESCE((v_domain_check->>'ok')::boolean,false) IS NOT TRUE THEN
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'code','atomic_satellite_finish_not_proven','detail',v_domain_check));
      END IF;
    END IF;

    SELECT count(*) INTO v_bad_satellite_seats
      FROM public.tournament_players target_seat
     WHERE target_seat.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_payouts po
          WHERE po.tournament_id = p_tournament_id
            AND po.source = 'satellite_seat'
            AND po.user_id = target_seat.user_id
            AND po.metadata->>'registration_id' = target_seat.id::text
       );
    IF v_bad_satellite_seats <> 0 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','satellite_seat_evidence_missing','count',v_bad_satellite_seats));
    END IF;

    -- Every in-kind payout names the original finisher/place and the exact
    -- target registration it funded. A payout row by itself is not a seat,
    -- and a target seat by itself is not a durable payout record.
    SELECT count(*) INTO v_bad_satellite_outcomes
      FROM public.tournament_payouts po
     WHERE po.tournament_id = p_tournament_id AND po.source = 'satellite_seat'
       AND (po."position" IS NULL
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_players finisher
               WHERE finisher.tournament_id = p_tournament_id
                 AND finisher.user_id = po.user_id
                 AND finisher.position = po."position"
            )
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_players target_seat
               WHERE target_seat.id::text = po.metadata->>'registration_id'
                 AND target_seat.user_id = po.user_id
                 AND target_seat.source_satellite_id = p_tournament_id
            ));

    -- Seat awards and cash ticket fallbacks form a top-finisher prefix. A gap
    -- means a lower place was paid while a higher promised place was skipped.
    WITH awarded_positions AS (
      SELECT po."position" AS place
        FROM public.tournament_payouts po
       WHERE po.tournament_id = p_tournament_id
         AND po.source = 'satellite_seat' AND po."position" IS NOT NULL
      UNION
      SELECT o.place
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
         AND o.place IS NOT NULL AND round(o.amount_paid,2) > 0
         AND abs(round(o.amount_paid,2)-round(o.amount_owed,2)) <= 0.005
    ), bounds AS (SELECT max(place) AS max_place FROM awarded_positions)
    SELECT count(*) INTO v_satellite_award_gaps
      FROM bounds b
      CROSS JOIN LATERAL generate_series(1,b.max_place) expected(place)
     WHERE b.max_place IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM awarded_positions a WHERE a.place=expected.place);

    IF v_bad_satellite_outcomes <> 0 OR v_satellite_award_gaps <> 0
       OR EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id
            AND o.kind = 'satellite_remainder'
            AND NOT EXISTS (
              SELECT 1 FROM public.tournament_players tp
               WHERE tp.tournament_id=p_tournament_id AND tp.user_id=o.user_id
            )
       ) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','satellite_awards_not_certified',
        'invalid_outcomes',v_bad_satellite_outcomes,
        'award_gaps',v_satellite_award_gaps));
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok',jsonb_array_length(v_failures) = 0,
    'reason',CASE WHEN jsonb_array_length(v_failures) = 0 THEN NULL
                  ELSE v_failures->0->>'code' END,
    'tournament_id',p_tournament_id,'winner_user_id',p_winner_user_id,
    'finish_kind',v_kind,'failures',v_failures,
    'financials',jsonb_build_object(
      'unsettled_obligations',v_unsettled_obligations,
      'place_obligations',v_place_owed,
      'rake_expected',v_rake_expected,
      'prize_balance',CASE WHEN v_escrow_found THEN v_escrow.prize_balance ELSE NULL END,
      'bounty_balance',CASE WHEN v_escrow_found THEN v_escrow.bounty_balance ELSE NULL END,
      'fee_balance',CASE WHEN v_escrow_found THEN v_escrow.fee_balance ELSE NULL END));
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_entry_purchases_frozen()
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
           SELECT 1
             FROM public.engine_maintenance_break b
            WHERE b.enforce_freeze
              AND b.announced_at < clock_timestamp() + INTERVAL '30 seconds'
              AND (
                (
                  b.phase = 'last_hand'
                  AND b.break_started_at IS NULL
                  AND b.break_ends_at IS NULL
                )
                OR (
                  b.phase = 'counting_down'
                  AND b.break_started_at IS NOT NULL
                  AND b.break_ends_at IS NOT NULL
                  AND b.break_started_at >= b.announced_at
                  AND b.break_ends_at > b.break_started_at
                  AND b.break_ends_at < b.announced_at + INTERVAL '15 minutes'
                )
              )
         )
         OR COALESCE(
           public.fn_active_maintenance_release_boundary() > clock_timestamp(),
           false
         );
$function$;
CREATE OR REPLACE FUNCTION public.fn_lock_tournament_launch_proof_parents(p_tournament_ids uuid[])
 RETURNS TABLE(tournament_id uuid, parent_status text, launch_id uuid, launch_lease_generation uuid, launch_completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT requested.id ORDER BY requested.id)
    INTO v_ids
    FROM unnest(p_tournament_ids) AS requested(id)
   WHERE requested.id IS NOT NULL;

  IF v_ids IS NULL THEN
    RETURN;
  END IF;

  /* Do not invert these two blocks.  Launch completion already owns receipt
     -> parent, and every child must join that order. */
  /* A few legacy RPCs entered with the tournament parent already locked.
     Waiting for a receipt owned by completion would make a cycle: completion
     waits for their parent while they wait for its receipt.  Fail that outer
     transaction as retryable instead of waiting; a clean retry enters this
     helper before touching another launch-proof row. */
  BEGIN
    PERFORM 1
      FROM public.tournament_launch_receipts r
     WHERE r.tournament_id = ANY(v_ids)
     ORDER BY r.tournament_id
     FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION
      'TOURNAMENT_TRANSITION_BUSY: launch proof receipt is changing'
      USING ERRCODE = '40001';
  END;

  PERFORM 1
    FROM public.tournaments t
   WHERE t.id = ANY(v_ids)
   ORDER BY t.id
   FOR UPDATE;

  IF EXISTS (
    SELECT 1
      FROM unnest(v_ids) AS requested(id)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.tournaments t WHERE t.id = requested.id
     )
  ) THEN
    RAISE EXCEPTION 'tournament launch proof child names a missing parent'
      USING ERRCODE = '23503';
  END IF;

  RETURN QUERY
    SELECT t.id,
           t.status::text,
           r.launch_id,
           r.lease_generation,
           r.completed_at
      FROM public.tournaments t
      LEFT JOIN public.tournament_launch_receipts r
        ON r.tournament_id = t.id
     WHERE t.id = ANY(v_ids)
     ORDER BY t.id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_charge_split(p_tournament_id uuid, p_charge_category text, p_gross numeric)
 RETURNS TABLE(refund_prize numeric, refund_bounty numeric, refund_fee numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_entry record;
  v_kind text := lower(btrim(COALESCE(p_charge_category,'')));
  v_gross numeric := round(COALESCE(p_gross,0),2);
  v_is_bounty boolean;
  v_ratio numeric;
  v_fee numeric;
  v_bounty numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_gross IS NULL
     OR p_gross::text IN ('NaN','Infinity','-Infinity')
     OR p_gross IS DISTINCT FROM v_gross OR v_gross <= 0
     OR v_kind NOT IN ('tournament_buyin','rebuy','addon') THEN
    RAISE EXCEPTION 'tournament charge split received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  SELECT t.buy_in_amount,t.buy_in_fee,t.bounty_amount,
         t.is_bounty,t.is_pko,t.is_mystery_bounty
    INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament charge split has no tournament %',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  v_is_bounty := COALESCE(v_t.is_bounty,false)
              OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_kind='tournament_buyin' THEN
    SELECT * INTO v_entry FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
    IF v_entry.charge IS DISTINCT FROM v_gross THEN
      RAISE EXCEPTION
        'tournament buy-in ledger amount % does not match its funded split %',
        v_gross,v_entry.charge USING ERRCODE = '23514';
    END IF;
    refund_prize := v_entry.prize;
    refund_bounty := v_entry.bounty;
    refund_fee := v_entry.rake;
  ELSIF v_kind='addon' THEN
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'add-on charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    refund_prize := v_gross;
    refund_bounty := 0;
    refund_fee := 0;
  ELSE
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'rebuy charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    v_ratio := public.fn_ca_tournament_fee_ratio(
      v_t.buy_in_amount, v_t.buy_in_fee);
    v_fee := public.fn_ca_recovery_fee_cents(
      round(v_gross*100)::bigint, v_ratio,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100;    v_bounty := CASE WHEN v_is_bounty THEN
      public.fn_ca_unit_floor_cents(
        round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),
                    v_gross-v_fee)*100)::bigint,
        public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100
      ELSE 0 END;
    refund_fee := v_fee;
    refund_bounty := v_bounty;
    refund_prize := round(v_gross-v_fee-v_bounty,2);
  END IF;
  IF refund_prize IS NULL OR refund_bounty IS NULL OR refund_fee IS NULL
     OR refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR refund_prize < 0 OR refund_bounty < 0 OR refund_fee < 0
     OR v_gross IS DISTINCT FROM
          round(refund_prize+refund_bounty+refund_fee,2) THEN
    RAISE EXCEPTION 'tournament charge split produced invalid component rails'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEXT;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_escrow_apply_exact_refund(p_tournament_id uuid, p_what text, p_refund_prize numeric, p_refund_bounty numeric, p_refund_fee numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.tournament_escrow%ROWTYPE;
  v_prize numeric := round(COALESCE(p_refund_prize,0),2);
  v_bounty numeric := round(COALESCE(p_refund_bounty,0),2);
  v_fee numeric := round(COALESCE(p_refund_fee,0),2);
BEGIN
  IF p_tournament_id IS NULL
     OR p_refund_prize IS NULL OR p_refund_bounty IS NULL OR p_refund_fee IS NULL
     OR p_refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_prize < 0 OR p_refund_bounty < 0 OR p_refund_fee < 0
     OR p_refund_prize IS DISTINCT FROM v_prize
     OR p_refund_bounty IS DISTINCT FROM v_bounty
     OR p_refund_fee IS DISTINCT FROM v_fee
     OR v_prize + v_bounty + v_fee <= 0 THEN
    RAISE EXCEPTION 'exact refund requires finite nonnegative whole-cent rails'
      USING ERRCODE = '22003';
  END IF;

  UPDATE public.tournament_escrow
     SET refund_prize = refund_prize + v_prize,
         refund_bounty = refund_bounty + v_bounty,
         refund_fee = refund_fee + v_fee,
         prize_balance = round(
           (gross_in - fee_entries_in - bounty_in) + overlay_in + satellite_in
           - reserve_out + reserve_in - prize_out - refund_prize - v_prize,2),
         bounty_balance = round(
           bounty_in - bounty_out - refund_bounty - v_bounty,2),
         fee_balance = round(
           fee_entries_in + satellite_fee_in - fee_out - refund_fee - v_fee,2),
         updated_at = now()
   WHERE tournament_id = p_tournament_id
   RETURNING * INTO v;
  IF v.tournament_id IS NULL OR v.enforced IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'exact refund escrow for tournament % is absent or unenforced',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v.prize_balance IS NULL OR v.bounty_balance IS NULL OR v.fee_balance IS NULL
     OR v.refund_prize IS NULL OR v.refund_bounty IS NULL OR v.refund_fee IS NULL
     OR v.prize_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.bounty_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.fee_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR v.prize_balance IS DISTINCT FROM round(v.prize_balance,2)
     OR v.bounty_balance IS DISTINCT FROM round(v.bounty_balance,2)
     OR v.fee_balance IS DISTINCT FROM round(v.fee_balance,2)
     OR v.refund_prize IS DISTINCT FROM round(v.refund_prize,2)
     OR v.refund_bounty IS DISTINCT FROM round(v.refund_bounty,2)
     OR v.refund_fee IS DISTINCT FROM round(v.refund_fee,2)
     OR v.prize_balance < -0.005
     OR v.bounty_balance < -0.005
     OR v.fee_balance < -0.005 THEN
    RAISE EXCEPTION
      'escrow_short: tournament % cannot pay exact % rails %, %, %; balances would be %, %, %',
      p_tournament_id,p_what,v_prize,v_bounty,v_fee,
      v.prize_balance,v.bounty_balance,v.fee_balance USING ERRCODE = 'P0403';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_terminal_marker_transition_is_exact(p_old jsonb, p_new jsonb, p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    p_old ? 'terminal_closed_at'
    AND p_new ? 'terminal_closed_at'
    AND NULLIF(p_old->>'terminal_closed_at','') IS NULL
    AND NULLIF(p_new->>'terminal_closed_at','') IS NOT NULL
    AND (p_new - 'terminal_closed_at') IS NOT DISTINCT FROM
        (p_old - 'terminal_closed_at')
    AND EXISTS (
      SELECT 1
        FROM public.tournaments t
       WHERE t.id = p_tournament_id
         AND upper(COALESCE(t.status::text,'')) IN
             ('COMPLETED','CANCELLED','CANCELED')
         AND t.ended_at IS NOT NULL
         AND isfinite(t.ended_at)
         AND NULLIF(p_new->>'terminal_closed_at','')::timestamptz
               IS NOT DISTINCT FROM t.ended_at
    ),false)
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_has_committed_tournament_receipt(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    SELECT (upper(COALESCE(t.status::text,'')) = 'COMPLETED'
       AND (EXISTS (
              SELECT 1 FROM public.tournament_terminal_settlements h
               WHERE h.tournament_id = t.id)
         OR EXISTS (
              SELECT 1 FROM public.tournament_satellite_settlements h
               WHERE h.tournament_id = t.id)))
       OR (upper(COALESCE(t.status::text,'')) IN ('CANCELLED','CANCELED')
       AND EXISTS (
              SELECT 1 FROM public.tournament_cancellation_receipts h
               WHERE h.tournament_id = t.id))
      FROM public.tournaments t
     WHERE t.id = p_tournament_id
  ),false)
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_felt_total(p_tournament_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(sum(ts.stack),0)
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id=ts.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND ts.left_at IS NULL;
$function$;
CREATE OR REPLACE FUNCTION public.fn_mystery_bounty_creation_document(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_profile text:=coalesce(p_config->>'mysteryBountyProfile','classic');
  v_activation text:=coalesce(p_config->>'mysteryBountyActivation','at_the_money');
  v_value jsonb:=coalesce(p_config->'mysteryBountyActivationValue','null'::jsonb);
  v_pool jsonb:=coalesce(nullif(p_config->'mysteryBountyPoolPercent','null'::jsonb),'50'::jsonb);
  v_top jsonb:=coalesce(nullif(p_config->'mysteryBountyTopPercent','null'::jsonb),'20'::jsonb);
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object' THEN
    RAISE EXCEPTION 'Invalid mystery bounty configuration' USING ERRCODE='22023';
  END IF;
  IF v_profile NOT IN ('balanced','classic','jackpot') THEN
    RAISE EXCEPTION 'Invalid mystery bounty profile' USING ERRCODE='22023';
  END IF;
  IF v_activation NOT IN ('at_the_money','percent_field','player_count') THEN
    RAISE EXCEPTION 'Invalid mystery bounty activation' USING ERRCODE='22023';
  END IF;
  IF v_activation<>'at_the_money' THEN
    IF jsonb_typeof(v_value)<>'number' THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation value' USING ERRCODE='22023';
    END IF;
    IF v_activation='percent_field' AND ((v_value#>>'{}')::numeric<=0 OR (v_value#>>'{}')::numeric>100) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation percentage' USING ERRCODE='22023';
    END IF;
    IF v_activation='player_count' AND ((v_value#>>'{}')::numeric<2
       OR (v_value#>>'{}')::numeric>9007199254740991
       OR trunc((v_value#>>'{}')::numeric)<>(v_value#>>'{}')::numeric) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation player count' USING ERRCODE='22023';
    END IF;
  ELSE
    v_value:='null'::jsonb;
  END IF;
  IF jsonb_typeof(v_pool)<>'number' OR jsonb_typeof(v_top)<>'number' THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage type' USING ERRCODE='22023';
  END IF;
  IF (v_pool#>>'{}')::numeric<0 OR (v_pool#>>'{}')::numeric>100
     OR trunc((v_pool#>>'{}')::numeric*100)<>(v_pool#>>'{}')::numeric*100
     OR (v_top#>>'{}')::numeric<=0 OR (v_top#>>'{}')::numeric>100 THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage range' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('mystery_bounty_profile',v_profile,
    'mystery_bounty_activation',v_activation,'mystery_bounty_activation_value',v_value,
    'mystery_bounty_pool_percent',v_pool,'mystery_bounty_regular_pool_percent',100-(v_pool#>>'{}')::numeric,
    'mystery_bounty_top_percent',v_top);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_is_unsafe_url(p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_host text;
BEGIN
    -- NULL / empty → safe (means no image set)
    IF p_url IS NULL OR length(btrim(p_url)) = 0 THEN
        RETURN false;
    END IF;

    -- 2 KiB cap to keep logs/queries sane
    IF length(p_url) > 2048 THEN
        RETURN true;
    END IF;

    -- Reject NULs + control chars (incl. \r \n \t \b etc)
    IF p_url ~ '[\x00-\x1F\x7F]' THEN
        RETURN true;
    END IF;

    -- Protocol-relative //host/... is ambiguous outside HTML and not needed.
    -- Reject before the relative-path check below.
    IF p_url ~ '^//' THEN
        RETURN true;
    END IF;

    -- Relative absolute path (e.g. "/smarter-poker-logo.png") is SAFE.
    -- Cannot cause SSRF (not a fetchable URL) and resolves same-origin in <img>.
    IF p_url ~ '^/[^/]' THEN
        RETURN false;
    END IF;

    -- Require http:// or https:// explicitly
    IF NOT (p_url ~* '^https?://') THEN
        RETURN true;
    END IF;

    -- Extract hostname; strip userinfo (user:pass@) if present
    v_host := lower(regexp_replace(p_url, '^https?://(?:[^@/]+@)?([^/?#:]+).*$', '\1', 'i'));

    -- localhost + no-dot hostnames (covers 'localhost', 'admin', 'intranet', etc.)
    IF v_host = 'localhost' OR v_host NOT LIKE '%.%' THEN
        RETURN true;
    END IF;

    -- IPv4 private / reserved ranges
    IF v_host ~ '^(127\.|10\.|0\.|169\.254\.|192\.168\.)' THEN
        RETURN true;
    END IF;
    IF v_host ~ '^172\.(1[6-9]|2[0-9]|3[0-1])\.' THEN
        RETURN true;
    END IF;

    -- IPv6 loopback / unique-local / link-local
    IF v_host ~ '^\[?(::1|::|fc[0-9a-f]{2}:|fd[0-9a-f]{2}:|fe[89ab][0-9a-f]:)' THEN
        RETURN true;
    END IF;

    -- Clean
    RETURN false;
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_reserved_username(p_username text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text;
  v_exact text[] := ARRAY[
    -- System / admin
    'admin','administrator','root','sudo','superuser','system','sys','default',
    'staff','owner','mod','moderator','manager','team','official','officials',
    'verified','certified','authentic','authorized','employee','employees',
    'founder','ceo','cto','cfo','coo','exec','executive',
    -- Support / contact
    'support','helpdesk','helpcenter','helpcentre','help','helpme','helpus',
    'contact','contactus','contact_us','info','inquiry','hello','hi',
    'customerservice','customer_service','customersupport','customer_support',
    'cs','csr','faq','feedback','report','abuse',
    -- Brand: Smarter.Poker
    'smarter','smarterpoker','smartpoker','smarter_poker','smarter.poker',
    'smarter_pkr','smarterpkr','smarter_official','smarterofficial',
    'smarter_support','smarter_team','smarter_admin','smarter_help',
    'smarter_staff','smarter_mod','smarterpoker_official','smarterpoker_team',
    'smarterpoker_support','smarterpoker_admin','smarterpoker_help',
    'sp_official','sp_support','sp_admin','sp_team',
    -- Sub-products
    'jarvis','geeves','pokerbrain','poker_brain','clubarena','club_arena',
    'clubcommander','club_commander','clubcomm','pokernearme','poker_near_me',
    -- Founder / known accounts
    'kingfish','danbekavac','dan_bekavac','dan.bekavac','bekavac','dbekavac',
    -- Generic AI / bots
    'bot','robot','ai','gpt','chatgpt','claude','openai','anthropic',
    -- Web / dev infra
    'api','apis','www','web','app','apps','mobile','http','https','ftp',
    'dev','prod','staging','localhost','test','testing','demo','example',
    'sample','samples',
    -- Auth / security
    'password','passwd','login','signup','signin','signout','logout',
    'register','security','auth','authentication','oauth','sso','session',
    'token','mfa','2fa','otp','verify','verification',
    -- Communication
    'email','mail','postmaster','webmaster','hostmaster','noreply','no_reply',
    'mailer','mailerdaemon','newsletter',
    -- Money / finance
    'money','cash','bank','banking','wallet','treasury','payment','payments',
    'billing','invoice','stripe','paypal','venmo','cashapp','zelle','square',
    'applepay','googlepay','plaid',
    -- Poker terms
    'poker','dealer','tournament','tournaments','cashier','casino','casinos',
    'vip','vips','premium','pro','pros','gold','silver','platinum',
    'diamond','diamonds','chip','chips','table','tables','lobby',
    -- Competitor / impersonation
    'pokerstars','ggpoker','partypoker','888poker','americascardroom','acr',
    'wsop','worldseries','pokerbros','clubgg','pokerrrr','suprema','pokerdom',
    'naturalpoker','x-poker','xpoker',
    -- Scam / spam
    'free','freemoney','free_money','winner','winners','prize','jackpot',
    'lottery','claim','claimnow','claim_now','urgent','alert','warning',
    'notice','security_alert','account_locked','password_reset','verify_now',
    -- Generic placeholders
    'null','undefined','nil','none','void','anonymous','anon','guest','user',
    'users','everyone','all','nobody','somebody','default','me','you','i',
    -- Edge cases
    'dot','period','underscore','hyphen','space','tab'
  ];
BEGIN
  v := lower(trim(both ' @' from coalesce(p_username, '')));
  IF v IS NULL OR v = '' THEN RETURN true; END IF;

  -- Exact-match
  IF v = ANY(v_exact) THEN RETURN true; END IF;

  -- Prefix patterns - brand impersonation
  IF v ~ '^smarter[._]'      THEN RETURN true; END IF;  -- smarter_X, smarter.X
  IF v ~ '^smarterpoker'     THEN RETURN true; END IF;  -- anything starting with smarterpoker
  IF v ~ '^smartpoker'       THEN RETURN true; END IF;
  IF v ~ '^smarterpkr'       THEN RETURN true; END IF;
  IF v ~ '^jarvis[._0-9]'    THEN RETURN true; END IF;
  IF v ~ '^geeves[._0-9]'    THEN RETURN true; END IF;
  IF v ~ '^kingfish'         THEN RETURN true; END IF;  -- kingfish*, no impersonation of Dan
  IF v ~ '^bekavac'          THEN RETURN true; END IF;
  IF v ~ '^danbekavac'       THEN RETURN true; END IF;
  IF v ~ '^pokerbrain'       THEN RETURN true; END IF;
  IF v ~ '^clubarena'        THEN RETURN true; END IF;
  IF v ~ '^clubcommander'    THEN RETURN true; END IF;

  -- Prefix patterns - system role impersonation (must have separator to avoid blocking 'admins'-as-substring etc)
  IF v ~ '^admin[._]'        THEN RETURN true; END IF;
  IF v ~ '^support[._]'      THEN RETURN true; END IF;
  IF v ~ '^staff[._]'        THEN RETURN true; END IF;
  IF v ~ '^official[._]'     THEN RETURN true; END IF;
  IF v ~ '^moderator[._]'    THEN RETURN true; END IF;
  IF v ~ '^help[._]'         THEN RETURN true; END IF;

  -- Suffix patterns - system role impersonation
  IF v ~ '_admin$'           THEN RETURN true; END IF;
  IF v ~ '_support$'         THEN RETURN true; END IF;
  IF v ~ '_staff$'           THEN RETURN true; END IF;
  IF v ~ '_official$'        THEN RETURN true; END IF;
  IF v ~ '_team$'            THEN RETURN true; END IF;
  IF v ~ '_mod$'             THEN RETURN true; END IF;
  IF v ~ '_moderator$'       THEN RETURN true; END IF;
  IF v ~ '_help$'            THEN RETURN true; END IF;

  RETURN false;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_is_service_context()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_raw_claims text;
    v_jwt_role   text;
BEGIN
    v_raw_claims := current_setting('request.jwt.claims', true);

    IF v_raw_claims IS NOT NULL
       AND btrim(v_raw_claims) <> ''
       AND btrim(v_raw_claims) <> 'null'
    THEN
        BEGIN
            v_jwt_role := v_raw_claims::jsonb ->> 'role';
        EXCEPTION WHEN others THEN
            -- Unparseable claims: fail CLOSED. A malformed JWT must never be
            -- mistaken for "no JWT".
            RETURN false;
        END;

        RETURN v_jwt_role = 'service_role';
    END IF;

    -- No JWT context.
    IF current_user IN ('anon', 'authenticated') THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_player_display_name(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
