                              p.first_name, p.last_name, p.full_name)
    FROM public.profiles p
   WHERE p.id = p_user_id;
$function$;
CREATE OR REPLACE FUNCTION public.fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_after numeric;
BEGIN
  /* ZERO-DRIFT phase 6: declare the ledger identity of the spin margin flow.
     Positive delta = spin margin landing with the owner (rake, from the spin
     reserve); negative delta = the owner funding the spin pool (overlay). */
  PERFORM public.fn_ca_declare_ledger(
    CASE WHEN p_delta >= 0 THEN 'rake' ELSE 'overlay' END, 'spin_reserve');

  IF p_owner_kind = 'union' THEN
    IF p_wallet NOT IN ('chip_balance','promo_wallet','rake_wallet','spin_reserve_wallet') THEN
      RAISE EXCEPTION 'unknown union wallet %', p_wallet;
    END IF;

    PERFORM set_config('app.uwt_selfjournal', '1', true);

    EXECUTE format(
      'UPDATE public.union_wallets SET %I = %I + $1, updated_at = now()
        WHERE union_id = $2 AND %I + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;

    IF v_after IS NOT NULL AND round(p_delta, 2) <> 0 THEN
      INSERT INTO public.union_wallet_transactions
        (union_id, wallet, direction, amount, balance_after, tx_type, notes)
      VALUES
        (p_owner_id, p_wallet,
         CASE WHEN p_delta > 0 THEN 'credit' ELSE 'debit' END,
         abs(round(p_delta, 2)), v_after,
         CASE WHEN p_delta > 0 THEN 'spin_seed_return' ELSE 'spin_pool_funding' END,
         CASE WHEN p_delta > 0
              THEN 'Spin reserve seed instalment returned to the union '
                || p_wallet || ' (fn_spin_move_owner_wallet)'
              ELSE 'Union ' || p_wallet || ' funded the spin reserve '
                || '(fn_spin_move_owner_wallet)' END);
    END IF;

    PERFORM set_config('app.uwt_selfjournal', '', true);
  ELSE
    IF p_wallet NOT IN ('chip_treasury','promo_balance') THEN
      RAISE EXCEPTION 'unknown club wallet %', p_wallet;
    END IF;
    EXECUTE format(
      'UPDATE public.clubs SET %I = COALESCE(%I,0) + $1
        WHERE id = $2 AND COALESCE(%I,0) + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;
  END IF;
  RETURN v_after;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_next_player_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate bigint;
  v_tries     int := 0;
BEGIN
  LOOP
    v_candidate := nextval('public.player_number_seq');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.profiles WHERE player_number = v_candidate::text
    );
    v_tries := v_tries + 1;
    IF v_tries > 1000 THEN
      RAISE EXCEPTION 'fn_next_player_number: no free player number after 1000 attempts';
    END IF;
  END LOOP;
  RETURN v_candidate::text;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bal numeric; v_seed numeric; v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_absorb');
  END IF;

  SELECT balance, seeded_amount INTO v_bal, v_seed
    FROM public.spin_bonus_pools WHERE club_id = p_club_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'club_had_no_pool');
  END IF;

  IF COALESCE(v_bal,0) > 0 THEN
    v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bal);
    IF v_after IS NULL THEN
      RAISE EXCEPTION 'cannot return the % Spins balance of club % to its treasury', v_bal, p_club_id;
    END IF;

    INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
    VALUES (p_club_id, 'merge', -v_bal, 0,
            format('Spins wallet closed on joining union %s - entire balance (including %s of outstanding seed) paid to the club main bank, to keep or disburse at its own discretion',
                   p_union_id, COALESCE(v_seed,0)));
  END IF;

  UPDATE public.spin_bonus_pools
     SET balance = 0, seeded_amount = 0, required_seed_at_activation = 0,
         seed_source_wallet = NULL, offered_max_stake = 0,
         is_active = false, deactivated_at = now(), updated_at = now()
   WHERE club_id = p_club_id;

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'paid_to_main_bank', COALESCE(v_bal,0), 'club_treasury_after', v_after);
END;
$function$;
CREATE OR REPLACE FUNCTION public.sp_cosmetic_is_owned(p_user uuid, p_token text, p_kind text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_token    text := public.sp_normalize_cosmetic_token(p_token);
  v_is_vip   boolean;
  v_free     text[] := ARRAY[
    'frame_slate', 'frame_ivory', 'frame_copper',
    'aura_mist',   'aura_dusk',   'aura_moss'
  ];
  v_catalog  text[] := ARRAY[
    'frame_gold', 'frame_diamond', 'frame_cyber', 'frame_hellfire',
    'aura_fire',  'aura_glitch',
    'frame_slate', 'frame_ivory', 'frame_copper',
    'aura_mist',   'aura_dusk',   'aura_moss'
  ];
BEGIN
  IF v_token = '' THEN
    RETURN true;
  END IF;

  IF NOT (v_token = ANY (v_catalog)) THEN
    RETURN false;
  END IF;

  IF p_kind IS NOT NULL AND v_token NOT LIKE (p_kind || '\_%') THEN
    RETURN false;
  END IF;

  -- FREE TIER: no user, no VIP, no ledger row required.
  IF v_token = ANY (v_free) THEN
    RETURN true;
  END IF;

  IF p_user IS NULL THEN
    RETURN false;
  END IF;

  SELECT p.is_vip INTO v_is_vip FROM public.profiles p WHERE p.id = p_user;
  IF coalesce(v_is_vip, false) THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.avatar_unlocks au
    WHERE au.user_id = p_user
      AND public.sp_normalize_cosmetic_token(au.avatar_id) = v_token
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_allocate_rake_credits(p_amount numeric, p_contributions jsonb, p_method text DEFAULT 'WEIGHTED_CONTRIBUTED'::text)
 RETURNS TABLE(user_id uuid, credit numeric, weight numeric)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH c AS (
    SELECT (k.key)::uuid AS uid,
           round((k.value)::numeric * 100)::bigint AS cc
      FROM jsonb_each(COALESCE(p_contributions, '{}'::jsonb)) k
     WHERE jsonb_typeof(k.value) = 'number'
       AND (k.value)::numeric > 0
       AND k.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ),
  t AS (
    SELECT COALESCE(SUM(cc), 0)::bigint AS total,
           round(GREATEST(COALESCE(p_amount, 0), 0) * 100)::bigint AS amt,
           COUNT(*)::bigint AS n
      FROM c
  ),
  weighted AS (
    SELECT c.uid, c.cc,
           (t.amt * c.cc) / t.total AS fl,
           (t.amt * c.cc) % t.total AS rem,
           t.amt, t.total
      FROM c CROSS JOIN t
     WHERE t.total > 0
  ),
  weighted_ranked AS (
    SELECT w.*,
           row_number() OVER (ORDER BY w.rem DESC, w.uid ASC) AS rn,
           SUM(w.fl) OVER () AS fl_sum
      FROM weighted w
  ),
  equal_ranked AS (
    SELECT c.uid, c.cc, t.amt, t.total, t.n,
           row_number() OVER (ORDER BY c.uid ASC) AS rn
      FROM c CROSS JOIN t
     WHERE t.n > 0
  )
  SELECT uid,
         ((fl + CASE WHEN rn <= (amt - fl_sum) THEN 1 ELSE 0 END)::numeric / 100),
         round(cc::numeric / total, 8)
    FROM weighted_ranked
   WHERE COALESCE(p_method, 'WEIGHTED_CONTRIBUTED') = 'WEIGHTED_CONTRIBUTED'
  UNION ALL
  SELECT uid,
         (((amt / n) + CASE WHEN rn <= (amt % n) THEN 1 ELSE 0 END)::numeric / 100),
         round(cc::numeric / total, 8)
    FROM equal_ranked
   WHERE COALESCE(p_method, 'WEIGHTED_CONTRIBUTED') = 'DEALT_EQUAL';
$function$;
CREATE OR REPLACE FUNCTION public.fn_award_vip_credit(p_user_id uuid, p_credit numeric, p_source_type text, p_source_id uuid, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ledger_id uuid;
  v_carry numeric(14,4);
  v_total numeric(14,4);
  v_pts bigint;
BEGIN
  -- SERVER ONLY. A browser calling this would be minting its own points.
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_award_vip_credit is a server-side path' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR COALESCE(p_credit, 0) <= 0 THEN
    RETURN 0;
  END IF;

  /* The carry row first, locked for this transaction: it serialises awards
     per user, and it is what the points depend on. Before phase 8 the leg
     was inserted with points = 0 and rewritten after this step. */
  INSERT INTO public.vip_points_carry (user_id, carry)
  VALUES (p_user_id, 0)
  ON CONFLICT (user_id) DO UPDATE SET carry = public.vip_points_carry.carry
  RETURNING carry INTO v_carry;

  v_total := v_carry + round(p_credit, 4);
  v_pts   := floor(v_total)::bigint;

  /* The leg, once, final. The unique (user, source_type, source_id) key is
     the idempotency: a second award for the same source writes nothing and
     changes nothing - the carry above was only locked, not moved. */
  INSERT INTO public.vip_points_ledger (user_id, points, reason, source_type, source_id, credit)
  VALUES (p_user_id, v_pts, p_reason, p_source_type, p_source_id, round(p_credit, 4))
  ON CONFLICT (user_id, source_type, source_id) DO NOTHING
  RETURNING id INTO v_ledger_id;
  IF v_ledger_id IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.vip_points_carry SET carry = v_total - v_pts, updated_at = now() WHERE user_id = p_user_id;

  IF v_pts > 0 THEN
    PERFORM set_config('app.vip_points_writer', 'fn_award_vip_credit', true);
    INSERT INTO public.vip_points (user_id, current_points, lifetime_points)
    VALUES (p_user_id, v_pts, v_pts)
    ON CONFLICT (user_id) DO UPDATE
      SET current_points = public.vip_points.current_points + v_pts,
          lifetime_points = public.vip_points.lifetime_points + v_pts,
          updated_at = now();
    PERFORM set_config('app.vip_points_writer', '', true);
  END IF;
  RETURN v_pts;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_current_epoch()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT id FROM public.ca_financial_epochs WHERE is_current LIMIT 1 $function$;
CREATE OR REPLACE FUNCTION public.enqueue_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb, p_occurred_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_event public.daily_challenge_event_outbox%ROWTYPE;
  v_receipt public.daily_challenge_progress_events%ROWTYPE;
  v_receipt_found boolean;
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  INSERT INTO public.daily_challenge_event_outbox (
    user_id,
    event_key,
    amounts,
    magnitudes,
    occurred_at
  ) VALUES (
    p_user_id,
    p_event_key,
    p_amounts,
    p_magnitudes,
    p_occurred_at
  )
  ON CONFLICT (user_id, event_key) DO NOTHING;

  SELECT * INTO STRICT v_event
  FROM public.daily_challenge_event_outbox
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;

  IF v_event.amounts IS DISTINCT FROM p_amounts
     OR v_event.magnitudes IS DISTINCT FROM p_magnitudes
     OR v_event.threshold_values IS DISTINCT FROM '{}'::jsonb
     OR v_event.occurred_at IS DISTINCT FROM p_occurred_at
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  SELECT * INTO v_receipt
  FROM public.daily_challenge_progress_events
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;
  v_receipt_found := FOUND;

  IF v_receipt_found
     AND (
       v_receipt.amounts IS DISTINCT FROM v_event.amounts
       OR v_receipt.magnitudes IS DISTINCT FROM v_event.magnitudes
       OR v_receipt.threshold_values IS DISTINCT FROM '{}'::jsonb
       OR v_receipt.occurred_at IS DISTINCT FROM v_event.occurred_at
     )
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  BEGIN
    PERFORM public.record_daily_challenge_event(
      v_event.user_id,
      v_event.event_key,
      v_event.amounts,
      v_event.magnitudes,
      v_event.occurred_at
    );
    DELETE FROM public.daily_challenge_event_outbox
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.daily_challenge_event_outbox
    SET attempts = attempts + 1,
        last_error = left(SQLERRM, 1000),
        next_attempt_at = now() + interval '1 minute'
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN false;
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_is_cert_account(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- DEFINER, like fn_ca_is_fixture_account. It reads auth.users, which `authenticated` cannot
  -- select from, so as INVOKER it answered one thing for service_role and another for everyone
  -- else - a predicate whose result depended on the caller rather than the account.
  --
  -- A HORSE IS A PLAYER (CLAUDE.md 10.5), so it is never certification equipment, whatever its
  -- address looks like. The fleet shares an email domain, which classified 468 of them as test
  -- equipment until 2026-09-08.
  SELECT p_user_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id AND COALESCE(p.is_horse, false))
    AND (
      EXISTS (SELECT 1 FROM public.ca_cert_accounts c WHERE c.user_id = p_user_id AND c.active)
      OR p_user_id::text LIKE '00000000-0000-0000-0000-%'
      OR EXISTS (SELECT 1 FROM auth.users u
                  WHERE u.id = p_user_id
                    AND (u.email LIKE '%@horses.smarter.poker'
                         OR u.email LIKE '%.invalid'))
    );
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_entry_scope_ok(p_user_id uuid, p_tournament_club uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_union boolean; v_club_union uuid;
BEGIN
  IF p_user_id IS NULL OR p_tournament_club IS NULL THEN
    RETURN false;
  END IF;
  -- The Diamond arena has no membership rows by design: every account with a
  -- profile is a member. A retired or missing profile is not.
  IF EXISTS (SELECT 1 FROM public.clubs c
              WHERE c.id = p_tournament_club AND c.asset = 'diamonds'
                AND c.is_platform IS TRUE AND c.union_id IS NULL) THEN
    RETURN EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id);
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_tournament_club) INTO v_is_union;
  IF v_is_union THEN
    -- Union-scoped tournament: member of any club in that union.
    RETURN EXISTS (
      SELECT 1 FROM public.club_members cm JOIN public.clubs c ON c.id = cm.club_id
       WHERE cm.user_id = p_user_id
         AND (c.union_id = p_tournament_club
              OR EXISTS (SELECT 1 FROM public.union_clubs uc
                          WHERE uc.club_id = c.id AND uc.union_id = p_tournament_club)));
  END IF;
  SELECT c.union_id INTO v_club_union FROM public.clubs c WHERE c.id = p_tournament_club;
  IF v_club_union IS NOT NULL THEN
    -- Club in a union: member of the club itself or any sibling club in the union.
    RETURN EXISTS (
      SELECT 1 FROM public.club_members cm JOIN public.clubs c ON c.id = cm.club_id
       WHERE cm.user_id = p_user_id
         AND (c.id = p_tournament_club
              OR c.union_id = v_club_union
              OR EXISTS (SELECT 1 FROM public.union_clubs uc
                          WHERE uc.club_id = c.id AND uc.union_id = v_club_union)));
  END IF;
  -- Standalone club: members only.
  RETURN EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.user_id = p_user_id AND cm.club_id = p_tournament_club);
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_noncirculating_chip_stores()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY['system_mint', 'system_burn', 'issuance_reserve', 'chip_retirement']::text[];
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_mint_supply(p_asset text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
    FROM public.ca_mint_ledger WHERE asset = p_asset;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_register_issuance_leg(p_ledger_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  l record; v_action text; v_holder_type text; v_holder uuid; v_label text;
  v_before numeric; v_after numeric; v_supply numeric; v_reason text; v_op text;
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
BEGIN
  SELECT * INTO l FROM public.chip_ledger WHERE id = p_ledger_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.ca_mint_ledger m WHERE m.chip_ledger_id = l.id) THEN
    RETURN false;
  END IF;
  IF l.category = 'correction' AND l.metadata->>'posted_via' = 'fn_ca_post_correction' THEN
    RETURN false;  -- a correction moves no balance (a_correction_is_not_a_mint)
  END IF;
  IF l.from_type = ANY (v_outside) AND NOT (l.to_type = ANY (v_outside)) THEN
    v_action := 'mint'; v_holder := l.to_entity_id;
    v_holder_type := CASE l.to_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSIF l.to_type = ANY (v_outside) AND NOT (l.from_type = ANY (v_outside)) THEN
    v_action := 'burn'; v_holder := l.from_entity_id;
    v_holder_type := CASE l.from_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSE
    RETURN false;  -- store to store, or circulating to circulating
  END IF;
  -- The autoledger stamps a union wallet's row with the union id; a union is
  -- also a row in clubs (is_union), so resolve by what the id actually is.
  IF v_holder_type = 'club' AND EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = v_holder AND COALESCE(c.is_union, false)) THEN
    v_holder_type := 'union';
  END IF;
  IF v_holder IS NULL THEN
    v_holder_type := 'circulation';
  END IF;
  IF v_holder_type = 'circulation' THEN
    v_holder := '00000000-0000-0000-0000-00000000c1c0';  -- the circulation sentinel (the house is ...d1a0)
  END IF;
  v_label := CASE v_holder_type
    WHEN 'club'   THEN (SELECT c.name FROM public.clubs c WHERE c.id = v_holder)
    WHEN 'union'  THEN COALESCE((SELECT u.name FROM public.unions u WHERE u.id = v_holder), (SELECT c.name FROM public.clubs c WHERE c.id = v_holder))
    WHEN 'player' THEN (SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text) FROM public.profiles p WHERE p.id = v_holder)
    ELSE 'circulation' END;
  -- A leg written by hand (a linked compensating entry) carries no balances;
  -- the register still wants a pair, so the pair is the amount itself.
  /* A door that wrote its own register row but did not link the leg
     (fn_ca_burn looks the leg up by a shape it does not always match):
     adopt that row rather than write a second one. Same action, holder,
     amount, asset, within five seconds of the leg, not yet linked. */
  UPDATE public.ca_mint_ledger m
     SET chip_ledger_id = l.id
   WHERE m.id = (SELECT m2.id FROM public.ca_mint_ledger m2
                  WHERE m2.chip_ledger_id IS NULL AND m2.asset = 'chips' AND m2.action = v_action
                    AND m2.amount = l.amount AND m2.holder_id = v_holder
                    AND m2.created_at BETWEEN l.created_at - interval '5 seconds' AND l.created_at + interval '5 seconds'
                  ORDER BY m2.created_at LIMIT 1);
  IF FOUND THEN RETURN false; END IF;
  v_before := COALESCE(CASE WHEN v_action = 'mint' THEN l.pre_to_balance ELSE l.pre_from_balance END, 0);
  v_after  := COALESCE(CASE WHEN v_action = 'mint' THEN l.post_to_balance ELSE l.post_from_balance END,
                       v_before + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END);
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
       + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  v_op := 'ledger:' || l.id::text;
  v_reason := left(COALESCE(NULLIF(btrim(l.description), ''), l.category) || ' (' || l.category
              || CASE WHEN l.idempotency_key IS NOT NULL THEN ', key ' || l.idempotency_key ELSE '' END
              || '; registered from the journal leg)', 500);
  IF length(btrim(v_reason)) < 10 THEN v_reason := v_reason || ' - registered from the journal'; END IF;
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason, performed_by, performed_by_label, db_role, chip_ledger_id, created_at)
  VALUES (v_op, v_action, 'chips', v_holder_type, v_holder, v_label, l.amount,
          v_before, v_after, v_supply, v_reason, l.performed_by, COALESCE(l.actor_service, l.db_role), l.db_role, l.id, l.created_at)
  ON CONFLICT (op_id) DO NOTHING;
  RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_mint_issued_24h(p_asset text, p_except_leg uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(sum(m.amount), 0)
    FROM public.ca_mint_ledger m
   WHERE m.asset = p_asset AND m.action = 'mint'
     AND m.origin <> 'baseline'
     AND m.created_at > now() - interval '24 hours'
     AND (p_except_leg IS NULL OR m.chip_ledger_id IS DISTINCT FROM p_except_leg);
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_club_rake_daily_apply(p_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer := 0;
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN RETURN 0; END IF;
  INSERT INTO public.ca_club_rake_daily AS d
         (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
  SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
    FROM public.fn_ca_club_rake_daily_compute(now(), now(), p_ids) c
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET hands = d.hands + EXCLUDED.hands,
         rake = d.rake + EXCLUDED.rake,
         bbj = d.bbj + EXCLUDED.bbj,
         pot = d.pot + EXCLUDED.pot,
         source_rows = d.source_rows + EXCLUDED.source_rows,
         updated_at = now();
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_club_rake_daily_rebuild_range(p_start date, p_end date, p_include_today boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_last date := CASE WHEN coalesce(p_include_today, false) THEN v_today ELSE v_today - 1 END;
  v_s date := LEAST(coalesce(p_start, v_today), coalesce(p_end, v_today));
  v_e date := LEAST(GREATEST(coalesce(p_start, v_today), coalesce(p_end, v_today)), v_last);
  d date;
  v_days integer := 0;
BEGIN
  IF v_s > v_e THEN RETURN 0; END IF;
  FOR d IN SELECT gs::date FROM generate_series(v_s, v_e, interval '1 day') gs LOOP
    -- One pass. A complete day has no writer to race, so the recount is
    -- exact; the caller checks the result against the ledger and says so.
    -- Retrying was measured on a live day and never closed the gap: see the
    -- header.
    PERFORM pg_advisory_xact_lock(hashtextextended('ca_club_rake_daily:' || d::text, 42));
    DELETE FROM public.ca_club_rake_daily r WHERE r.stat_date = d;
    INSERT INTO public.ca_club_rake_daily AS x
           (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
    SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
      FROM public.fn_ca_club_rake_daily_compute(
             (d::timestamp AT TIME ZONE 'UTC'), ((d + 1)::timestamp AT TIME ZONE 'UTC'), NULL) c
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET hands = x.hands + EXCLUDED.hands,
           rake = x.rake + EXCLUDED.rake,
           bbj = x.bbj + EXCLUDED.bbj,
           pot = x.pot + EXCLUDED.pot,
           source_rows = x.source_rows + EXCLUDED.source_rows,
           updated_at = now();
    v_days := v_days + 1;
  END LOOP;
  RETURN v_days;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_settlement_frozen(p_club_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT c.settlement_locked
       AND (c.settlement_lock_until IS NULL OR c.settlement_lock_until > now())
       FROM clubs c WHERE c.id = p_club_id),
    false);
$function$;
CREATE OR REPLACE FUNCTION public.fn_socialize_horse(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  p record; ca record; v_h bigint; v_loc text; v_tz text; v_spec text; v_stakes text; v_alias text; v_voice text; v_arch text; v_cad int; v_bday date; v_touched boolean := false;
  v_locs text[] := ARRAY['Atlantic City, NJ','Austin, TX','Barcelona, ES','Berlin, DE','Brooklyn, NY','Chicago, IL','Dallas, TX','Denver, CO','Dublin, IE','Las Vegas, NV','Lisbon, PT','London, UK','Los Angeles, CA','Manchester, UK','Manila, PH','Melbourne, AU','Miami, FL','Phoenix, AZ','Seattle, WA','Toronto, CA'];
  v_tzs text[] := ARRAY['America/New_York','America/Chicago','Europe/Madrid','Europe/Berlin','America/New_York','America/Chicago','America/Chicago','America/Denver','Europe/Dublin','America/Los_Angeles','Europe/Lisbon','Europe/London','America/Los_Angeles','Europe/London','Asia/Manila','Australia/Melbourne','America/New_York','America/Phoenix','America/Los_Angeles','America/Toronto'];
  v_specs text[] := ARRAY['bounty tournaments','cash games','heads-up','live cash','mixed games','PLO','satellites','short deck','spins','tournaments'];
  v_stk text[] := ARRAY['1/2','1/3','10/25','2/3','2/5','25/50','5/10'];
  v_voices text[] := ARRAY['analytical','blunt','hype','dry','veteran','casual','skeptical','excitable','terse','conversational','community','technical','storyteller','grinder','coach'];
  v_archs text[] := ARRAY['blunt','analytical','hype','dry','veteran','casual','skeptical','excitable','terse','conversational'];
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = p_id;
  IF NOT FOUND OR NOT COALESCE(p.is_horse, false) THEN RETURN false; END IF;
  v_h := abs(hashtext(p_id::text));
  v_loc := v_locs[1 + (v_h % 20)]; v_tz := v_tzs[1 + (v_h % 20)]; v_spec := v_specs[1 + ((v_h / 7) % 10)]; v_stakes := v_stk[1 + ((v_h / 11) % 7)];
  v_voice := v_voices[1 + ((v_h / 13) % array_length(v_voices, 1))]; v_arch := v_archs[1 + ((v_h / 17) % array_length(v_archs, 1))];
  v_cad := public.fn_fleet_cadence(p_id);
  v_bday := date '1972-01-01' + ((v_h / 23) % (365 * 30))::int;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  IF NOT FOUND THEN
    v_alias := public.fn_mint_social_alias(p_id::text);
    INSERT INTO public.content_authors (name, alias, location, timezone, specialty, stakes, bio, avatar_seed, avatar_url, profile_id, is_active, voice, birthday, personality)
    VALUES (COALESCE(NULLIF(p.display_name, ''), NULLIF(p.full_name, ''), p.username), v_alias, v_loc, v_tz, v_spec, v_stakes, v_spec || ' regular out of ' || v_loc || '. Mostly ' || v_stakes || '.', lower(v_alias) || '_' || substr(md5(p_id::text), 1, 8), p.avatar_url, p_id, true, v_voice, v_bday, jsonb_build_object('archetype', v_arch, 'cadence_per_week', v_cad, 'seeded_by', 'fn_socialize_horse', 'seeded_at', now()));
    v_touched := true;
    SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  END IF;
  UPDATE public.content_authors SET is_active = true,
      location = COALESCE(NULLIF(location, ''), v_loc), timezone = COALESCE(NULLIF(timezone, ''), v_tz), specialty = COALESCE(NULLIF(specialty, ''), v_spec), stakes = COALESCE(NULLIF(stakes, ''), v_stakes),
      bio = COALESCE(NULLIF(bio, ''), v_spec || ' regular out of ' || COALESCE(NULLIF(location,''), v_loc) || '. Mostly ' || COALESCE(NULLIF(stakes,''), v_stakes) || '.'),
      voice = COALESCE(NULLIF(voice, ''), v_voice), birthday = COALESCE(birthday, v_bday), avatar_url = COALESCE(avatar_url, p.avatar_url),
      personality = COALESCE(personality, '{}'::jsonb)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'archetype' THEN '{}'::jsonb ELSE jsonb_build_object('archetype', v_arch) END
                    || jsonb_build_object('cadence_per_week', v_cad)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'seeded_by' THEN '{}'::jsonb ELSE jsonb_build_object('seeded_by', 'fn_socialize_horse', 'seeded_at', now()) END
  WHERE profile_id = p_id
    AND (NOT is_active OR COALESCE(location,'') = '' OR COALESCE(timezone,'') = '' OR COALESCE(specialty,'') = '' OR COALESCE(stakes,'') = '' OR COALESCE(bio,'') = '' OR COALESCE(voice,'') = '' OR birthday IS NULL OR avatar_url IS NULL OR personality IS NULL OR NOT (personality ? 'archetype') OR (personality->>'cadence_per_week') IS DISTINCT FROM v_cad::text);
  IF FOUND THEN v_touched := true; END IF;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  UPDATE public.profiles SET bio = COALESCE(NULLIF(bio, ''), ca.bio), city = COALESCE(NULLIF(city, ''), split_part(ca.location, ',', 1)), favorite_game = COALESCE(NULLIF(favorite_game, ''), ca.specialty), birth_year = COALESCE(birth_year, EXTRACT(YEAR FROM ca.birthday)::int), social_profile_completed = true, updated_at = now()
  WHERE id = p_id AND (COALESCE(bio,'') = '' OR COALESCE(city,'') = '' OR COALESCE(favorite_game,'') = '' OR birth_year IS NULL OR NOT COALESCE(social_profile_completed, false));
  IF FOUND THEN v_touched := true; END IF;
  RETURN v_touched;
END; $function$;
CREATE OR REPLACE FUNCTION public.enqueue_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb, p_values jsonb, p_occurred_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_event public.daily_challenge_event_outbox%ROWTYPE;
  v_receipt public.daily_challenge_progress_events%ROWTYPE;
  v_receipt_found boolean;
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  INSERT INTO public.daily_challenge_event_outbox (
    user_id,
    event_key,
    amounts,
    magnitudes,
    threshold_values,
    occurred_at
  ) VALUES (
    p_user_id,
    p_event_key,
    p_amounts,
    p_magnitudes,
    p_values,
    p_occurred_at
  )
  ON CONFLICT (user_id, event_key) DO NOTHING;

  SELECT * INTO STRICT v_event
  FROM public.daily_challenge_event_outbox
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;

  IF v_event.amounts IS DISTINCT FROM p_amounts
     OR v_event.magnitudes IS DISTINCT FROM p_magnitudes
     OR v_event.threshold_values IS DISTINCT FROM p_values
     OR v_event.occurred_at IS DISTINCT FROM p_occurred_at
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  SELECT * INTO v_receipt
  FROM public.daily_challenge_progress_events
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;
  v_receipt_found := FOUND;

  IF v_receipt_found
     AND (
       v_receipt.amounts IS DISTINCT FROM v_event.amounts
       OR v_receipt.magnitudes IS DISTINCT FROM v_event.magnitudes
       OR v_receipt.threshold_values IS DISTINCT FROM v_event.threshold_values
       OR v_receipt.occurred_at IS DISTINCT FROM v_event.occurred_at
     )
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  BEGIN
    PERFORM public.record_daily_challenge_event(
      v_event.user_id,
      v_event.event_key,
      v_event.amounts,
      v_event.magnitudes,
      v_event.threshold_values,
      v_event.occurred_at
    );
    DELETE FROM public.daily_challenge_event_outbox
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.daily_challenge_event_outbox
    SET attempts = attempts + 1,
        last_error = left(SQLERRM, 1000),
        next_attempt_at = now() + interval '1 minute'
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN false;
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text)
 RETURNS numeric
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  -- A parked refund remains in this bank but is already owed, not spendable.
  -- Financial callers must hold bbj_pools FOR UPDATE before reading it.
  SELECT COALESCE(sum(u.amount),0) FROM public.bbj_unclaimed_shares u
  JOIN public.bbj_payouts p ON p.id=u.payout_id
  WHERE u.pool_id=p_pool_id AND u.paid_at IS NULL
    AND (CASE WHEN p.kind='mini' THEN 'backup' ELSE 'main' END)=p_bank;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_day_manifest(p_day date DEFAULT (CURRENT_DATE - 1), p_restate_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE v_count bigint; v_net numeric; v_first bigint; v_last bigint; v_sha text; v_prior text; v_prior_rows bigint;
BEGIN
  /* One index range over idx_chip_ledger_created_at: the cost is this day's
     legs, not the journal's. A day is a UTC day (SET timezone above). */
  SELECT count(*), COALESCE(sum(amount), 0), min(chain_seq), max(chain_seq),
         encode(extensions.digest(
           COALESCE(string_agg(
             id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
             '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
             extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
             E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
    INTO v_count, v_net, v_first, v_last, v_sha
    FROM public.chip_ledger
   WHERE created_at >= p_day AND created_at < p_day + 1;

  SELECT sha256, row_count INTO v_prior, v_prior_rows
    FROM public.ca_ledger_day_manifests WHERE day = p_day;

  IF v_prior IS NULL THEN
    IF v_count = 0 THEN
      /* Nothing to attest and nothing attested: not a manifest, not an error. */
      RETURN jsonb_build_object('day', p_day, 'rows', 0, 'attested', false, 'tampered', false);
    END IF;
    INSERT INTO public.ca_ledger_day_manifests
      (day, row_count, first_seq, last_seq, net_amount, sha256, last_checked_at)
    VALUES (p_day, v_count, v_first, v_last, v_net, v_sha, now())
    ON CONFLICT (day) DO NOTHING;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  IF v_prior = v_sha THEN
    /* Read and agreed: that is a verification, so say when it happened. */
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = p_day;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  /* The stored attestation and the journal disagree. */
  IF p_restate_reason IS NULL THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest', 'unauthorized_adjustment', 'critical',
      'manifest-mismatch:' || p_day::text,
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the recomputed ledger manifest for ' || p_day || ' no longer matches the stored one - historical rows changed',
      false, jsonb_build_object('day', p_day, 'stored', v_prior, 'recomputed', v_sha,
                                'stored_rows', v_prior_rows, 'actual_rows', v_count));
    RETURN jsonb_build_object('day', p_day, 'tampered', true, 'stored', v_prior, 'recomputed', v_sha,
                              'stored_rows', v_prior_rows, 'actual_rows', v_count);
  END IF;

  IF v_count = 0 THEN
    /* A day that was attested cannot become a day that never happened. The
       statement that would empty it is refused whole. */
    RAISE EXCEPTION
      'refusing to restate % to zero rows (it attested % rows): an attested day cannot be emptied. Reason offered: %',
      p_day, v_prior_rows, p_restate_reason
      USING ERRCODE = 'P0403';
  END IF;

  /* Open the guard for exactly this update, in this transaction only. The
     guard writes the restatement row itself, old value kept. */
  PERFORM set_config('app.manifest_restatement', p_restate_reason, true);
  UPDATE public.ca_ledger_day_manifests
     SET row_count = v_count, first_seq = v_first, last_seq = v_last,
         net_amount = v_net, sha256 = v_sha, last_checked_at = now()
   WHERE day = p_day;
  PERFORM set_config('app.manifest_restatement', '', true);

  RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
    'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false,
    'restated', true, 'old_sha256', v_prior, 'old_rows', v_prior_rows, 'reason', p_restate_reason);
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_is_fixture_account(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_user_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id AND COALESCE(p.is_horse, false))
    AND (
      p_user_id::text LIKE '00000000-0000-0000-0000-%'
      OR EXISTS (SELECT 1 FROM public.ca_cert_accounts c WHERE c.user_id = p_user_id AND c.active)
      OR EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user_id AND u.email LIKE '%.invalid')
    );
$function$;
CREATE OR REPLACE FUNCTION public.fn_bounty_obligation_has_complete_marker(p_obligation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- DIAMOND PHASE 9: the expected split is taken at the event's unit
  -- (fn_ca_tournament_unit_cents: a cent for a chip event, so every
  -- expression below is what it was; a whole Diamond for a Diamond event).
  -- A mystery chest splits into unit-floored equal shares with the remainder
  -- to the first claimant by user id; a regular or PKO head splits into
  -- unit-floored equal shares with the remainder to the last claimant, and a
  -- PKO cash half is the unit-floored half of the share.
  SELECT COALESCE((
    SELECT CASE WHEN o.mode='mystery_chest' THEN
      EXISTS (
        SELECT 1 FROM public.tournament_bounty_awards a
         WHERE a.bounty_obligation_id=o.id AND a.status='completed'
           AND (SELECT COALESCE(sum(r.amount_cents),0)
                  FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.paid_at IS NOT NULL)=a.amount_cents
           AND NOT EXISTS (
             SELECT 1
               FROM (
                 SELECT claimant_id,ordinal,claimant_count,
                        CASE WHEN u.unit = 1 THEN
                          floor(a.amount_cents / claimant_count)
                            + CASE WHEN ordinal <= mod(a.amount_cents,claimant_count)
                                   THEN 1 ELSE 0 END
                        ELSE
                          public.fn_ca_unit_floor_cents(floor(a.amount_cents / claimant_count)::bigint, u.unit)
                            + CASE WHEN ordinal = 1
                                   THEN a.amount_cents
                                        - public.fn_ca_unit_floor_cents(floor(a.amount_cents / claimant_count)::bigint, u.unit) * claimant_count
                                   ELSE 0 END
                        END AS expected_cents
                   FROM (
                     SELECT (c->>'user_id')::uuid AS claimant_id,
                            row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                            count(*) OVER () AS claimant_count
                       FROM jsonb_array_elements(o.claimants) c
                   ) ordered_claimants
                   CROSS JOIN (SELECT public.fn_ca_tournament_unit_cents(o.tournament_id) AS unit) u
               ) expected
              WHERE NOT EXISTS (
                SELECT 1 FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.user_id=expected.claimant_id
                   AND r.amount_cents=expected.expected_cents
                   AND r.paid_at IS NOT NULL
              )
           )
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_award_recipients r
              WHERE r.award_id=a.id
                AND (r.paid_at IS NULL OR NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(o.claimants) c
                   WHERE (c->>'user_id')::uuid=r.user_id
                ))
           )
      )
    ELSE
      NOT EXISTS (
        SELECT 1
          FROM (
            SELECT claimant_id, ordinal, claimant_count, u.unit,
                   CASE WHEN ordinal < claimant_count
                        THEN public.fn_ca_unit_floor_cents(floor(head_cents / claimant_count)::bigint, u.unit)
                        ELSE head_cents
                             - public.fn_ca_unit_floor_cents(floor(head_cents / claimant_count)::bigint, u.unit) * (claimant_count - 1)
                   END AS expected_cents
              FROM (
                SELECT (c->>'user_id')::uuid AS claimant_id,
                       row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                       count(*) OVER () AS claimant_count,
                       round(o.head_amount * 100)::bigint AS head_cents
                  FROM jsonb_array_elements(o.claimants) c
              ) ordered_claimants
              CROSS JOIN (SELECT public.fn_ca_tournament_unit_cents(o.tournament_id) AS unit) u
          ) expected
         WHERE expected.expected_cents > 0
           AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounties b
            WHERE b.bounty_obligation_id=o.id
              AND b.collector_player_id=expected.claimant_id
              AND round(b.bounty_amount * 100)::bigint=expected.expected_cents
              AND round(COALESCE(b.added_to_collector_bounty,0) * 100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN expected.expected_cents
                              - public.fn_ca_unit_floor_cents(floor(expected.expected_cents/2.0)::bigint, expected.unit)
                         ELSE 0 END
              AND round((b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))*100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN public.fn_ca_unit_floor_cents(floor(expected.expected_cents/2.0)::bigint, expected.unit)
                         ELSE expected.expected_cents END
         )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
           AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(o.claimants) c
              WHERE (c->>'user_id')::uuid=b.collector_player_id
           )
      )
      AND round(COALESCE((
        SELECT sum(b.bounty_amount) FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
      ),0),2)=round(o.head_amount,2)
    END
      FROM public.tournament_bounty_obligations o
     WHERE o.id=p_obligation_id
  ),false);
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_normalize_alert_text(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  /* Order matters. UUIDs first (digits and hyphens), then timestamps, then
     decimals, then bare integers, then whitespace. What is left is the WORDS,
     which is what distinguishes one cause from another. */
  SELECT regexp_replace(
           regexp_replace(
             regexp_replace(
               regexp_replace(
                 regexp_replace(
                   lower(coalesce(p_text, '')),
                   '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}',
                   '<id>', 'g'),
                 '\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}:\d{2}(\.\d+)?([+-]\d{2}:?\d{2}|z)?',
                 '<ts>', 'g'),
               '\d+\.\d+', '<amt>', 'g'),
             '\d+', '<n>', 'g'),
           '\s+', ' ', 'g')
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_id_from_credit_key(p_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id_text text;
  v_id uuid;
BEGIN
  IF p_key LIKE 'tourney:%' OR p_key LIKE 'mb-residual:%' THEN
    v_id_text := split_part(p_key,':',2);
    IF v_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN v_id_text::uuid;
    END IF;
  ELSIF p_key LIKE 'mb:%' THEN
    v_id_text := split_part(p_key,':',2);
    IF v_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT a.tournament_id INTO v_id
        FROM public.tournament_bounty_awards a WHERE a.id = v_id_text::uuid;
      RETURN v_id;
    END IF;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_chip_supply(p_tournament_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(r.entrants,0)*COALESCE(t.starting_chips,0)
       + COALESCE(r.rebuys,0)
         *COALESCE(NULLIF(t.rebuy_chips,0),t.starting_chips,0)
       + COALESCE(r.addons,0)
         *COALESCE(NULLIF(t.addon_chips,0),t.starting_chips,0)
       + COALESCE(a.chips,0)
    FROM public.tournaments t
    LEFT JOIN LATERAL (
      SELECT count(*) AS entrants,
             COALESCE(sum(GREATEST(COALESCE(tp.rebuys,0),0)),0) AS rebuys,
             count(*) FILTER (WHERE tp.add_on) AS addons
        FROM public.tournament_players tp
       WHERE tp.tournament_id=t.id
    ) r ON true
    LEFT JOIN public.tournament_felt_supply_acknowledgements a
           ON a.tournament_id = t.id
   WHERE t.id=p_tournament_id;
$function$;
CREATE OR REPLACE FUNCTION public.fn_invoice_accounting_ledger_transfer(p_ledger_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE leg public.chip_ledger%ROWTYPE; inv_id uuid; issuer_kind text; issuer_id uuid; payee_kind text; payee_id uuid; kind text;
BEGIN
 SELECT * INTO leg FROM public.chip_ledger WHERE id=p_ledger_id;
 IF NOT FOUND OR leg.status IS DISTINCT FROM 'posted' OR leg.amount IS NULL OR leg.amount<=0
    OR leg.amount::text IN('NaN','Infinity','-Infinity') OR leg.amount<>round(leg.amount,2)
 THEN RAISE EXCEPTION 'invalid_accounting_transfer' USING ERRCODE='23514'; END IF;
 IF leg.from_type IN('union_wallet','union_bank') THEN issuer_kind:='union';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type='club_treasury' THEN issuer_kind:='club';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type IN('player_wallet','agent_wallet') THEN issuer_id:=leg.from_entity_id;
   issuer_kind:=CASE WHEN leg.from_type='agent_wallet' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=issuer_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSIF leg.from_type='settlement_suspense' AND leg.category='rakeback' AND leg.club_id IS NOT NULL THEN
   -- Club-issued receipt for the existing clearing-account leg; preserve its actual source in breakdown.
   issuer_kind:='club';issuer_id:=leg.club_id;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_source' USING ERRCODE='23514'; END IF;
 -- Game payout journals retain the physical union_wallets.id store identity.
 -- Accounting parties use unions.id. Resolve only a matching, declared host;
 -- never rewrite the original journal or infer a different union.
 IF leg.category IN('wheel_prize','plinko_prize','crash_prize','crossing_prize','mines_prize')
    AND issuer_kind='union' AND leg.union_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.id=issuer_id AND w.union_id=leg.union_id)
 THEN issuer_id:=leg.union_id; END IF;
 IF leg.to_type IN('union_wallet','union_bank') THEN payee_kind:='union';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type='club_treasury' THEN payee_kind:='club';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type IN('player_wallet','agent_wallet') THEN
   payee_id:=leg.to_entity_id;
   payee_kind:=CASE WHEN leg.category='commission' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_recipient' USING ERRCODE='23514'; END IF;
 kind:=CASE WHEN issuer_kind='union' AND payee_kind='club' THEN 'union_to_club'
            WHEN issuer_kind='club' AND payee_kind='agent' THEN 'club_to_agent'
            WHEN issuer_kind='agent' AND payee_kind='agent' THEN 'agent_to_subagent'
            WHEN issuer_kind='agent' AND payee_kind='player' THEN 'agent_to_player' ELSE 'transaction_receipt' END;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
 SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
 IF inv_id IS NULL THEN
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,notes,source_ledger_id)
   VALUES(COALESCE(leg.club_id,leg.union_id),kind,issuer_kind,issuer_id::text,payee_kind,payee_id::text,leg.amount,leg.amount,0,
    COALESCE(leg.metadata,'{}'::jsonb)||jsonb_build_object('ledger_id',leg.id,'category',leg.category,'ledger_from_type',leg.from_type,
      'ledger_from_entity_id',leg.from_entity_id,'ledger_to_type',leg.to_type,'ledger_to_entity_id',leg.to_entity_id,
      'payee_role_at_transfer',CASE WHEN payee_kind='player' THEN 'player' ELSE (SELECT a.role FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id ORDER BY a.id LIMIT 1) END),
    'paid',true,leg.created_at,'Receipt For A Posted Accounting Transfer. This Does Not Certify The Entire Weekly Close.',leg.id)
   RETURNING id INTO inv_id;
 END IF;
 PERFORM public.fn_deliver_accounting_invoice(inv_id);
 RETURN inv_id;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_club_level_for_members(p_members integer)
 RETURNS smallint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT MAX(level) FROM public.club_level_thresholds
      WHERE min_members <= GREATEST(COALESCE(p_members, 0), 0)),
    1::smallint);
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_role_rank(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT CASE p_role
    WHEN 'owner'       THEN 100
    WHEN 'co_owner'    THEN 90
    WHEN 'admin'       THEN 80
    WHEN 'super_agent' THEN 60
    WHEN 'agent'       THEN 40
    WHEN 'sub_agent'   THEN 20
    WHEN 'player'      THEN 0
    ELSE -1
  END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_grantable_roles(p_club_id uuid, p_actor_user_id uuid, p_target_user_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_role  text;
  v_target_role text;
  v_platform_admin boolean := false;
BEGIN
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL THEN RETURN '{}'; END IF;

  -- Nobody edits their own title. An owner demoting themselves would leave a
  -- club with no owner; anyone else would simply be promoting themselves.
  IF p_actor_user_id = p_target_user_id THEN RETURN '{}'; END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_actor_user_id
     AND status IN ('active','approved');

  SELECT role INTO v_target_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_target_user_id
     AND status IN ('active','approved');

  IF v_target_role IS NULL THEN RETURN '{}'; END IF;

  SELECT COALESCE(is_admin, false) INTO v_platform_admin
    FROM profiles WHERE id = p_actor_user_id;

  IF v_actor_role IS NULL AND NOT v_platform_admin THEN RETURN '{}'; END IF;

  -- The club owner is not demotable through this path. Handing over a club is
  -- a deliberate act of its own, not a dropdown on the members list.
  IF v_target_role = 'owner' THEN RETURN '{}'; END IF;

  IF v_platform_admin OR v_actor_role = 'owner' THEN
    RETURN ARRAY['co_owner','admin','super_agent','agent','sub_agent','player'];
  END IF;

  IF v_actor_role IN ('co_owner','admin') THEN
    -- "as high as admin". A co-owner outranks an admin but may not appoint or
    -- remove another co-owner; only the owner does that.
    IF fn_club_role_rank(v_target_role) >= fn_club_role_rank(v_actor_role) THEN
      RETURN '{}';
    END IF;
    RETURN ARRAY['admin','super_agent','agent','sub_agent','player'];
  END IF;

  -- A super agent manages the whole ladder beneath it, inside its own
  -- downline: agent, sub agent, player -- in either direction. It may not
  -- mint another super agent; that is owner / co-owner / admin work.
  IF v_actor_role = 'super_agent' THEN
    IF v_target_role IN ('player','agent','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['agent','sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- An agent may raise a player of theirs to sub agent, and put them back.
  IF v_actor_role = 'agent' THEN
    IF v_target_role IN ('player','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- sub agents and players promote nobody
  RETURN '{}';
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_tournament_primary_table(p_tournament_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY (
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id = tb.id AND s.left_at IS NULL
     ) DESC,
     tb.created_at ASC
   LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.sp_normalize_cosmetic_token(p_raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT regexp_replace(lower(btrim(coalesce(p_raw, ''))), '[[:space:]-]+', '_', 'g');
$function$;
CREATE OR REPLACE FUNCTION public.ca_refresh_reporting_rollups_base(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start date := LEAST(p_start, p_end);
  v_end date := GREATEST(p_start, p_end);
  v_from timestamptz;
  v_to timestamptz;
  v_players bigint;
  v_tournaments bigint;
  v_participants bigint;
BEGIN
  IF v_start IS NULL OR v_end IS NULL OR v_end - v_start > 400 THEN
    RAISE EXCEPTION 'reporting refresh requires a 0-400 day range';
  END IF;
  PERFORM pg_advisory_xact_lock(918273645);
  v_from := v_start::timestamp AT TIME ZONE 'UTC';
  v_to := (v_end + 1)::timestamp AT TIME ZONE 'UTC';

  DELETE FROM public.ca_club_player_daily WHERE stat_date BETWEEN v_start AND v_end;
  DELETE FROM public.ca_club_tournament_daily WHERE stat_date BETWEEN v_start AND v_end;
  DELETE FROM public.ca_club_tournament_player_daily WHERE stat_date BETWEEN v_start AND v_end;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id, cm.user_id)
           uc.union_id, cm.user_id, cm.club_id
      FROM public.club_members cm
      JOIN public.union_clubs uc ON uc.club_id = cm.club_id
     ORDER BY uc.union_id, cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id, cm.club_id
      FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id, club_id FROM home
    UNION
    SELECT user_id, club_id FROM standalone
  ), mapped AS MATERIALIZED (
    -- 2026-09-04: cash rows are the ones with a table (buy-in, cash-out,
    -- add-on, rebuy, refund); tournament rows have a tournament and no table
    -- (buy-in, add-on, rebuy, refund, prize, bounty, prize reversal). The sign
    -- is the row's type. This read buy-in/cash-out and buy-in/prize/bounty.
    SELECT 'cash'::text AS kind,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           h.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id AS tournament_id
      FROM public.wallet_transactions wt
      JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NOT NULL
       AND tb.tournament_id IS NULL
      JOIN home h ON h.union_id=tb.union_id AND h.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
    UNION ALL
    -- standalone tables, which this rollup never read.
    SELECT 'cash',wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
           tb.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id
      FROM public.wallet_transactions wt
      JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NULL
       AND tb.tournament_id IS NULL AND tb.club_id IS NOT NULL
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
    UNION ALL
    SELECT 'tournament',wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
           a.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id
      FROM public.wallet_transactions wt
      JOIN affiliations a ON a.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
       AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL
  )
  INSERT INTO public.ca_club_player_daily
    (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
  SELECT m.club_id,m.user_id,m.stat_date,
         SUM(CASE WHEN m.kind='cash'
                  THEN CASE WHEN m.type='credit' THEN m.amount
                            WHEN m.type='debit' THEN -m.amount ELSE 0 END ELSE 0 END),
         SUM(CASE WHEN m.kind='tournament'
                  THEN CASE WHEN m.type='credit' THEN m.amount
                            WHEN m.type='debit' THEN -m.amount ELSE 0 END ELSE 0 END),now()
    FROM mapped m GROUP BY 1,2,3;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id,cm.user_id)
           uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id,cm.club_id FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id,club_id FROM home UNION SELECT user_id,club_id FROM standalone
  ), wallet_mapped AS MATERIALIZED (
    SELECT a.club_id,wt.related_entity_id AS tournament_id,wt.user_id,
           (wt.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           CASE WHEN wt.type='credit' THEN wt.amount
                WHEN wt.type='debit' THEN -wt.amount ELSE 0 END AS winnings
      FROM public.wallet_transactions wt JOIN affiliations a ON a.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
       AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL
  ), entrant_totals AS MATERIALIZED (
    SELECT tp.tournament_id,count(*)::numeric AS total_players
      FROM public.tournament_players tp GROUP BY tp.tournament_id
  ), entrant_clubs AS MATERIALIZED (
    SELECT tp.tournament_id,a.club_id,count(*)::numeric AS club_players
      FROM public.tournament_players tp JOIN affiliations a ON a.user_id=tp.user_id
     GROUP BY tp.tournament_id,a.club_id
  ), rake_mapped AS MATERIALIZED (
    SELECT r.tournament_id,(r.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           CASE WHEN r.metadata ? 'user_id' THEN a.club_id ELSE ec.club_id END AS club_id,
           CASE WHEN r.metadata ? 'user_id' THEN r.rake_amount
                ELSE r.rake_amount*ec.club_players/NULLIF(et.total_players,0) END AS fee
      FROM public.rake_records r
      LEFT JOIN affiliations a ON r.metadata ? 'user_id'
       AND a.user_id::text=r.metadata->>'user_id'
      LEFT JOIN entrant_clubs ec ON NOT (r.metadata ? 'user_id')
       AND ec.tournament_id=r.tournament_id
      LEFT JOIN entrant_totals et ON et.tournament_id=r.tournament_id
     WHERE r.created_at>=v_from AND r.created_at<v_to AND r.is_tournament
       AND r.tournament_id IS NOT NULL AND r.rake_amount<>0
  ), combined AS (
    SELECT wm.club_id,wm.tournament_id,wm.stat_date,0::numeric AS fee,
           sum(wm.winnings) AS winnings FROM wallet_mapped wm GROUP BY 1,2,3
    UNION ALL
    SELECT rm.club_id,rm.tournament_id,rm.stat_date,sum(rm.fee),0::numeric
      FROM rake_mapped rm WHERE rm.club_id IS NOT NULL GROUP BY 1,2,3
  )
  INSERT INTO public.ca_club_tournament_daily
    (club_id,tournament_id,stat_date,fee,winnings,updated_at)
  SELECT club_id,tournament_id,stat_date,sum(fee),sum(winnings),now()
    FROM combined GROUP BY 1,2,3;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id,cm.user_id) uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id,cm.club_id FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id,club_id FROM home UNION SELECT user_id,club_id FROM standalone
  )
  INSERT INTO public.ca_club_tournament_player_daily
    (club_id,tournament_id,user_id,stat_date,updated_at)
  SELECT DISTINCT a.club_id,wt.related_entity_id,wt.user_id,
         (wt.created_at AT TIME ZONE 'UTC')::date,now()
    FROM public.wallet_transactions wt JOIN affiliations a ON a.user_id=wt.user_id
   WHERE wt.created_at>=v_from AND wt.created_at<v_to
     AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
     AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL;

  SELECT count(*) INTO v_players FROM public.ca_club_player_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  SELECT count(*) INTO v_tournaments FROM public.ca_club_tournament_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  SELECT count(*) INTO v_participants FROM public.ca_club_tournament_player_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  RETURN jsonb_build_object('start',v_start,'end',v_end,'player_facts',v_players,
    'tournament_facts',v_tournaments,'participant_facts',v_participants,
    'refreshed_at',now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.ca_refresh_reporting_cash_rollup(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start date:=LEAST(p_start,p_end); v_end date:=GREATEST(p_start,p_end);
  v_from timestamptz; v_to timestamptz; v_rows bigint;
BEGIN
  IF v_start IS NULL OR v_end IS NULL OR v_end-v_start>400 THEN
    RAISE EXCEPTION 'cash reporting refresh requires a 0-400 day range'; END IF;
  PERFORM pg_advisory_xact_lock(918273645);
  v_from:=v_start::timestamp AT TIME ZONE 'UTC';
  v_to:=(v_end+1)::timestamp AT TIME ZONE 'UTC';
  UPDATE public.ca_club_player_daily SET cash_net=0,updated_at=now()
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON(uc.union_id,cm.user_id) uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), cash AS (
    SELECT x.club_id,x.user_id,x.stat_date,SUM(x.cash_net) AS cash_net FROM (
      SELECT h.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date stat_date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END) cash_net
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NOT NULL
         AND tb.tournament_id IS NULL
        JOIN home h ON h.union_id=tb.union_id AND h.user_id=wt.user_id
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
      UNION ALL
      -- 2026-09-04: standalone tables, which this rollup never read.
      SELECT tb.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END)
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NULL
         AND tb.tournament_id IS NULL AND tb.club_id IS NOT NULL
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
    ) x GROUP BY 1,2,3
  )
  INSERT INTO public.ca_club_player_daily AS d
    (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
  SELECT club_id,user_id,stat_date,cash_net,0,now() FROM cash
  ON CONFLICT(club_id,user_id,stat_date) DO UPDATE
   SET cash_net=EXCLUDED.cash_net,updated_at=now();
  SELECT count(*) INTO v_rows FROM public.ca_club_player_daily
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  RETURN jsonb_build_object('start',v_start,'end',v_end,'cash_facts',v_rows,'refreshed_at',now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inc  public.ca_drift_incidents;
  rec  uuid;
  n    int := 0;
  club_name  text;
  union_name text;
  body text;
  age_min int;
  v_finding text;
  v_state   text;
  v_kind    text;
  v_fresh   boolean;
  v_withheld text := NULL;
  v_findings numeric;
  /* A LIVENESS FINDING CARRIES NO CHIP AMOUNT AND STILL MATTERS (2026-09-12).
     These detectors answer "is the platform dealing", not "do the chips add
     up", so their discrepancy is always 0.00 and the money gate below would
     mute every one of them. On 2026-09-12 the engine dealt zero tournament
     hands for five hours and every detector that could have said so would have
     been filed and muted here. Measured before changing it: 1,041 pushes were
     withheld on that gate in seven days and exactly 10 were liveness findings,
     so relaxing it generally would have sent a thousand pages a week. Named
     explicitly so a future detector has to ask to be on this list, and so the
     rule that decides who gets woken is readable in one glance. */
  v_liveness CONSTANT text[] := ARRAY[
    'fn_ca_conservation_sweep:fn_ca_orphaned_running_tournaments',
    'fn_ca_conservation_sweep:fn_ca_tables_that_cannot_deal',
    'fn_ca_conservation_sweep:fn_ca_knockout_door_stalled',
    'fn_ca_conservation_sweep:fn_ca_stranded_completing_tournaments',
    'fn_ca_conservation_sweep:fn_ca_rake_rollup_writer_silent',
    'fn_ca_conservation_sweep:fn_ca_absent_tournament_players'
  ];
  v_is_liveness boolean;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_kind := CASE
              WHEN p_kind = 'escalated'    THEN 'escalated'
              WHEN inc.status = 'resolved' THEN 'resolved'
              ELSE 'raised'
            END;

  v_is_liveness := COALESCE(inc.source, '') = ANY (v_liveness);
  v_findings := COALESCE(
      NULLIF(inc.metadata->>'row_count','')::numeric,
      jsonb_array_length(COALESCE(inc.metadata->'rows','[]'::jsonb))::numeric,
      0);

  /* DAN'S RULE, 2026-09-06. Three gates, on the PUSH only. The incident is
     still filed, the event row is still written, the board still shows
     everything - what changes is whose night it interrupts.

     Order matters: 'resolved' is checked first because a fix is the case he
     named explicitly, and it would otherwise slip through on a critical. */
  IF v_kind = 'resolved' THEN
    v_withheld := 'a fix is not a page';
  ELSIF lower(COALESCE(inc.severity,'')) <> 'critical' THEN
    v_withheld := 'severity ' || COALESCE(inc.severity,'null') || ' is not critical';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND NOT v_is_liveness THEN
    v_withheld := 'nothing is unaccounted for (0.00)';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND v_is_liveness AND v_findings = 0 THEN
    /* A liveness detector that found nothing is the healthy case and is not a
       page either. Only a detector that actually found something gets through. */
    v_withheld := 'the check is live and found nothing';
  END IF;

  IF v_withheld IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (inc.id, 'notify_withheld',
            jsonb_build_object('reason', v_withheld, 'kind', v_kind,
                               'severity', inc.severity,
                               'discrepancy', inc.discrepancy_amount,
                               'headline', left(p_headline, 110),
                               'rule', 'Dan 2026-09-06: only critical errors that need my attention'));
    RETURN 0;
  END IF;

  SELECT name INTO club_name  FROM public.clubs  WHERE id = inc.club_id;
  SELECT name INTO union_name FROM public.unions WHERE id = inc.union_id;
  age_min := GREATEST(0, floor(extract(epoch FROM now() - inc.detected_at) / 60))::int;

  IF v_is_liveness AND COALESCE(inc.discrepancy_amount, 0) = 0 THEN
    /* Say what was actually found. "drift 0.00 chips" reads as a rounding
       error, and an alert that reads like a rounding error gets ignored. */
    body := format(
      '%s | %s: %s finding(s) on the %s layer. %s%sAge %smin, reconcile target %s.',
      upper(inc.severity), inc.entity_type,
      to_char(v_findings, 'FM999999999990'),
      inc.layer,
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'));
  ELSE
    body := format(
      '%s | %s drift %s chips (%s layer). Expected %s, actual %s. %s%sAge %smin, reconcile target %s. Auto-repair: %s.',
      upper(inc.severity), inc.classification,
      to_char(COALESCE(inc.discrepancy_amount,0), 'FM999999999990.00'),
      inc.layer,
      COALESCE(to_char(inc.expected_amount,'FM999999999990.00'),'?'),
      COALESCE(to_char(inc.actual_amount,'FM999999999990.00'),'?'),
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'), inc.auto_repair_status);
  END IF;

  v_finding := public.fn_ca_finding_key(inc.dedupe_key, inc.classification, inc.layer,
                                        inc.club_id, inc.union_id);
  v_state := md5(
      v_kind
      || '|' || COALESCE(inc.severity,'?')
      || '|' || COALESCE(inc.classification,'?')
      || '|' || COALESCE(inc.layer,'?')
      || '|' || COALESCE(inc.club_id::text,'-')
      || '|' || COALESCE(inc.union_id::text,'-')
      || '|' || CASE WHEN v_kind = 'escalated'
                     THEN COALESCE(inc.escalation_level, 0)::text ELSE '' END);

  FOR rec IN SELECT unnest(public.fn_ca_incident_recipient_ids(inc, p_senior_only))
  LOOP
    BEGIN
      v_fresh := NULL;
      INSERT INTO public.ca_incident_notify_ledger AS l
        (recipient_id, finding_key, state_hash, last_kind, last_incident_id)
      VALUES (rec, v_finding, v_state, v_kind, inc.id)
      ON CONFLICT (recipient_id, finding_key) DO UPDATE
        SET state_hash = EXCLUDED.state_hash, last_kind = EXCLUDED.last_kind,
            last_incident_id = EXCLUDED.last_incident_id, last_sent_at = now(),
            send_count = l.send_count + 1
        WHERE l.state_hash IS DISTINCT FROM EXCLUDED.state_hash
      RETURNING true INTO v_fresh;

      IF NOT COALESCE(v_fresh, false) THEN
        INSERT INTO public.ca_incident_events (incident_id, kind, detail)
        VALUES (inc.id, 'notified',
                jsonb_build_object('already_reported', true, 'finding_key', v_finding,
                                   'state', v_kind, 'recipient', rec));
        CONTINUE;
      END IF;

      PERFORM public.fn_raise_notification(
        rec, 'financial_incident', left(p_headline, 110), left(body, 480),
        '/hub/club-arena/financial-incidents?id=' || inc.id::text,
        jsonb_build_object('incident_id', inc.id, 'finding_key', v_finding,
                           'classification', inc.classification, 'severity', inc.severity,
                           'discrepancy', inc.discrepancy_amount, 'club_id', inc.club_id,
                           'union_id', inc.union_id, 'deadline_at', inc.deadline_at));
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'notify_failed',
              jsonb_build_object('recipient', rec, 'error', SQLERRM));
    END;
  END LOOP;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (inc.id, p_kind,
          jsonb_build_object('headline', p_headline, 'recipients', n,
                             'senior_only', p_senior_only, 'age_min', age_min,
                             'finding_key', v_finding, 'state', v_kind));
  RETURN n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_incident_notify failed for %: %', p_incident_id, SQLERRM;
  RETURN 0;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_get_club_realtime_member_count(p_club_id uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT count(*)::bigint
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id
     AND (cm.status IS NULL OR cm.status IN ('active', 'approved'));
$function$;
CREATE OR REPLACE FUNCTION public.fn_batch_union_realtime_member_counts(p_union_ids uuid[])
 RETURNS TABLE(union_id uuid, member_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT requested.union_id, count(cm.user_id)::bigint
    FROM unnest(p_union_ids) requested(union_id)
    LEFT JOIN public.union_clubs uc ON uc.union_id = requested.union_id
    LEFT JOIN public.club_members cm ON cm.club_id = uc.club_id
      AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
   GROUP BY requested.union_id;
$function$;
CREATE OR REPLACE FUNCTION public.fn_seat_club_for_user_membership_unchecked(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_union uuid; v_table_club uuid; v_club uuid;
  v_is_horse boolean := false; v_n int; v_idx int;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM tables t WHERE t.id = p_table_id;

  IF v_union IS NULL THEN
    RETURN v_table_club;                       -- standalone club game
  END IF;

  -- ONE CLUB AT A TIME (Dan 2026-08-21). If this player is already sitting
  -- somewhere in this union, the club they are already representing wins -
  -- over the preferred club, over the hash, over membership order. Everything
  -- below only decides where a player who is NOT currently seated starts.
  SELECT ts.club_id INTO v_club
    FROM table_seats ts
    JOIN tables t2 ON t2.id = ts.table_id
   WHERE ts.user_id = p_user_id
     AND ts.left_at IS NULL
     AND ts.club_id IS NOT NULL
     AND t2.union_id = v_union
     AND lower(coalesce(t2.status, '')) NOT IN ('closed','completed','cancelled','finished')
   ORDER BY ts.joined_at ASC NULLS LAST
   LIMIT 1;
  IF v_club IS NOT NULL THEN
    RETURN v_club;
  END IF;

  -- Honour the club the player entered through, when they really are a member.
  IF p_preferred_club IS NOT NULL
     AND EXISTS (SELECT 1 FROM club_members m
                  JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
                 WHERE m.user_id = p_user_id AND m.club_id = p_preferred_club
                   AND m.status IN ('active','approved'))
  THEN
    RETURN p_preferred_club;
  END IF;

  SELECT COALESCE(p.is_horse, false) INTO v_is_horse FROM profiles p WHERE p.id = p_user_id;

  IF v_is_horse THEN
    -- Stable home club for a simulated player that is not currently seated:
    -- deterministic from its own id, so horses spread across the union's clubs
    -- instead of all piling into the oldest one.
    SELECT count(*) INTO v_n
      FROM club_members m
      JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
     WHERE m.user_id = p_user_id AND m.status IN ('active','approved');

    IF v_n > 1 THEN
      v_idx := (abs(hashtextextended(p_user_id::text, 0)) % v_n)::int;
      SELECT m.club_id INTO v_club
        FROM club_members m
        JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
       WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
       ORDER BY m.club_id
       OFFSET v_idx LIMIT 1;
      IF v_club IS NOT NULL THEN RETURN v_club; END IF;
    END IF;
  END IF;

  -- Real players: oldest membership.
  SELECT m.club_id INTO v_club
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
   WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
   ORDER BY m.joined_at ASC NULLS LAST, m.club_id
   LIMIT 1;

  RETURN v_club;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_is_midway_scope(p_union_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    -- THE FOUR ESTATES (Dan, 2026-09-03): Midway Union with Club JAQK and
    -- SHARK CLUB inside it, and Deep Stack Society standing alone. Until
    -- chip standard Phase 4.3 (2026-09-04) this scope was Midway only, so an
    -- incident about Deep Stack Society's money - its jackpot reserve running
    -- dry, a payout that could not reconcile - was dropped before it was
    -- filed. Deep Stack is an estate; its incidents file.
    -- platform-substrate incidents: no entity dimension anywhere = global
    -- checks (supply, suspense, guards, crons, diamonds) that protect every
    -- union including Midway. These always file.
    (p_union_id IS NULL AND p_club_id IS NULL AND p_table_id IS NULL
     AND p_tournament_id IS NULL
     AND COALESCE(p_metadata->>'union_id','') = ''
     AND COALESCE(p_metadata->>'club_id','') = '')
    OR p_union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    OR p_club_id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id = p_club_id
         AND c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.union_clubs uc
       WHERE uc.club_id = p_club_id
         AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.tables t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_table_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR EXISTS (
      SELECT 1 FROM public.tournaments t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_tournament_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR COALESCE(p_metadata->>'union_id', '') = 'fade0000-0000-0000-0000-000000000001'
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id::text = COALESCE(p_metadata->>'club_id', '')
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )), false);
$function$;
CREATE OR REPLACE FUNCTION public.fn_spin_book_entry(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t record;
  v_owner uuid;
  v_pool_id uuid;
  v_table_id uuid;
  v_live_seats integer;
  v_seat_users integer;
  v_exact_seat_stacks integer;
  v_roster_users integer;
  v_paid_users integer;
  v_buyin_debits integer;
  v_buyin_total numeric;
  v_collected numeric;
  v_rake_rate numeric;
  v_rake numeric;
  v_reserve_in numeric;
  v_balance numeric;
  v_reserve public.spin_reserve_ledger%ROWTYPE;
  v_reserve_count integer;
  v_journal_id uuid;
  v_journal_count integer;
  v_entry_existed boolean := false;
  v_contrib jsonb;
  v_key text := 'spin:' || p_tournament_id::text || ':entry';
BEGIN
  SELECT t.id, t.club_id, t.buy_in_amount, t.max_players, t.variant,
         t.starting_chips,
         t.tournament_type, t.status
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR (lower(COALESCE(v_t.variant,'')) <> 'spin'
         AND upper(COALESCE(v_t.tournament_type,'')) <> 'SPIN') THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_spin');
  END IF;
  IF v_t.club_id IS NULL OR COALESCE(v_t.buy_in_amount,0) <= 0
     OR COALESCE(v_t.max_players,0) <> 3
     OR v_t.starting_chips IS NULL
     OR v_t.starting_chips::text IN ('NaN','Infinity','-Infinity')
     OR v_t.starting_chips <= 0
     OR upper(COALESCE(v_t.status::text,'')) IN ('COMPLETED','CANCELLED','CANCELED') THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_spin_contract');
  END IF;

  v_table_id := public.fn_tournament_primary_table(p_tournament_id);
  SELECT count(*), count(DISTINCT s.user_id),
         count(*) FILTER (
           WHERE s.stack IS NOT DISTINCT FROM v_t.starting_chips
             AND s.stack::text NOT IN ('NaN','Infinity','-Infinity')
             AND s.stack > 0)
    INTO v_live_seats, v_seat_users, v_exact_seat_stacks
    FROM public.table_seats s
   WHERE s.table_id = v_table_id AND s.left_at IS NULL;
  SELECT count(DISTINCT tp.user_id)
    INTO v_roster_users
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_paid_users
    FROM (
      SELECT tp.user_id
        FROM public.tournament_players tp
        JOIN public.wallet_transactions w
          ON w.related_entity_id = tp.tournament_id
         AND w.user_id = tp.user_id
         AND w.type = 'debit'
         AND w.category = 'tournament_buyin'
       WHERE tp.tournament_id = p_tournament_id
       GROUP BY tp.user_id
      HAVING round(sum(w.amount),2) = round(v_t.buy_in_amount,2)
    ) paid;
  SELECT count(*), round(COALESCE(sum(w.amount),0),2)
    INTO v_buyin_debits,v_buyin_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND w.type = 'debit'
     AND w.category = 'tournament_buyin';
  SELECT EXISTS (
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution'
  ) INTO v_entry_existed;

  -- The live-seat distribution is an admission proof, not an immutable
  -- receipt proof. The third-seat transaction must begin with three exact
  -- starting stacks. Once its contribution exists, hands may redistribute or
  -- vacate those stacks; replay proves the three paid identities and the
  -- immutable contribution+journal below without demanding pre-hand state.
  IF (NOT v_entry_existed AND (
       v_table_id IS NULL OR v_live_seats <> 3 OR v_seat_users <> 3
       OR v_exact_seat_stacks <> 3
       OR EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND NOT EXISTS (
              SELECT 1 FROM public.table_seats s
               WHERE s.table_id = v_table_id AND s.left_at IS NULL
                 AND s.user_id = tp.user_id))))
     OR v_roster_users <> 3 OR v_paid_users <> 3
     OR v_buyin_debits <> 3
     OR v_buyin_total <> round(v_t.buy_in_amount * 3,2) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','three_paid_seats_required',
      'seats',v_live_seats,'seat_users',v_seat_users,
      'exact_seat_stacks',v_exact_seat_stacks,
      'roster_users',v_roster_users,'paid_users',v_paid_users,
      'buyin_debits',v_buyin_debits,'buyin_total',v_buyin_total);
  END IF;

  -- One lock order for both the seat trigger and the start authority.
  PERFORM 1 FROM public.tournament_escrow
   WHERE tournament_id = p_tournament_id FOR UPDATE;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('spin_entry:' || p_tournament_id::text,0));

  v_owner := public.fn_spin_reserve_pool(v_t.club_id);
  SELECT p.id, p.balance INTO v_pool_id, v_balance
    FROM public.spin_bonus_pools p
   WHERE p.club_id = v_owner
   FOR UPDATE;
  IF v_pool_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','no_pool_row','owner_id',v_owner);
  END IF;

  v_collected := round(v_t.buy_in_amount * 3,2);
  v_rake_rate := public.fn_spin_rake_rate(v_t.buy_in_amount);
  v_rake := round(v_collected * v_rake_rate,2);
  v_reserve_in := round(v_collected - v_rake,2);

  SELECT count(*) INTO v_reserve_count
    FROM public.spin_reserve_ledger r
   WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution';
  IF v_reserve_count > 0 THEN
    IF v_reserve_count <> 1 THEN
      RAISE EXCEPTION 'Spin % has % contribution rows',
        p_tournament_id,v_reserve_count USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_reserve
      FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution'
     FOR SHARE;
    IF v_reserve.club_id IS DISTINCT FROM v_owner
       OR v_reserve.amount IS DISTINCT FROM v_reserve_in
       OR v_reserve.buy_in IS DISTINCT FROM v_t.buy_in_amount
       OR v_reserve.seats IS DISTINCT FROM 3
       OR v_reserve.house_rake IS DISTINCT FROM v_rake THEN
      RAISE EXCEPTION 'Spin % existing contribution disagrees with its paid entry',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*) INTO v_journal_count
      FROM public.chip_ledger l
     WHERE l.category = 'spin_entry'
       AND l.from_type = 'prize_liability'
       AND l.from_entity_id = p_tournament_id
       AND l.to_type = 'spin_reserve'
       AND l.to_entity_id = v_pool_id
       AND l.tournament_id = p_tournament_id
       AND l.amount = v_reserve_in;
    IF v_journal_count <> 1 THEN
      RAISE EXCEPTION 'Spin % existing contribution has % exact journals',
        p_tournament_id,v_journal_count USING ERRCODE = 'P0404';
    END IF;
    SELECT l.id INTO v_journal_id
      FROM public.chip_ledger l
     WHERE l.category = 'spin_entry'
       AND l.from_type = 'prize_liability'
       AND l.from_entity_id = p_tournament_id
       AND l.to_type = 'spin_reserve'
       AND l.to_entity_id = v_pool_id
       AND l.tournament_id = p_tournament_id
       AND l.amount = v_reserve_in;
    RETURN jsonb_build_object(
      'ok',true,'reason','already_booked','collected',v_collected,
      'house_rake',v_rake,'reserve_in',v_reserve_in,'balance',v_balance,
      'owner_id',v_owner,'pool_id',v_pool_id,'seats',3,'paid_users',3,
      'entry_reserve_id',v_reserve.id,'entry_journal_id',v_journal_id);
  END IF;

  PERFORM public.fn_ca_declare_ledger(
    'spin_entry','prize_liability',p_tournament_id,NULL,v_key,NULL);
  UPDATE public.spin_bonus_pools
     SET balance = balance + v_reserve_in,
         total_deposited = total_deposited + v_reserve_in,
         spin_count = spin_count + 1,
         highest_stake = GREATEST(highest_stake,v_t.buy_in_amount),
         updated_at = now()
   WHERE id = v_pool_id
   RETURNING balance INTO v_balance;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Spin reserve pool % vanished while booking %',
      v_pool_id,p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  INSERT INTO public.spin_reserve_ledger
    (club_id,tournament_id,kind,amount,balance_after,multiplier,
     buy_in,seats,house_rake,note)
  VALUES
    (v_owner,p_tournament_id,'contribution',v_reserve_in,v_balance,NULL,
     v_t.buy_in_amount,3,v_rake,
     CASE WHEN v_owner = v_t.club_id
          THEN 'three exact paid buy-ins less fixed rake'
          ELSE format('three exact paid buy-ins less fixed rake (club %s)',v_t.club_id)
      END)
  RETURNING * INTO v_reserve;

  SELECT count(*), (array_agg(l.id ORDER BY l.created_at,l.id))[1]
    INTO v_journal_count,v_journal_id
    FROM public.chip_ledger l
   WHERE l.idempotency_key = v_key
     AND l.category = 'spin_entry'
     AND l.from_type = 'prize_liability'
     AND l.from_entity_id = p_tournament_id
     AND l.to_type = 'spin_reserve'
     AND l.to_entity_id = v_pool_id
     AND l.tournament_id = p_tournament_id
     AND l.amount = v_reserve_in;
  IF v_journal_count <> 1 THEN
    RAISE EXCEPTION 'Spin % new contribution has % exact keyed journals',
      p_tournament_id,v_journal_count USING ERRCODE = 'P0404';
  END IF;

  SELECT jsonb_object_agg(tp.user_id::text,v_t.buy_in_amount)
    INTO v_contrib
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_rake > 0 THEN
    INSERT INTO public.rake_records
      (hand_id,table_id,club_id,rake_amount,pot_size,num_players,
       bbj_contribution,is_tournament,tournament_id,source,
       player_contributions,metadata)
    VALUES
      (NULL,NULL,v_t.club_id,v_rake,v_collected,3,0,true,p_tournament_id,
       'fn_spin_book_entry',v_contrib,
       jsonb_build_object(
         'kind','spin_rake','buy_in',v_t.buy_in_amount,
         'rake_rate',v_rake_rate,'booked_at','third_paid_seat',
         'reserve_owner',v_owner,'treasury_credited',false,
         'distributed_by','atomic_distribute_rake',
         'rake_per_player',round(v_rake / 3,4),'seats_attributed',3));
  END IF;

  PERFORM set_config('app.ledger_category','',true);
  PERFORM set_config('app.ledger_counterparty','',true);
  PERFORM set_config('app.ledger_counterparty_entity','',true);
  PERFORM set_config('app.ledger_idempotency_key','',true);

  RETURN jsonb_build_object(
    'ok',true,'reason','booked','collected',v_collected,
    'house_rake',v_rake,'reserve_in',v_reserve_in,'balance',v_balance,
    'owner_id',v_owner,'pool_id',v_pool_id,'seats',3,'paid_users',3,
    'entry_reserve_id',v_reserve.id,'entry_journal_id',v_journal_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_game_management_scope(p_club_id uuid)
 RETURNS TABLE(scope_kind text, scope_id uuid, union_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN x.union_id IS NULL THEN 'club' ELSE 'union' END,
         COALESCE(x.union_id, p_club_id), x.union_id
  FROM (
    SELECT COALESCE(c.union_id, uc.union_id) AS union_id
    FROM public.clubs c
    LEFT JOIN public.union_clubs uc ON uc.club_id=c.id
    WHERE c.id=p_club_id
    ORDER BY uc.joined_at DESC NULLS LAST
    LIMIT 1
  ) x
$function$;
CREATE OR REPLACE FUNCTION public.fn_safe_jsonb_array(p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  IF p_text IS NULL OR btrim(p_text) = '' THEN
    RETURN '[]'::jsonb;
  END IF;
  BEGIN
    v := p_text::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN '[]'::jsonb;
  END;
  IF v IS NULL OR jsonb_typeof(v) <> 'array' THEN
    RETURN '[]'::jsonb;
  END IF;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_mint_social_alias(p_seed text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_w1 text[];
  v_w2 text[];
  v_base text;
  v_cand text;
  v_n integer := 0;
  v_h bigint;
BEGIN
  SELECT array_agg(w ORDER BY w) INTO v_w1
    FROM (SELECT DISTINCT (regexp_match(alias, '^([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;
  SELECT array_agg(w ORDER BY w) INTO v_w2
    FROM (SELECT DISTINCT (regexp_match(alias, '^[A-Z][a-z]+([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;

  IF v_w1 IS NULL OR v_w2 IS NULL
     OR COALESCE(array_length(v_w1, 1), 0) = 0
     OR COALESCE(array_length(v_w2, 1), 0) = 0 THEN
    RAISE EXCEPTION 'fn_mint_social_alias: no alias vocabulary to draw from';
  END IF;

  v_h := abs(hashtext(p_seed));

  LOOP
    v_base := v_w1[1 + ((v_h + v_n * 7919) % array_length(v_w1, 1))]
           || v_w2[1 + (((v_h / 17) + v_n * 104729) % array_length(v_w2, 1))];
    -- Pure handles first. Once fifty probes have all collided we are in a
    -- crowded corner of the space, so take the discriminator rather than
    -- probing forever: this is the safety net that 2026-09-01 did not have.
    v_cand := CASE WHEN v_n < 50 THEN v_base ELSE v_base || (v_n - 49)::text END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.content_authors WHERE alias = v_cand);
    v_n := v_n + 1;
    IF v_n > 100000 THEN
      RAISE EXCEPTION 'fn_mint_social_alias: could not mint a free alias for %', p_seed;
    END IF;
  END LOOP;

  RETURN v_cand;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_arena_name(p_alias text, p_username text, p_display_name text, p_first_name text, p_last_name text, p_full_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH real_name AS (
    SELECT COALESCE(
             NULLIF(btrim(p_full_name), ''),
             NULLIF(btrim(concat_ws(' ',
               NULLIF(btrim(p_first_name), ''),
               NULLIF(btrim(p_last_name),  ''))), '')
           ) AS rn
  )
  SELECT COALESCE(
           NULLIF(btrim(p_alias), ''),
           NULLIF(btrim(p_username), ''),
           CASE
             WHEN NULLIF(btrim(p_display_name), '') IS NOT NULL
              AND (SELECT rn FROM real_name) IS NOT NULL
              AND lower(btrim(p_display_name)) = lower((SELECT rn FROM real_name))
             THEN NULL
             ELSE NULLIF(btrim(p_display_name), '')
           END,
           'Player')
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_level_min_members(p_level integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT min_members FROM public.club_level_thresholds
      WHERE level = LEAST(GREATEST(COALESCE(p_level, 1), 1),
                          (SELECT MAX(level) FROM public.club_level_thresholds))),
    0);
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_club_rake_daily_compute(p_from timestamp with time zone, p_to timestamp with time zone, p_ids uuid[])
 RETURNS TABLE(club_id uuid, stat_date date, hands bigint, rake numeric, bbj numeric, pot numeric, source_rows bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH src AS (
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0) AS rake, coalesce(r.bbj_contribution, 0) AS bbj,
           coalesce(r.pot_size, 0) AS pot, r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NOT NULL AND r.id = ANY (p_ids)
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
    UNION ALL
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0), coalesce(r.bbj_contribution, 0),
           coalesce(r.pot_size, 0), r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NULL AND r.created_at >= p_from AND r.created_at < p_to
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
  ),
  tbl AS (
    SELECT s.id, s.club_id AS table_club, (s.created_at AT TIME ZONE 'UTC')::date AS day,
           s.rake, s.bbj, s.pot, s.player_contributions, t.union_id
      FROM src s
      LEFT JOIN tables t ON t.id = s.table_id
     WHERE t.id IS NULL OR t.tournament_id IS NULL
  ),
  -- Only a union table needs its contributions read: a standalone table's
  -- rake has exactly one place to go. A key that is not a uuid or a value
  -- that is not a number is ignored, never raised: a reporting rollup must
  -- not fail a ledger write. A contribution of zero still counts the hand
  -- for that player's club, as club_table_daily counts it.
  contrib AS (
    SELECT b.id, b.union_id,
           CASE WHEN e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN e.key::uuid END AS uid,
           CASE WHEN e.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN e.value::numeric END AS contrib
      FROM tbl b
      CROSS JOIN LATERAL jsonb_each_text(
        CASE WHEN jsonb_typeof(b.player_contributions) = 'object'
             THEN b.player_contributions ELSE '{}'::jsonb END) e
     WHERE b.union_id IS NOT NULL
  ),
  attributed AS (
    SELECT c.id, c.contrib,
           coalesce((SELECT cm.club_id
                       FROM club_members cm
                       JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = c.union_id
                      WHERE cm.user_id = c.uid
                      ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
                      LIMIT 1),
                    b.table_club) AS club_id
      FROM contrib c JOIN tbl b ON b.id = c.id
     WHERE c.uid IS NOT NULL AND c.contrib IS NOT NULL AND c.contrib >= 0
  ),
  split AS (
    SELECT a.id, a.club_id, sum(a.contrib) AS contrib, count(*) AS src_rows
      FROM attributed a GROUP BY a.id, a.club_id
  ),
  split_total AS (
    SELECT s.id, sum(s.contrib) AS tot FROM split s GROUP BY s.id
  ),
  hand_rows AS (
    SELECT b.*, EXISTS (SELECT 1 FROM split_total st WHERE st.id = b.id AND st.tot > 0) AS has_split
      FROM tbl b
  ),
  parts AS (
    -- A union hand with a usable split: rake by contribution share, and one
    -- hand for every club that contributed.
    SELECT h.day, s.club_id, 1::bigint AS hands, h.rake * s.contrib / st.tot AS rake,
           0::numeric AS bbj, 0::numeric AS pot, s.src_rows
      FROM split s
      JOIN split_total st ON st.id = s.id AND st.tot > 0
      JOIN hand_rows h ON h.id = s.id
    UNION ALL
    -- The table's club: the drop and the pot volume of every hand it hosted,
    -- plus the whole hand when nothing could be attributed.
    SELECT h.day, h.table_club,
           CASE WHEN h.has_split THEN 0 ELSE 1 END,
           CASE WHEN h.has_split THEN 0 ELSE h.rake END,
           h.bbj, h.pot,
           CASE WHEN h.has_split THEN 0 ELSE 1 END
      FROM hand_rows h
  )
  SELECT p.club_id, p.day, sum(p.hands)::bigint, sum(p.rake), sum(p.bbj), sum(p.pot),
         sum(p.src_rows)::bigint
    FROM parts p
   GROUP BY p.club_id, p.day;
$function$;
CREATE OR REPLACE FUNCTION public.fn_fleet_cadence(p_profile_id uuid)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 45 THEN 1
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 75 THEN 2
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 90 THEN 3
    ELSE 7 END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_stable_dedupe_key(p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  /* Strips a trailing period label: :2026-09-06, :2026-09-06-18, :2026-36.
     Used ONLY together with an equal discrepancy, so an hourly bucket that
     reports a different number is never folded into another one. */
  SELECT regexp_replace($1, ':([0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?|[0-9]{4}-[0-9]{1,2})$', '')
$function$;
CREATE OR REPLACE FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A Daily Missions player is required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('daily-missions-user:' || p_user_id::text, 0)
  );

  PERFORM 1
  FROM public.profiles
  WHERE id = p_user_id
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Daily Missions profile not found for player %', p_user_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(id uuid, challenge_id text, progress integer, requirement integer, chip_reward numeric, diamond_reward integer, newly_completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_event public.daily_challenge_progress_events%ROWTYPE;
  v_event_found boolean;
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  SELECT * INTO v_event
  FROM public.daily_challenge_progress_events
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;
  v_event_found := FOUND;

  IF v_event_found
     AND (
       v_event.amounts IS DISTINCT FROM p_amounts
       OR v_event.magnitudes IS DISTINCT FROM p_magnitudes
       OR v_event.threshold_values IS DISTINCT FROM '{}'::jsonb
       OR v_event.occurred_at IS DISTINCT FROM p_occurred_at
     )
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.record_daily_challenge_event_serialized_body(
    p_user_id,
    p_event_key,
    p_amounts,
    p_magnitudes,
    p_occurred_at
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb, p_values jsonb, p_occurred_at timestamp with time zone)
 RETURNS TABLE(id uuid, challenge_id text, progress integer, requirement integer, chip_reward numeric, diamond_reward integer, newly_completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inserted integer;
  v_event public.daily_challenge_progress_events%ROWTYPE;
  v_daily_key text;
  v_weekly_key text;
  v_monthly_key text;
BEGIN
  IF p_user_id IS NULL OR p_event_key IS NULL
     OR length(p_event_key) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'A player and stable event key are required';
  END IF;
  IF p_amounts IS NULL OR jsonb_typeof(p_amounts) <> 'object'
     OR p_magnitudes IS NULL OR jsonb_typeof(p_magnitudes) <> 'object'
     OR p_values IS NULL OR jsonb_typeof(p_values) <> 'object' THEN
    RAISE EXCEPTION 'Challenge event amounts, magnitudes, and values must be JSON objects';
  END IF;
  IF p_occurred_at < now() - interval '35 days'
     OR p_occurred_at > now() + interval '1 minute' THEN
    RAISE EXCEPTION 'Daily Missions events must be recorded at their authoritative occurrence time';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_amounts) key
    WHERE key NOT IN (
      'hands_played',
      'hands_won',
      'showdowns',
      'showdowns_won',
      'hands_won_no_showdown',
      'big_pots',
      'strong_hands',
      'chips_won',
      'tournaments_played',
      'friends_added'
    )
  ) THEN
    RAISE EXCEPTION 'Unknown Daily Missions event type';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_each_text(p_amounts) item
    WHERE CASE
      WHEN item.value ~ '^\d+$' THEN
        item.value::numeric < 0
        OR (item.key = 'chips_won' AND item.value::numeric > 1000000000)
        OR (item.key <> 'chips_won' AND item.value::numeric > 2500)
      ELSE true
    END
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_each_text(p_magnitudes) item
    WHERE CASE
      WHEN item.value ~ '^\d+(\.\d+)?$' THEN
        item.value::numeric < 0 OR item.value::numeric > 1000000000
      ELSE true
    END
  ) THEN
    RAISE EXCEPTION 'Daily Missions event values are outside their server contract';
  END IF;

  -- Only catalog types with per-occurrence thresholds may carry value arrays.
  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_values) item
    WHERE item.key NOT IN ('big_pots', 'strong_hands')
       OR jsonb_typeof(item.value) <> 'array'
  ) THEN
    RAISE EXCEPTION 'Daily Missions exact values have an invalid category or shape';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_values) item
    WHERE jsonb_array_length(item.value) > 2500
  ) THEN
    RAISE EXCEPTION 'Daily Missions exact values exceed the event candidate limit';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_values) item
    WHERE NOT (p_amounts ? item.key)
       OR jsonb_array_length(item.value) <> (p_amounts ->> item.key)::integer
  ) THEN
    RAISE EXCEPTION 'Daily Missions exact values must match their scalar candidate count';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_values) category
    CROSS JOIN LATERAL jsonb_array_elements(category.value) AS candidate(value)
    WHERE CASE
      WHEN jsonb_typeof(candidate.value) = 'number' THEN
        candidate.value::text::numeric < 0
        OR candidate.value::text::numeric > 1000000000
        OR (category.key = 'strong_hands' AND candidate.value::text::numeric > 20)
      ELSE true
    END
  ) THEN
    RAISE EXCEPTION 'Daily Missions exact values must be bounded nonnegative numbers';
  END IF;

  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  v_daily_key := to_char((p_occurred_at AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_weekly_key := 'W'
    || to_char(date_trunc('week', p_occurred_at AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_monthly_key := 'M' || to_char(p_occurred_at AT TIME ZONE 'utc', 'YYYY-MM');

  INSERT INTO public.daily_challenge_progress_events (
    user_id,
    event_key,
    amounts,
    magnitudes,
    threshold_values,
    occurred_at
  ) VALUES (
    p_user_id,
    p_event_key,
    p_amounts,
    p_magnitudes,
    p_values,
    p_occurred_at
  )
  ON CONFLICT (user_id, event_key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    SELECT * INTO STRICT v_event
    FROM public.daily_challenge_progress_events
    WHERE user_id = p_user_id
      AND event_key = p_event_key
    FOR UPDATE;

    IF v_event.amounts IS DISTINCT FROM p_amounts
       OR v_event.magnitudes IS DISTINCT FROM p_magnitudes
       OR v_event.threshold_values IS DISTINCT FROM p_values
       OR v_event.occurred_at IS DISTINCT FROM p_occurred_at
    THEN
      RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
    END IF;

    RETURN;
  END IF;

  PERFORM public.fn_assign_current_challenge_period(
    p_user_id,
    'daily',
    v_daily_key,
    5
  );
  PERFORM public.fn_assign_current_challenge_period(
    p_user_id,
    'weekly',
    v_weekly_key,
    3
  );
  PERFORM public.fn_assign_current_challenge_period(
    p_user_id,
    'monthly',
    v_monthly_key,
    2
  );

  RETURN QUERY
  WITH scalar_bumps AS (
    SELECT key AS challenge_type,
           GREATEST(COALESCE((value #>> '{}')::integer, 0), 0) AS amount
    FROM jsonb_each(p_amounts)
  ), calculated_bumps AS (
    SELECT u.id,
           CASE
             WHEN u.threshold_snapshot IS NULL THEN b.amount
             WHEN p_values ? u.challenge_type_snapshot THEN (
               SELECT count(*)::integer
               FROM jsonb_array_elements(
                 p_values -> u.challenge_type_snapshot
               ) AS candidate(value)
               WHERE candidate.value::text::numeric >= u.threshold_snapshot
             )
             WHEN COALESCE(
               (p_magnitudes -> u.challenge_type_snapshot) #>> '{}',
               '0'
             )::numeric >= u.threshold_snapshot THEN b.amount
             ELSE 0
           END AS amount
    FROM public.user_daily_challenges u
    JOIN scalar_bumps b
      ON b.challenge_type = u.challenge_type_snapshot
    WHERE u.user_id = p_user_id
      AND u.completed = false
      AND u.assigned_date IN (v_daily_key, v_weekly_key, v_monthly_key)
  ), updated AS (
    UPDATE public.user_daily_challenges u
    SET progress = LEAST(
          u.progress + calculated.amount,
          u.requirement_snapshot
        ),
        completed = (u.progress + calculated.amount) >= u.requirement_snapshot,
        completed_at = CASE
          WHEN (u.progress + calculated.amount) >= u.requirement_snapshot
               AND u.completed_at IS NULL THEN now()
          ELSE u.completed_at
        END
    FROM calculated_bumps calculated
    WHERE u.id = calculated.id
      AND calculated.amount > 0
    RETURNING u.id,
              u.challenge_id,
              u.progress,
              u.requirement_snapshot,
              u.chip_reward_snapshot,
              u.diamond_reward_snapshot,
              u.completed
  )
  SELECT updated.id,
         updated.challenge_id,
         updated.progress,
         updated.requirement_snapshot,
         updated.chip_reward_snapshot,
         updated.diamond_reward_snapshot,
         updated.completed
  FROM updated;

  -- DIAMOND-RULINGS 3 (CLAUDE.md 10.5, horses are players): a horse has no browser, so the
  -- engine is its input device and it presses Claim the moment a human would be shown the
  -- and never breaks the progress just recorded.
  --
  -- five-argument serialized body, which nothing in the engine reaches; 733 challenges completed
  -- and 0 were claimed before this was noticed.
  -- The horse claim used to run here, which keyed it to a horse DOING something: a horse that
    -- stopped playing stopped claiming, and 23 quiet horses accumulated 759 rewards worth
    -- 51,380 diamonds. It is now fn_ca_horse_claim_due, keyed to who is OWED, on a minute
    -- tick. Recording an event does not pay anybody (CLAUDE.md 10.5, 10.11).
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_agent_commission_paid_by_period(p_club_id uuid, p_user_id uuid, p_created_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                  WHERE s.club_id = p_club_id AND s.user_id = p_user_id
                    AND p_created_at >= s.period_start AND p_created_at < s.period_end);
$function$;
CREATE OR REPLACE FUNCTION public.fn_active_maintenance_release_boundary()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  c_required_steps CONSTANT text[] := ARRAY[
    'sit_out_at','hold_expires_at','addon_period_ends_at','reversible_until',
    'reveal_deadline_at','rebuy_prompt_until','bomb_pot_next_due_at',
    'cash_stay_last_tick_at','cash_rejoin_expires_at','level_started_at',
    'cluster_break_eligible_since','cluster_move_expires_at',
    'reconnect_presence','reconnect_snapshots'
  ];
  v_request_role text := NULLIF(btrim(COALESCE(auth.role(), '')), '');
  v_trusted_database_actor boolean;
  v_release_target timestamptz;
BEGIN
  -- supabase_auth_admin added 2026-09-10: it is GoTrue's own database role
  -- (the signup triggers run as it), never a browser. Without it every signup
  -- wallet trigger raised 42501 here (signup_errors id 9318).
  SELECT session_user IN ('postgres', 'supabase_admin', 'service_role', 'supabase_auth_admin')
         OR COALESCE(r.rolsuper, false)
    INTO v_trusted_database_actor
    FROM (SELECT session_user AS role_name) s
    LEFT JOIN pg_catalog.pg_roles r ON r.rolname = s.role_name;

  IF v_request_role IS NOT NULL
     AND v_request_role NOT IN ('anon', 'authenticated', 'service_role') THEN
    RAISE EXCEPTION 'MAINTENANCE_RELEASE_CERTIFICATE_CALLER_REFUSED'
      USING ERRCODE = '42501';
  END IF;
  IF v_request_role IS NULL AND NOT COALESCE(v_trusted_database_actor, false) THEN
    RAISE EXCEPTION 'MAINTENANCE_RELEASE_CERTIFICATE_CALLER_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  -- PERF (2026-09-10, swarm A): OFFSET 0 is an optimisation fence. Without it
  -- the planner evaluated `shifted ?& c_required_steps` first on every row of
  -- engine_maintenance_thaws (167 rows, 0 of them contract_version 3) on every
  -- money write that reaches fn_platform_frozen: 229 us -> 32 us per call.
  -- Same four quals, same max(); the jsonb quals now only see rows that already
  -- passed contract_version = 3 AND release_target_at > clock_timestamp().
  SELECT max(t.release_target_at) INTO v_release_target
    FROM (SELECT t.release_target_at, t.shifted
            FROM public.engine_maintenance_thaws t
           WHERE t.contract_version = 3
             AND t.release_target_at > clock_timestamp()
          OFFSET 0) t
   WHERE COALESCE((t.shifted->>'complete')::boolean, false)
     AND t.shifted ?& c_required_steps;
  RETURN v_release_target;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_blind_contract_number(p_value jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v numeric; t text:=p_value #>> '{}';
BEGIN
  IF jsonb_typeof(p_value) NOT IN ('number','string') OR t !~ '^[0-9]+([.][0-9]+)?$' THEN RETURN NULL; END IF;
  v:=t::numeric;
  IF v>9007199254740991 THEN RETURN NULL; END IF;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-'source_ledger_ids');
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,'accounting_invoice',CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number,
     CASE WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips',
     meta,false,'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $function$;
CREATE OR REPLACE FUNCTION public.fn_club_is_in_downline(p_club_id uuid, p_upline_user_id uuid, p_member_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH RECURSIVE dl AS (
    SELECT cm.user_id, 1 AS depth
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.agent_id = p_upline_user_id
       AND p_upline_user_id IS NOT NULL
       AND p_member_user_id IS NOT NULL
       AND p_upline_user_id <> p_member_user_id
    UNION
    SELECT cm.user_id, dl.depth + 1
      FROM public.club_members cm
      JOIN dl ON cm.agent_id = dl.user_id
     WHERE cm.club_id = p_club_id
       AND dl.depth < 20
  )
  SELECT EXISTS (SELECT 1 FROM dl WHERE dl.user_id = p_member_user_id);
$function$;
CREATE OR REPLACE FUNCTION public.fn_spin_reserve_pool(p_club_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_owner uuid;
BEGIN
  v_owner := public.fn_spin_reserve_owner(p_club_id);

  INSERT INTO public.spin_bonus_pools (club_id, owner_kind)
  VALUES (v_owner,
          CASE WHEN EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_owner)
               THEN 'union' ELSE 'club' END)
  ON CONFLICT (club_id) DO NOTHING;

  RETURN v_owner;
END; $function$;
CREATE OR REPLACE FUNCTION public.fn_spin_rake_rate(p_buy_in numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  -- ONE rate at every stake. The multiplier table is what actually charges
  -- the rake, and its expectation (2.7638 over 3 seats) is 8% and no other
  -- number. See src/config/spinSpec.ts "THE BANDS ARE GONE".
  SELECT 0.08;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_incident_recipient_ids(p_incident ca_drift_incidents, p_senior_only boolean DEFAULT false)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- REGISTRY-ONLY (2026-08-31, Dan's directive): financial incident pushes
  -- go to the active rows of ca_incident_recipients and to nobody else.
  -- The old dynamic fan-out to affected club/union owners is deliberately
  -- gone - an incident about a club must never page that club's owner.
  SELECT COALESCE(array_agg(DISTINCT r.user_id), '{}')
  FROM public.ca_incident_recipients r
  WHERE r.active
    AND (NOT p_senior_only OR r.senior)
    AND (r.scope IN ('platform','financial_ops','technical')
         OR (r.scope = 'union' AND r.scope_id = p_incident.union_id)
         OR (r.scope = 'club'  AND r.scope_id = p_incident.club_id))
$function$;
CREATE OR REPLACE FUNCTION public.record_daily_challenge_event_serialized_body(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(id uuid, challenge_id text, progress integer, requirement integer, chip_reward numeric, diamond_reward integer, newly_completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inserted integer;
  v_daily_key text;
  v_weekly_key text;
  v_monthly_key text;
BEGIN
  IF p_user_id IS NULL OR p_event_key IS NULL OR length(p_event_key) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'A player and stable event key are required';
  END IF;
  IF p_amounts IS NULL OR jsonb_typeof(p_amounts) <> 'object'
     OR p_magnitudes IS NULL OR jsonb_typeof(p_magnitudes) <> 'object' THEN
    RAISE EXCEPTION 'Challenge event amounts must be JSON objects';
  END IF;
  IF p_occurred_at < now() - interval '35 days' OR p_occurred_at > now() + interval '1 minute' THEN
    RAISE EXCEPTION 'Daily Missions events must be recorded at their authoritative occurrence time';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(p_amounts) key
    WHERE key NOT IN ('hands_played','hands_won','showdowns','showdowns_won',
                      'hands_won_no_showdown','big_pots','strong_hands',
                      'chips_won','tournaments_played','friends_added')
  ) THEN
    RAISE EXCEPTION 'Unknown Daily Missions event type';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_each_text(p_amounts) item
    WHERE CASE WHEN item.value ~ '^\d+$' THEN
      item.value::numeric < 0
      OR (item.key = 'chips_won' AND item.value::numeric > 1000000000)
      OR (item.key <> 'chips_won' AND item.value::numeric > 2500)
    ELSE true END
  ) OR EXISTS (
    SELECT 1 FROM jsonb_each_text(p_magnitudes) item
    WHERE CASE WHEN item.value ~ '^\d+$' THEN
      item.value::numeric < 0 OR item.value::numeric > 1000000000
    ELSE true END
  ) THEN
    RAISE EXCEPTION 'Daily Missions event values are outside their server contract';
  END IF;

  v_daily_key := to_char((p_occurred_at AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_weekly_key := 'W' || to_char(date_trunc('week', p_occurred_at AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_monthly_key := 'M' || to_char(p_occurred_at AT TIME ZONE 'utc', 'YYYY-MM');

  INSERT INTO public.daily_challenge_progress_events (
    user_id, event_key, amounts, magnitudes, occurred_at
  ) VALUES (p_user_id, p_event_key, p_amounts, p_magnitudes, p_occurred_at)
  ON CONFLICT (user_id, event_key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN RETURN; END IF;

  PERFORM public.fn_assign_current_challenge_period(p_user_id, 'daily', v_daily_key, 5);
  PERFORM public.fn_assign_current_challenge_period(p_user_id, 'weekly', v_weekly_key, 3);
  PERFORM public.fn_assign_current_challenge_period(p_user_id, 'monthly', v_monthly_key, 2);

  RETURN QUERY
  WITH bumps AS (
    SELECT key AS ctype,
           GREATEST(COALESCE((value #>> '{}')::integer, 0), 0) AS amount
    FROM jsonb_each(p_amounts)
  ), updated AS (
    UPDATE public.user_daily_challenges u
       SET progress = LEAST(u.progress + b.amount, u.requirement_snapshot),
           completed = (u.progress + b.amount) >= u.requirement_snapshot,
           completed_at = CASE
             WHEN (u.progress + b.amount) >= u.requirement_snapshot
                  AND u.completed_at IS NULL THEN now()
             ELSE u.completed_at
           END
      FROM bumps b
     WHERE u.user_id = p_user_id
       AND u.challenge_type_snapshot = b.ctype
       AND b.amount > 0
       AND u.completed = false
       AND u.assigned_date IN (v_daily_key, v_weekly_key, v_monthly_key)
       AND (
         u.threshold_snapshot IS NULL
         OR COALESCE((p_magnitudes -> b.ctype) #>> '{}', '0')::numeric >= u.threshold_snapshot
       )
    RETURNING u.id, u.challenge_id, u.progress, u.requirement_snapshot,
              u.chip_reward_snapshot, u.diamond_reward_snapshot, u.completed
  )
  SELECT updated.id, updated.challenge_id, updated.progress,
         updated.requirement_snapshot, updated.chip_reward_snapshot,
         updated.diamond_reward_snapshot, updated.completed
  FROM updated;

  -- DIAMOND-RULINGS 3 (CLAUDE.md 10.5, horses are players): a horse has no browser, so the
  -- engine is its input device, and it presses Claim the moment a human would be shown the
  -- that fails is filed; it never breaks the progress that was just recorded.
  -- The horse claim used to run here, which keyed it to a horse DOING something: a horse that
    -- stopped playing stopped claiming, and 23 quiet horses accumulated 759 rewards worth
    -- 51,380 diamonds. It is now fn_ca_horse_claim_due, keyed to who is OWED, on a minute
    -- tick. Recording an event does not pay anybody (CLAUDE.md 10.5, 10.11).
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text := COALESCE(p_dedupe_key, '');
  before text;
BEGIN
  FOR i IN 1..4 LOOP
    before := k;
    k := regexp_replace(k, ':[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', '');
    k := regexp_replace(k, ':[0-9a-fA-F]{32}$', '');
    k := regexp_replace(k, ':[0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?$', '');
    EXIT WHEN k = before;
  END LOOP;

  IF k = '' THEN
    k := COALESCE(p_classification, 'unknown');
  END IF;

  RETURN k
      || '|' || COALESCE(p_layer, 'unknown')
      || '|' || COALESCE(p_club_id::text, '-')
      || '|' || COALESCE(p_union_id::text, '-');
END $function$;
CREATE OR REPLACE FUNCTION public.fn_fleet_hash(p_profile_id text, p_salt text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bytes bytea := convert_to(p_salt || ':' || p_profile_id, 'UTF8');
  v_h bigint := 2166136261;
  v_i int;
BEGIN
  FOR v_i IN 0 .. length(v_bytes) - 1 LOOP
    v_h := v_h # get_byte(v_bytes, v_i);
    v_h := (v_h * 16777619) % 4294967296;
  END LOOP;
  RETURN v_h;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_assign_current_challenge_period(p_user_id uuid, p_tier text, p_period_key text, p_count integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);
  PERFORM public.fn_assign_current_challenge_period_serialized_body(
    p_user_id,
    p_tier,
    p_period_key,
    p_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_accounting_next_invoice_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE y int:=extract(year FROM now() AT TIME ZONE 'America/Chicago'); n bigint;
BEGIN
 INSERT INTO public.accounting_invoice_counters(year,next_number) VALUES(y,2)
 ON CONFLICT(year) DO UPDATE SET next_number=accounting_invoice_counters.next_number+1
 RETURNING next_number-1 INTO n;
 RETURN 'CA-'||y::text||'-'||lpad(n::text,8,'0');
END $function$;
CREATE OR REPLACE FUNCTION public.fn_accounting_party_users(p_kind text, p_id uuid)
 RETURNS TABLE(user_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT DISTINCT p.id FROM public.profiles p WHERE p.id IN (
  SELECT p_id WHERE p_kind IN('agent','player')
  UNION SELECT c.owner_id FROM public.clubs c WHERE p_kind='club' AND c.id=p_id
  UNION SELECT m.user_id FROM public.club_members m WHERE p_kind='club' AND m.club_id=p_id
   AND m.role IN('owner','co_owner','admin') AND COALESCE(m.status,'active') IN('active','approved')
  UNION SELECT u.owner_id FROM public.unions u WHERE p_kind='union' AND u.id=p_id
  UNION SELECT a.user_id FROM public.union_admins a WHERE p_kind='union' AND a.union_id=p_id
   AND public.fn_is_union_overseer(p_id,a.user_id)
 );
$function$;
CREATE OR REPLACE FUNCTION public.apply_rakeback_player_stats(p_rake_record_id uuid, p_user_id uuid, p_club_id uuid, p_hands integer, p_rake numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted integer;
BEGIN
  IF p_rake_record_id IS NULL OR p_user_id IS NULL OR p_club_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.rakeback_stats_applied (rake_record_id, user_id, hands, rake)
  VALUES (p_rake_record_id, p_user_id, p_hands, p_rake)
  ON CONFLICT (rake_record_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    RETURN false;
  END IF;

  INSERT INTO public.player_stats (
    user_id, club_id, hands_played, total_rake,
    total_winnings, total_losses, vpip, pfr, tournaments_played, tournaments_won
  ) VALUES (
    p_user_id, p_club_id, COALESCE(p_hands, 0), COALESCE(p_rake, 0),
    0, 0, 0, 0, 0, 0
  )
  ON CONFLICT (user_id, club_id) DO UPDATE SET
    hands_played = public.player_stats.hands_played + EXCLUDED.hands_played,
    total_rake   = ROUND((public.player_stats.total_rake + EXCLUDED.total_rake) * 100) / 100,
    updated_at   = NOW();

  RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_accounting_terms_at(p_entity_type text, p_entity_key text, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE h public.accounting_agreement_history%ROWTYPE;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'accounting_terms_not_authorised' USING ERRCODE='42501'; END IF;
 IF p_entity_type NOT IN('agents','club_members','union_clubs') OR p_entity_type IS NULL
    OR p_entity_key IS NULL OR p_entity_key='' OR p_at IS NULL OR NOT isfinite(p_at) OR p_at>transaction_timestamp()
 THEN RAISE EXCEPTION 'invalid_accounting_terms_request' USING ERRCODE='22023'; END IF;
 SELECT * INTO h FROM public.accounting_agreement_history
  WHERE entity_type=p_entity_type AND entity_key=p_entity_key AND observed_at<=p_at
  ORDER BY observed_at DESC,id DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_terms_not_observed' USING ERRCODE='55000'; END IF;
 RETURN jsonb_build_object('history_id',h.id,'observed_at',h.observed_at,'terms',h.after_terms);
END $function$;
CREATE OR REPLACE FUNCTION public.fn_accounting_agent_terms_at(p_club_id uuid, p_user_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE identities text[]; identity_key text; v jsonb; result jsonb; active_count int:=0;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'accounting_terms_not_authorised' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_user_id IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR p_at>transaction_timestamp()
 THEN RAISE EXCEPTION 'invalid_accounting_terms_request' USING ERRCODE='22023'; END IF;
 -- Find candidate identities from history, then resolve each identity at the
 -- earning time. A later move/deletion closes the old identity; filtering the
 -- history by club before selecting its latest event would resurrect that row.
 SELECT array_agg(DISTINCT entity_key) INTO identities FROM public.accounting_agreement_history
  WHERE entity_type='agents' AND club_id=p_club_id AND subject_user_id=p_user_id AND observed_at<=p_at;
 IF identities IS NULL THEN RAISE EXCEPTION 'accounting_terms_not_observed' USING ERRCODE='55000'; END IF;
 FOREACH identity_key IN ARRAY identities LOOP
  v:=public.fn_accounting_terms_at('agents',identity_key,p_at);
  IF v->'terms'->>'club_id'=p_club_id::text AND v->'terms'->>'user_id'=p_user_id::text
     AND v->'terms'->>'status'='active' THEN
   active_count:=active_count+1; result:=v;
  END IF;
 END LOOP;
 IF active_count=0 THEN RAISE EXCEPTION 'accounting_terms_not_active' USING ERRCODE='55000'; END IF;
 IF active_count>1 THEN RAISE EXCEPTION 'accounting_terms_ambiguous' USING ERRCODE='55000'; END IF;
 RETURN result;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_update_conversation_last_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    UPDATE social_conversations
    SET 
        last_message_at = NEW.created_at,
        last_message_preview = LEFT(NEW.content, 100),
        updated_at = now()
    WHERE id = NEW.conversation_id;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_notify_friend_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    sender_name TEXT;
BEGIN
    -- Skip if suppressed by auto-connect trigger
    IF current_setting('app.suppress_friend_notifications', true) = 'true' THEN
        RETURN NEW;
    END IF;

    IF NEW.status = 'pending' THEN
        SELECT COALESCE(full_name, username, 'Someone') INTO sender_name
        FROM public.profiles WHERE id = NEW.user_id;
        
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            NEW.friend_id,
            NEW.user_id,
            'friend_request',
            sender_name,
            'sent you a friend request',
            jsonb_build_object(
                'sender_id', NEW.user_id,
                'friendship_id', NEW.id,
                'sender_name', sender_name
            )
        );
    ELSIF NEW.status = 'accepted' THEN
        SELECT COALESCE(full_name, username, 'Someone') INTO sender_name
        FROM public.profiles WHERE id = NEW.user_id;
        
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            NEW.friend_id,
            NEW.user_id,
            'friend_accept',
            sender_name,
            'accepted your friend request',
            jsonb_build_object(
                'sender_id', NEW.user_id,
                'friendship_id', NEW.id,
                'sender_name', sender_name
            )
        );
    END IF;
    
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    next_player_num BIGINT;
    generated_username TEXT;
    resolved_full_name TEXT;
    v_first_name TEXT;
    v_last_name TEXT;
    v_prev_diamonds INTEGER;
    v_now_diamonds INTEGER;
    v_grant JSONB;
    v_grant_class TEXT;
BEGIN
    resolved_full_name := COALESCE(
        NULLIF(TRIM(COALESCE(NEW.raw_user_meta_data->>'full_name', '')), ''),
        NULLIF(TRIM(COALESCE(NEW.raw_user_meta_data->>'name', '')), ''),
        NULLIF(TRIM(
            COALESCE(NEW.raw_user_meta_data->>'given_name', '') || ' ' ||
            COALESCE(NEW.raw_user_meta_data->>'family_name', '')
        ), ''),
        ''
    );

    v_first_name := COALESCE(NEW.raw_user_meta_data->>'first_name', '');
    v_last_name  := COALESCE(NEW.raw_user_meta_data->>'last_name',  '');

    IF v_first_name = '' AND v_last_name = '' AND resolved_full_name <> '' THEN
        v_first_name := split_part(resolved_full_name, ' ', 1);
        v_last_name  := CASE
            WHEN position(' ' in resolved_full_name) > 0
            THEN substring(resolved_full_name from position(' ' in resolved_full_name) + 1)
            ELSE ''
        END;
    END IF;

    generated_username := COALESCE(
        NULLIF(NEW.raw_user_meta_data->>'poker_alias', ''),
        NULLIF(REGEXP_REPLACE(resolved_full_name, '[^a-zA-Z0-9]', '', 'g'), ''),
        SPLIT_PART(COALESCE(NEW.email, ''), '@', 1),
        'Player' || FLOOR(RANDOM() * 10000)::TEXT
    );
    generated_username := LEFT(generated_username, 15);

    -- If the derived username is reserved, fall back to Player<N> so the row
    -- never lands as @admin / @support / @smarterpoker / etc.
    IF public.is_reserved_username(generated_username) THEN
        generated_username := 'Player' || FLOOR(RANDOM() * 100000)::TEXT;
    END IF;

    SELECT nextval('public.profiles_player_number_seq') INTO next_player_num;

    -- ZERO-DRIFT: remember the pre-upsert balance so the signup grant can
    -- journal itself exactly when it changes supply, and never otherwise.
    SELECT diamonds INTO v_prev_diamonds FROM public.profiles WHERE id = NEW.id;

    INSERT INTO public.profiles (
        id, full_name, first_name, last_name, email, username, avatar_url,
        player_number, streak_count, diamonds, diamond_balance, diamond_multiplier, skill_tier,
        access_tier, is_vip, vip_tier, vip_expires_at,
        created_at, updated_at, last_login, last_active, is_online
    ) VALUES (
        NEW.id, resolved_full_name, v_first_name, v_last_name,
        COALESCE(NEW.email, ''), generated_username,
        COALESCE(NEW.raw_user_meta_data->>'avatar_url',
                 NEW.raw_user_meta_data->>'picture', ''),
        next_player_num, 0, 0, 0, 1.0, 'Newcomer',
        CASE
            WHEN NEW.raw_user_meta_data->>'state' IN ('WA','ID','MI','NV','CA') THEN 'Restricted_Tier'
            ELSE 'Full_Access'
        END,
        true, 'monthly', NOW() + INTERVAL '30 days',
        NOW(), NOW(), NOW(), NOW(), true
    )
    ON CONFLICT (id) DO UPDATE SET
        last_login    = NOW(),
        last_active   = NOW(),
        is_online     = true,
        full_name     = CASE WHEN COALESCE(profiles.full_name, '') = '' THEN EXCLUDED.full_name ELSE profiles.full_name END,
        first_name    = CASE WHEN COALESCE(profiles.first_name, '') = '' THEN EXCLUDED.first_name ELSE profiles.first_name END,
        last_name     = CASE WHEN COALESCE(profiles.last_name, '') = '' THEN EXCLUDED.last_name ELSE profiles.last_name END,
        avatar_url    = CASE WHEN COALESCE(profiles.avatar_url, '') = '' THEN EXCLUDED.avatar_url ELSE profiles.avatar_url END,
        player_number = COALESCE(profiles.player_number, EXCLUDED.player_number),
        is_vip        = CASE WHEN profiles.is_vip IS NULL OR profiles.is_vip = false THEN true ELSE profiles.is_vip END,
        vip_tier      = CASE WHEN profiles.vip_tier IS NULL THEN 'monthly' ELSE profiles.vip_tier END,
        vip_expires_at= CASE WHEN profiles.vip_expires_at IS NULL THEN NOW() + INTERVAL '30 days' ELSE profiles.vip_expires_at END;

    SELECT diamonds INTO v_now_diamonds FROM public.profiles WHERE id = NEW.id;

    -- THE SIGNUP GRANT IS ISSUED BY THE MINT (2026-09-08, DIAMOND-RULINGS 17, roadmap 1.3).
    -- The profile is born holding 0 and the 500 arrive through fn_ca_mint under the op id
    -- signup:<id>, which fills the balance, journals (class promotional, reference signup:<id>)
    -- and registers in one call, and replays as a no-op. A profile that already carries a
    -- register row (seed: from the older born-with-balance door, or signup:) or a signup
    -- journal row is not granted again, so a re-auth of an existing player mints nothing.
    -- A refusal by the Mint (the diamond_issuance freeze) is filed as DR2:signup_grant_refused;
    -- ensure-profile.js re-asks the Mint for the same op id on the next login, so the live path
    -- restarts from its own record and no back-pay job exists (CLAUDE.md 10.12).
    IF NOT EXISTS (SELECT 1 FROM public.ca_mint_ledger m
                    WHERE m.op_id IN ('signup:' || NEW.id::text, 'seed:' || NEW.id::text))
       AND NOT EXISTS (SELECT 1 FROM public.diamond_transactions t
                        WHERE t.user_id = NEW.id
                          AND (t.type = 'signup_bonus'
                               OR t.reference_id = 'signup:' || NEW.id::text)) THEN
        BEGIN
            v_grant := public.fn_ca_mint('diamonds', 'player', NEW.id, 500, 'signup grant',
                                         'signup:' || NEW.id::text, 'promotional');
            IF COALESCE((v_grant ->> 'ok')::boolean, false) IS NOT TRUE
               AND COALESCE((v_grant ->> 'replayed')::boolean, false) IS NOT TRUE THEN
                PERFORM public.fn_ca_diamond_incident(
                    'DR2:signup_grant_refused', 'warning', NEW.id, 500, 'handle_new_user',
                    jsonb_build_object('result', v_grant, 'prev_diamonds', v_prev_diamonds,
                                       'now_diamonds', v_now_diamonds));
            END IF;
        EXCEPTION WHEN OTHERS THEN
            PERFORM public.fn_ca_diamond_incident(
                'DR2:signup_grant_not_journaled', 'critical', NEW.id, 500, 'handle_new_user',
                jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM,
                                   'prev_diamonds', v_prev_diamonds,
                                   'now_diamonds', v_now_diamonds));
        END;
    END IF;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    -- Defensive: never block auth.users INSERT, but DO leave a forensic trail.
    BEGIN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg, raw_meta)
      VALUES (NEW.id, NEW.email, 'handle_new_user', SQLSTATE, SQLERRM, NEW.raw_user_meta_data);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_notify_agent_on_cashout()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_player_name TEXT;
    v_club_name TEXT;
BEGIN
    -- Get player name
    SELECT display_name INTO v_player_name
    FROM profiles
    WHERE id = NEW.player_id;

    -- Get club name
    SELECT name INTO v_club_name
    FROM clubs
    WHERE id = NEW.club_id;

    -- Create notification for agent
    INSERT INTO notifications (user_id, type, title, message, data, created_at)
    VALUES (
        NEW.agent_id,
        'cashout_request',
        'Cashout Request',
        v_player_name || ' requested a cashout of ' || NEW.amount || ' chips in ' || v_club_name,
        jsonb_build_object(
            'cashout_id', NEW.id,
            'player_id', NEW.player_id,
            'club_id', NEW.club_id,
            'amount', NEW.amount
        ),
        NOW()
    );

    -- Create a club message notification for agent
    INSERT INTO messages (
        conversation_id,
        sender_id,
        receiver_id,
        content,
        is_read,
        created_at
    )
    SELECT 
        c.id,
        NEW.player_id,
        NEW.agent_id,
        'Cashout Request: ' || NEW.amount || ' Chips. Please Review In Your Agent Dashboard.',
        FALSE,
        NOW()
    FROM conversations c
    WHERE c.participant_ids @> ARRAY[NEW.player_id, NEW.agent_id]
      AND c.club_id = NEW.club_id
      AND c.category = 'club'
    LIMIT 1;

    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.initialize_user_diamonds()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    /* 2026-09-07: this wrote (100, 100) into a MIRROR of profiles.diamonds.
       The canonical store defaults to 0 and no profile in fourteen days held a
       canonical 100, so the number was never a balance - it was a mirror
       disagreeing with the thing it mirrors. It reads the canonical store now;
       at signup there is usually no profile row yet, which reads 0, and
       trg_diamond_side_tables_follow_profiles writes the true figure the
       moment the profile is created. */
    INSERT INTO public.user_diamonds (user_id, balance, lifetime_earned)
    VALUES (NEW.id,
            COALESCE((SELECT GREATEST(COALESCE(p.diamonds, 0), 0)
                        FROM public.profiles p WHERE p.id = NEW.id), 0),
            0)
    ON CONFLICT (user_id) DO NOTHING;

    INSERT INTO public.user_daily_streaks (user_id)
    VALUES (NEW.id)
    ON CONFLICT (user_id) DO NOTHING;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'initialize_user_diamonds', SQLSTATE, SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_agent_wallet_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$ BEGIN IF NEW.agent_wallet_balance IS DISTINCT FROM OLD.agent_wallet_balance THEN NEW.business_balance := NEW.agent_wallet_balance; ELSIF NEW.business_balance IS DISTINCT FROM OLD.business_balance THEN NEW.agent_wallet_balance := NEW.business_balance; END IF; IF NEW.player_wallet_balance IS DISTINCT FROM OLD.player_wallet_balance THEN NEW.player_balance := NEW.player_wallet_balance; ELSIF NEW.player_balance IS DISTINCT FROM OLD.player_balance THEN NEW.player_wallet_balance := NEW.player_balance; END IF; IF NEW.promo_wallet_balance IS DISTINCT FROM OLD.promo_wallet_balance THEN NEW.promo_balance := NEW.promo_wallet_balance; ELSIF NEW.promo_balance IS DISTINCT FROM OLD.promo_balance THEN NEW.promo_wallet_balance := NEW.promo_balance; END IF; RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.fn_block_message_field_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Service role is the maintenance path and bypasses field locks.
  IF auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF NEW.sender_id IS DISTINCT FROM OLD.sender_id THEN
    RAISE EXCEPTION 'sender_id cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.conversation_id IS DISTINCT FROM OLD.conversation_id THEN
    RAISE EXCEPTION 'conversation_id cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'created_at cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user_v2_create_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.wallets (user_id, wallet_type, balance, locked_balance)
  VALUES (NEW.id, 'PLAYER', 0, 0)
  ON CONFLICT (user_id, wallet_type) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
    VALUES (NEW.id, NEW.email, 'handle_new_user_v2_create_wallet', SQLSTATE, SQLERRM);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_enforce_anti_farming_caps()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$                                                                                 
 DECLARE                                                                                       
   v_recipient uuid;                                                                           
   v_check     jsonb;                                                                          
   v_kingfish  uuid := '47965354-0e56-43ef-931c-ddaab82af765';                                 
 BEGIN                                                                                         
   -- Only enforce on outbound (debit) rows                                                    
   IF NEW.amount IS NULL OR NEW.amount >= 0 THEN                                               
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- Only on user→user diamond movement channels.                                             
   -- COALESCE coerces NULL to '' so NULL columns evaluate to FALSE (not NULL)                 
   -- in the IN check. Critical because deduct_diamonds writes source=NULL on                  
   -- every non-gift call (game_cost, course_purchase, etc.) and we need those                 
   -- to fall through to the early RETURN NEW.                                                 
   IF NOT (                                                                                    
        COALESCE(NEW.transaction_type, '') IN ('live_gift_sent','diamond_gift_sent')           
     OR COALESCE(NEW.source, '') IN ('stream_gift','wallet_transfer','wallet_diamond_transfer')
   ) THEN                                                                                      
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- KINGFISH sender bypass                                                                   
   IF NEW.user_id = v_kingfish THEN                                                            
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- Recipient_id required in metadata for enforced channels                                  
   v_recipient := NULLIF(NEW.metadata->>'recipient_id', '')::uuid;                             
   IF v_recipient IS NULL THEN                                                                 
     RAISE EXCEPTION 'Anti-farming: recipient_id missing from metadata for % transaction',     
       COALESCE(NEW.transaction_type, NEW.source)                                              
       USING ERRCODE = 'check_violation';                                                      
   END IF;                                                                                     
                                                                                               
   -- Delegate to shared cap function                                                          
   v_check := public.fn_check_anti_farming_gift_cap(NEW.user_id, v_recipient, ABS(NEW.amount));
                                                                                               
   IF NOT (v_check->>'allowed')::boolean THEN                                                  
     RAISE EXCEPTION 'Anti-farming: %', v_check->>'reason'                                     
       USING ERRCODE = 'check_violation', DETAIL = v_check::text;                              
   END IF;                                                                                     
                                                                                               
   RETURN NEW;                                                                                 
 END;                                                                                          
 $function$;
CREATE OR REPLACE FUNCTION public.trg_fn_live_invite_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_recipient_id uuid;
    v_sender_name text;
BEGIN
    -- Only trigger for [LIVE_INVITE] messages
    IF NEW.content IS NOT NULL AND NEW.content LIKE '[LIVE_INVITE]%' THEN
        -- Find the recipient (the other participant in the direct conversation)
        SELECT user_id INTO v_recipient_id
        FROM public.social_conversation_participants
        WHERE conversation_id = NEW.conversation_id AND user_id != NEW.sender_id
        LIMIT 1;

        -- Get the sender's name
        SELECT COALESCE(full_name, username, 'Someone') INTO v_sender_name
        FROM public.profiles
        WHERE id = NEW.sender_id;

        IF v_recipient_id IS NOT NULL THEN
            -- Insert the notification record
            INSERT INTO public.notifications (
                user_id,
                type,
                title,
                message,
                data,
                read
            ) VALUES (
                v_recipient_id,
                'live_invite',
                'Live Stream Invite',
                v_sender_name || ' invited you to join their live stream as a guest co-host.',
                jsonb_build_object(
                    'conversation_id', NEW.conversation_id,
                    'message_id', NEW.id,
                    'content', NEW.content,
                    'sender_name', v_sender_name
                ),
                false
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_notification_read_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_read boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_read := COALESCE(NEW.read_at IS NOT NULL, false) OR COALESCE(NEW.is_read, false) OR COALESCE(NEW.read, false);
  ELSE
    IF (NEW.read_at IS DISTINCT FROM OLD.read_at) THEN v_read := NEW.read_at IS NOT NULL;
    ELSIF (NEW.is_read IS DISTINCT FROM OLD.is_read) THEN v_read := COALESCE(NEW.is_read, false);
    ELSIF (NEW.read IS DISTINCT FROM OLD.read) THEN v_read := COALESCE(NEW.read, false);
    ELSE v_read := COALESCE(NEW.read_at IS NOT NULL, false) OR COALESCE(NEW.is_read, false) OR COALESCE(NEW.read, false);
    END IF;
  END IF;
  NEW.is_read := v_read; NEW.read := v_read;
  IF v_read THEN NEW.read_at := COALESCE(NEW.read_at, now()); ELSE NEW.read_at := NULL; END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.fn_mirror_notification_to_push_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE notice public.notifications%ROWTYPE; receipt record; existing public.push_outbox%ROWTYPE;
 v_tag text;v_pending int;state text:='pending';reason text;
 c_max_pending CONSTANT int:=20;c_max_age CONSTANT interval:=interval '30 minutes';
BEGIN
 -- Delivery rows are inserted AFTER their notification. Wait until the whole
 -- transaction is ready to commit before granting the canonical exception.
 IF TG_NAME<>'trg_accounting_push_after_delivery' AND NEW.type='accounting_invoice' THEN RETURN NEW; END IF;
 SELECT * INTO notice FROM public.notifications WHERE id=NEW.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT d.invoice_id,d.recipient_id,d.delivery_mode,m.conversation_id,m.message_type,m.media_metadata,
  i.invoice_number,i.net_amount INTO receipt
 FROM public.accounting_invoice_deliveries d JOIN public.settlement_invoices i ON i.id=d.invoice_id
 JOIN public.social_messages m ON m.id=d.message_id WHERE d.notification_id=notice.id;
 IF FOUND THEN
  -- A real receipt foreign key, exact recipient and issued document are
  -- required. Arbitrary accounting-looking JSON cannot bypass normal caps.
  IF receipt.recipient_id IS DISTINCT FROM notice.user_id
   OR notice.data->>'invoice_id' IS DISTINCT FROM receipt.invoice_id::text
   OR notice.data->>'invoice_number' IS DISTINCT FROM receipt.invoice_number
   OR notice.data->'amount' IS DISTINCT FROM to_jsonb(receipt.net_amount)
   OR receipt.message_type IS DISTINCT FROM 'invoice'
   OR receipt.media_metadata->>'invoice_id' IS DISTINCT FROM receipt.invoice_id::text
   OR COALESCE(notice.data->>'conversation_id',notice.data->>'conversationId') IS DISTINCT FROM receipt.conversation_id::text
   OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=receipt.conversation_id AND p.user_id=notice.user_id)
  THEN RAISE EXCEPTION 'accounting_push_receipt_provenance_invalid' USING ERRCODE='23514'; END IF;
  IF receipt.delivery_mode='weekly_detail' OR notice.type='accounting_invoice_detail' THEN
   state:='skipped';reason:='accounting_archived_detail';
  ELSIF notice.type IS DISTINCT FROM 'accounting_invoice' THEN
   RAISE EXCEPTION 'accounting_push_notification_type_invalid' USING ERRCODE='23514';
  ELSIF notice.data->>'_push' IS NOT NULL THEN
   state:='skipped';reason:='accounting_source_suppressed:'||(notice.data->>'_push');
  ELSIF notice.created_at<now()-c_max_age THEN
   state:='skipped';reason:='accounting_historical_notification';
  END IF;
  SELECT * INTO existing FROM public.push_outbox WHERE accounting_notification_id=notice.id;
  IF FOUND THEN
   IF existing.recipient_user_id IS DISTINCT FROM notice.user_id OR existing.related_entity_id IS DISTINCT FROM notice.id
    OR existing.event IS DISTINCT FROM 'accounting_invoice' THEN RAISE EXCEPTION 'accounting_push_receipt_collision' USING ERRCODE='23514'; END IF;
   RETURN NEW;
  END IF;
  -- No exception swallowing here. The invoice, message, notification, linked
  -- transfer and durable outbox receipt commit together or all roll back.
  -- Normal dispatcher preference, quiet-hour, device and consent gates remain.
  INSERT INTO public.push_outbox(recipient_user_id,title,body,url,event,tag,status,failure_reason,related_entity_id,accounting_notification_id)
  VALUES(notice.user_id,left(notice.title,120),left(COALESCE(notice.message,notice.title),500),
   COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub'),
   'accounting_invoice','accounting_invoice:'||receipt.conversation_id::text,state,reason,notice.id,notice.id);
  RETURN NEW;
 END IF;

 -- A reserved accounting label with no actual delivery link is invalid,
 -- including a caller that forces this constraint before the link is written.
 -- Fail the transaction rather than silently dropping its accounting push.
 IF notice.type='accounting_invoice' THEN
  RAISE EXCEPTION 'accounting_push_delivery_link_missing' USING ERRCODE='23514';
 END IF;
 IF notice.type='accounting_invoice_detail' THEN RETURN NEW; END IF;
 -- Existing non-accounting notification policy stays intact.
 IF notice.data IS NOT NULL AND notice.data->>'_push' IS NOT NULL THEN RETURN NEW; END IF;
 IF notice.user_id IS NULL OR notice.title IS NULL OR btrim(notice.title)='' THEN RETURN NEW; END IF;
 IF notice.created_at IS NOT NULL AND notice.created_at<now()-c_max_age THEN RETURN NEW; END IF;
 IF notice.type IN('waitlist_seat_open','waitlist_offer_expired','seat_available','waitlist_ready','table_ready') THEN
  v_tag:='seat_offer:'||COALESCE(NULLIF(btrim(COALESCE(notice.data->>'table_id','')),''),notice.id::text);
 ELSIF notice.type IN('system','daily_challenge','venue_alert','bonus','vip','live','poker_news','diamond','achievement') THEN
  v_tag:=notice.type||':'||notice.user_id::text;
 ELSE
  v_tag:=notice.type||':'||COALESCE(NULLIF(btrim(COALESCE(notice.data->>'conversationId','')),''),NULLIF(btrim(COALESCE(notice.data->>'conversation_id','')),''),notice.actor_id::text,notice.id::text);
 END IF;
 BEGIN
  SELECT count(*) INTO v_pending FROM public.push_outbox WHERE recipient_user_id=notice.user_id AND status IN('pending','processing');
  IF v_pending>=c_max_pending THEN RETURN NEW; END IF;
  INSERT INTO public.push_outbox(recipient_user_id,title,body,url,event,tag,status,related_entity_id)
   VALUES(notice.user_id,left(notice.title,120),left(COALESCE(notice.message,notice.title),500),COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub'),notice.type,v_tag,'pending',notice.id);
 EXCEPTION WHEN OTHERS THEN RAISE WARNING 'mirror_notification_to_push_outbox failed for notification %: %',notice.id,SQLERRM;
 END;
 RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_enforce_agent_commission_bounds()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_union uuid; v_min numeric; v_max numeric; v_rate numeric;
BEGIN
  IF NEW.commission_rate IS NULL THEN RETURN NEW; END IF;

  -- THE RATE IS NOT CHANGING, SO THERE IS NOTHING TO JUDGE.
  -- This trigger is BEFORE UPDATE OF commission_rate, and Postgres fires that
  -- for any UPDATE whose SET list names the column, identical value or not.
  -- Without this, an unrelated write - a status change, a demotion, a parent
  -- reassignment - re-validates a rate nobody touched against a band the row
  -- may never have satisfied, and raises P0001 into a caller that has no idea
  -- why. It is how demoting a co-owner to player failed outright in any club
  -- under a union with a non-zero minimum.
  IF TG_OP = 'UPDATE' AND NEW.commission_rate IS NOT DISTINCT FROM OLD.commission_rate THEN
    RETURN NEW;
  END IF;

  -- A co-owner and an admin earn nothing, by Dan's rule and by
  -- trg_agents_staff_earn_no_rakeback, which sets both of their rates to zero.
  -- The union band says what an EARNING agent may be paid, so it has nothing to
  -- say about a row that is forbidden to earn.
  IF NEW.commission_rate = 0 AND EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = NEW.club_id
       AND cm.user_id = NEW.user_id
       AND cm.role IN ('co_owner', 'admin')
  ) THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(uc.union_id, c.union_id) INTO v_union
    FROM clubs c LEFT JOIN union_clubs uc ON uc.club_id = c.id
   WHERE c.id = NEW.club_id LIMIT 1;

  IF v_union IS NULL THEN RETURN NEW; END IF;   -- standalone club: no policy

  v_min := public.fn_union_setting(v_union, 'min_agent_commission', 0);
  v_max := public.fn_union_setting(v_union, 'max_agent_commission', 1);

  -- Rates may be expressed as a fraction (0.5) or whole percent (50).
  v_rate := CASE WHEN NEW.commission_rate > 1 THEN NEW.commission_rate / 100.0
                 ELSE NEW.commission_rate END;

  IF v_rate < v_min OR v_rate > v_max THEN
    RAISE EXCEPTION 'agent commission % is outside the union policy band (% .. %)',
      v_rate, v_min, v_max
      USING HINT = 'Change unions.settings.min_agent_commission / max_agent_commission to widen the band.';
  END IF;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_notification_fill_action_url()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NULLIF(btrim(COALESCE(NEW.link, '')), '') IS NULL
       AND NULLIF(btrim(COALESCE(NEW.action_url, '')), '') IS NULL THEN
        BEGIN
            NEW.action_url := public.fn_notification_action_url(NEW.type, NEW.data, NEW.metadata);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'fn_notification_fill_action_url failed for type %: %', NEW.type, SQLERRM;
        END;
    END IF;
    RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_log_jackpot_payout_without_hand()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.hand_id IS NULL THEN
    INSERT INTO public.bbj_hand_evidence_log (kind, payout_id, table_id, hand_number, detail)
    VALUES ('payout_without_hand', NEW.id, NEW.table_id, NEW.hand_number,
            jsonb_build_object('total_amount', NEW.total_amount,
                               'note', 'hand_history row was not found when the payout was written'));
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_agent_wallet_direct_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_user in ('authenticated','anon') then
    if tg_op='INSERT' and (
      coalesce(new.agent_wallet_balance,0)<>0 or coalesce(new.business_balance,0)<>0 or
      coalesce(new.player_wallet_balance,0)<>0 or coalesce(new.player_balance,0)<>0 or
      coalesce(new.promo_wallet_balance,0)<>0 or coalesce(new.promo_balance,0)<>0 or
      coalesce(new.credit_limit,0)<>0 or coalesce(new.credit_used,0)<>0 or
      coalesce(new.commission_rate,0)<>0 or coalesce(new.player_rakeback_rate,0)<>0
    ) then
      raise exception 'Agent financial accounts may only be created through authorized operations';
    elsif tg_op='UPDATE' and (
      new.agent_wallet_balance is distinct from old.agent_wallet_balance or
      new.business_balance is distinct from old.business_balance or
      new.player_wallet_balance is distinct from old.player_wallet_balance or
      new.player_balance is distinct from old.player_balance or
      new.promo_wallet_balance is distinct from old.promo_wallet_balance or
      new.promo_balance is distinct from old.promo_balance or
      new.credit_limit is distinct from old.credit_limit or
      new.credit_used is distinct from old.credit_used or
      new.commission_rate is distinct from old.commission_rate or
      new.player_rakeback_rate is distinct from old.player_rakeback_rate
    ) then
      raise exception 'Agent financial accounts may only change through authorized operations';
    end if;
  end if;
  return new;
end
$function$;
CREATE OR REPLACE FUNCTION public.fn_snapshot_daily_challenge_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_replacement_tier text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT c.name, c.description, c.challenge_type, c.tier, c.requirement,
           c.threshold, c.chip_reward, c.diamond_reward
      INTO NEW.challenge_name_snapshot, NEW.challenge_description_snapshot,
           NEW.challenge_type_snapshot, NEW.tier_snapshot, NEW.requirement_snapshot,
           NEW.threshold_snapshot, NEW.chip_reward_snapshot, NEW.diamond_reward_snapshot
      FROM public.daily_challenge_catalog c
     WHERE c.id = NEW.challenge_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unknown challenge % - cannot snapshot its contract', NEW.challenge_id;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.challenge_id IS DISTINCT FROM OLD.challenge_id THEN
    IF current_setting('app.daily_challenge_reroll', true) IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'Assigned daily challenges can only be replaced by the reroll contract';
    END IF;
    IF OLD.completed OR OLD.claimed THEN
      RAISE EXCEPTION 'Completed daily challenge contracts cannot be replaced';
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.assigned_date IS DISTINCT FROM OLD.assigned_date
       OR NEW.id IS DISTINCT FROM OLD.id
    THEN
      RAISE EXCEPTION 'A reroll cannot move a daily challenge contract';
    END IF;

    SELECT c.name, c.description, c.challenge_type, c.tier, c.requirement,
           c.threshold, c.chip_reward, c.diamond_reward
      INTO NEW.challenge_name_snapshot, NEW.challenge_description_snapshot,
           NEW.challenge_type_snapshot, v_replacement_tier, NEW.requirement_snapshot,
           NEW.threshold_snapshot, NEW.chip_reward_snapshot, NEW.diamond_reward_snapshot
      FROM public.daily_challenge_catalog c
     WHERE c.id = NEW.challenge_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown replacement challenge %', NEW.challenge_id; END IF;
    IF v_replacement_tier IS DISTINCT FROM OLD.tier_snapshot THEN
      RAISE EXCEPTION 'A reroll cannot change mission cycle';
    END IF;
    NEW.tier_snapshot := v_replacement_tier;
    RETURN NEW;
  END IF;

  IF NEW.challenge_name_snapshot IS DISTINCT FROM OLD.challenge_name_snapshot
     OR NEW.challenge_description_snapshot IS DISTINCT FROM OLD.challenge_description_snapshot
     OR NEW.challenge_type_snapshot IS DISTINCT FROM OLD.challenge_type_snapshot
     OR NEW.tier_snapshot IS DISTINCT FROM OLD.tier_snapshot
     OR NEW.requirement_snapshot IS DISTINCT FROM OLD.requirement_snapshot
     OR NEW.threshold_snapshot IS DISTINCT FROM OLD.threshold_snapshot
     OR NEW.chip_reward_snapshot IS DISTINCT FROM OLD.chip_reward_snapshot
     OR NEW.diamond_reward_snapshot IS DISTINCT FROM OLD.diamond_reward_snapshot
  THEN
    RAISE EXCEPTION 'Assigned daily challenge contracts are immutable';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_bbj_ledger_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.bbj_ledger_deletions (source_table, row_data)
  VALUES (TG_TABLE_NAME, to_jsonb(OLD));
  -- One alert per statement would flood on a cascade; dedupe to one per table per hour.
  IF NOT EXISTS (
    SELECT 1 FROM public.financial_alerts
     WHERE source = 'bbj_ledger_delete_guard'
       AND context->>'table' = TG_TABLE_NAME
       AND created_at > now() - interval '1 hour') THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('critical', 'bbj_ledger_delete_guard',
      'A BBJ ledger row was deleted. The 2026-08 drift incident was exactly this. Review bbj_ledger_deletions.',
      jsonb_build_object('table', TG_TABLE_NAME, 'role', current_user,
                         'app', current_setting('application_name', true)));
  END IF;
  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_agents_staff_earn_no_rakeback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = NEW.club_id AND cm.user_id = NEW.user_id
       AND cm.role IN ('co_owner', 'admin')
  ) THEN
    -- The row survives: it is also the agent wallet. Only the rate goes to zero.
    NEW.commission_rate      := 0;
    NEW.player_rakeback_rate := 0;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_daily_missions_friend_accepted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status = 'accepted'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'accepted') THEN
    IF NEW.user_id = NEW.friend_id THEN
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
    ELSIF NEW.user_id < NEW.friend_id THEN
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
      PERFORM public.fn_lock_daily_mission_user(NEW.friend_id);
    ELSE
      PERFORM public.fn_lock_daily_mission_user(NEW.friend_id);
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
    END IF;

    BEGIN
      PERFORM public.enqueue_daily_challenge_event(
        NEW.user_id,
        'friendship:' || NEW.id::text,
        '{"friends_added":1}'::jsonb,
        '{}'::jsonb,
        now()
      );
      PERFORM public.enqueue_daily_challenge_event(
        NEW.friend_id,
        'friendship:' || NEW.id::text,
        '{"friends_added":1}'::jsonb,
        '{}'::jsonb,
        now()
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Missions friendship event % could not be queued: %',
        NEW.id,
        SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_daily_missions_claimed_milestone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.claimed AND NOT OLD.claimed AND NEW.tier_snapshot = 'daily' THEN
    PERFORM public.fn_award_daily_mission_milestones(NEW.user_id);
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_earn_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_engine text; v_period text; v_day date; v_budget bigint; v_spent bigint; v_awarded bigint;
    v_cap integer; v_cap_vip integer; v_is_vip boolean := false; v_at timestamptz;
    v_refuse text; v_refuse_detail text; v_armed boolean;
BEGIN
    BEGIN
        IF COALESCE(NEW.issuance_class, '') IN ('purchased', 'transferred', 'refund', 'admin', 'arena', 'spend', 'deletion', 'bridge') THEN
            RETURN NULL;
        END IF;
        IF COALESCE(NEW.type, '') = 'purchase' OR COALESCE(NEW.transaction_type, '') = 'purchase' THEN
            RETURN NULL;
        END IF;
        -- Fixture accounts are not players (2026-09-07 review DEF-03): their issuance is not
        -- promotional spend. Horses ARE players and are counted.
        IF public.fn_ca_is_fixture_account(NEW.user_id) THEN
            RETURN NULL;
        END IF;

        v_at     := COALESCE(NEW.created_at, now());
        v_engine := CASE WHEN NEW.issuance_class IS NULL THEN 'unclassified'
                         ELSE public.fn_ca_diamond_engine_of(NEW.type, NEW.transaction_type, NEW.source,
                                                             NEW.description, NEW.reference_id) END;
        v_period := to_char((v_at AT TIME ZONE 'America/Chicago'), 'YYYY-MM');
        v_day    := (v_at AT TIME ZONE 'America/Chicago')::date;

        -- THE PER-USER ROW FIRST. It is keyed (user_id, engine, day), so it contends only with the
        -- same player's own concurrent awards - which is to say, essentially never. It used to sit
        -- after the budget write and was therefore lost every time the budget write timed out,
        -- taking the per-user cap figure down with it.
        INSERT INTO public.diamond_user_daily_awards (user_id, engine, day, awarded, updated_at)
        VALUES (NEW.user_id, v_engine, v_day, NEW.amount, now())
        ON CONFLICT (user_id, engine, day) DO UPDATE
           SET awarded = diamond_user_daily_awards.awarded + EXCLUDED.awarded, updated_at = now()
        RETURNING awarded INTO v_awarded;

        -- THE BUDGET LINE EXISTS, BUT ITS TOTAL IS NO LONGER MAINTAINED HERE. This upsert touches
        -- the row only when the line is missing for a new period, so it is a once-a-month write,
        -- not a once-an-award one.
        INSERT INTO public.diamond_reward_budgets (period, engine, budget_diamonds, spent_diamonds, updated_at)
        VALUES (v_period, v_engine,
                COALESCE((SELECT b.budget_diamonds FROM public.diamond_reward_budgets b
                           WHERE b.engine = v_engine AND b.period < v_period
                           ORDER BY b.period DESC LIMIT 1), 2500000),
                0, now())
        ON CONFLICT (period, engine) DO NOTHING;

        -- ONE INSERT, NO CONTENTION. Two awards never touch the same row, so there is nothing to
        -- wait behind. This is the whole fix.
        INSERT INTO public.ca_diamond_engine_spend (period, engine, user_id, amount, journal_id, at)
        VALUES (v_period, v_engine, NEW.user_id, NEW.amount, NEW.id, v_at)
        ON CONFLICT (journal_id) DO NOTHING;

        -- RULING 21: THE ENGINE'S MONTHLY TOTAL IS A FORECAST, NOT A GATE. It is a pot shared
        -- between players, so refusing on it punishes whoever arrives last for what everybody
        -- else earned. The spend row appended above is the measurement, and the economy report
        -- reads it; nothing here refuses, and no incident is filed per award - daily_missions is
        -- 4.2x its line today, so one would fire on every single award and be muted inside a day
        -- (10.84). The only cap that refuses is the per-user one below.

        SELECT c.max_per_user_per_day, c.max_per_user_per_day_vip INTO v_cap, v_cap_vip
          FROM public.diamond_engine_daily_caps c WHERE c.engine = v_engine;
        IF v_cap_vip IS NOT NULL THEN
            SELECT COALESCE(p.is_vip, false) AND (COALESCE(p.vip_tier, '') = 'lifetime'
                     OR (p.vip_expires_at IS NOT NULL AND p.vip_expires_at > now()))
              INTO v_is_vip FROM public.profiles p WHERE p.id = NEW.user_id;
            IF COALESCE(v_is_vip, false) THEN v_cap := v_cap_vip; END IF;
        END IF;

        IF v_cap IS NOT NULL AND v_awarded > v_cap THEN
            IF public.fn_ca_diamond_rule_mode('DR7:user_over_daily_cap') = 'refuse' THEN
                v_refuse := COALESCE(v_refuse, 'DR7:user_over_daily_cap');
                v_refuse_detail := COALESCE(v_refuse_detail, format('engine %s day %s cap %s awarded %s', v_engine, v_day, v_cap, v_awarded));
            END IF;
            PERFORM public.fn_ca_diamond_incident('DR7:user_over_daily_cap', 'warning', NEW.user_id, NEW.amount,
                'fn_ca_diamond_earn_ledger',
                jsonb_build_object('engine', v_engine, 'day', v_day, 'is_vip', v_is_vip,
                                   'max_per_user_per_day', v_cap, 'awarded_today', v_awarded,
                                   'journal_id', NEW.id, 'reference_id', NEW.reference_id));
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- A FAILURE HERE MEANS A GUARD DID NOT RUN, and that is a different thing from a counter
        -- being late. While both rules are in `log` it is a warning; the moment either is armed to
        -- refuse, a write that could not complete is the guard failing OPEN, so it is CRITICAL and
        -- says so. The award is still paid: a player never loses an earned reward because our
        -- bookkeeping stumbled (10.9 rule 3), and "I could not tell" gets its own severity rather
        -- than being folded into silence (10.86).
        -- Only the per-user cap can refuse now (ruling 21), so it alone decides whether a
        -- write that could not complete means a guard failed open. The engine pot is a forecast
        -- and its rule row is deleted below; consulting a rule that no longer exists would read
        -- as armed while being nothing at all.
        v_armed := public.fn_ca_diamond_rule_mode('DR7:user_over_daily_cap') = 'refuse';
        PERFORM public.fn_ca_diamond_incident('DR7:ledger_write_failed',
            CASE WHEN v_armed THEN 'critical' ELSE 'warning' END, NEW.user_id, NEW.amount,
            'fn_ca_diamond_earn_ledger',
            jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM, 'journal_id', NEW.id,
                               'reference_id', NEW.reference_id, 'rules_armed', v_armed,
                               'note', CASE WHEN v_armed
                                            THEN 'A rule is armed to refuse and this write did not complete, so neither cap was evaluated for this award. The guard failed OPEN.'
                                            ELSE 'Both rules are in log mode; nothing was refused either way.' END));
    END;
    -- DIAMOND-RULINGS 17/18: a flipped DR7 refuses the credit. Raising here aborts the writer's
    -- whole transaction (balance, journal, ledger rows), so nothing is issued and nothing is
    -- half-written. The incident above rolls back with it; the writer's error carries the reason.
    IF v_refuse IS NOT NULL THEN
        RAISE EXCEPTION '%: promotional issuance refused (%)', v_refuse, v_refuse_detail
            USING ERRCODE = 'P0407';
    END IF;
    RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_agent_commission_rollup_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.agent_commission_unsettled_rollup AS r
         (club_id, user_id, owed, rows_behind, oldest_unsettled, updated_at)
  SELECT n.club_id, n.user_id,
         sum(n.amount), count(*), min(n.created_at), now()
    FROM new_rows n
   WHERE n.settled_at IS NULL AND n.club_id IS NOT NULL AND n.user_id IS NOT NULL
     AND NOT public.fn_agent_commission_paid_by_period(n.club_id, n.user_id, n.created_at)
   GROUP BY n.club_id, n.user_id
  ON CONFLICT (club_id, user_id) DO UPDATE
     SET owed             = r.owed + EXCLUDED.owed,
         rows_behind      = r.rows_behind + EXCLUDED.rows_behind,
         oldest_unsettled = least(r.oldest_unsettled, EXCLUDED.oldest_unsettled),
         updated_at       = now();

  -- Phase 6: the per-day total the Financials page reads.
  INSERT INTO public.ca_club_commission_daily AS c
         (club_id, stat_date, amount, rows_counted, updated_at)
  SELECT n.club_id, (n.created_at AT TIME ZONE 'UTC')::date, sum(n.amount), count(*), now()
    FROM new_rows n
   WHERE n.club_id IS NOT NULL
   GROUP BY n.club_id, (n.created_at AT TIME ZONE 'UTC')::date
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET amount       = c.amount + EXCLUDED.amount,
         rows_counted = c.rows_counted + EXCLUDED.rows_counted,
         updated_at   = now();
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_agent_commission_rollup_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pairs jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Transition tables cannot be combined with a column list on the
    -- trigger, so the trigger fires on every UPDATE and the filter is here:
    -- only rows whose outstanding amount, settlement or ownership changed
    -- name a pair to recompute. A notes-only update names none.
    SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('club_id', x.club_id, 'user_id', x.user_id)), '[]'::jsonb)
      INTO v_pairs
      FROM (
        SELECT o.club_id, o.user_id
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.settled_at IS DISTINCT FROM n.settled_at
            OR o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.user_id IS DISTINCT FROM n.user_id
        UNION
        SELECT n.club_id, n.user_id
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.settled_at IS DISTINCT FROM n.settled_at
            OR o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.user_id IS DISTINCT FROM n.user_id
      ) x;

    -- Phase 6: the day total moves only when amount, club or day moved.
    -- Subtract the old row, add the new one; a settlement changes neither.
    INSERT INTO public.ca_club_commission_daily AS c
           (club_id, stat_date, amount, rows_counted, updated_at)
    SELECT x.club_id, x.d, sum(x.amount), sum(x.n), now()
      FROM (
        SELECT o.club_id, (o.created_at AT TIME ZONE 'UTC')::date AS d, -o.amount AS amount, -1 AS n
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.created_at IS DISTINCT FROM n.created_at
        UNION ALL
        SELECT n.club_id, (n.created_at AT TIME ZONE 'UTC')::date, n.amount, 1
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.created_at IS DISTINCT FROM n.created_at
      ) x
     WHERE x.club_id IS NOT NULL
     GROUP BY x.club_id, x.d
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET amount       = c.amount + EXCLUDED.amount,
           rows_counted = c.rows_counted + EXCLUDED.rows_counted,
           updated_at   = now();
  ELSE
    SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('club_id', o.club_id, 'user_id', o.user_id)), '[]'::jsonb)
      INTO v_pairs
      FROM old_rows o;

    INSERT INTO public.ca_club_commission_daily AS c
           (club_id, stat_date, amount, rows_counted, updated_at)
    SELECT o.club_id, (o.created_at AT TIME ZONE 'UTC')::date, -sum(o.amount), -count(*), now()
      FROM old_rows o
     WHERE o.club_id IS NOT NULL
     GROUP BY o.club_id, (o.created_at AT TIME ZONE 'UTC')::date
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET amount       = c.amount + EXCLUDED.amount,
           rows_counted = c.rows_counted + EXCLUDED.rows_counted,
           updated_at   = now();
  END IF;
  IF v_pairs <> '[]'::jsonb THEN
    PERFORM public.fn_agent_commission_rollup_recompute(v_pairs);
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_register_follows_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    PERFORM public.fn_ca_register_diamond_journal_row(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    -- The diamonds already moved and the journal row stands. A register that
    -- could not be written is an incident, not a refused purchase.
    BEGIN
      PERFORM public.fn_ca_diamond_incident(
        'MINT:register_follow_failed', 'critical', NEW.user_id, NEW.amount,
        'fn_ca_diamond_register_follows_journal',
        jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM,
                           'journal_id', NEW.id, 'reference_id', NEW.reference_id));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_sync_profile_total_hands()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := COALESCE(NEW.user_id, OLD.user_id);
BEGIN
  IF v_user IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  /* Recomputed from the table rather than incremented. An increment has to be
     right on every path - insert, update, delete, and the upsert the
     achievement engine uses - and being wrong once is permanent. A SUM over a
     handful of club rows for one player is cheap and cannot drift. */
  UPDATE public.profiles p
     SET total_hands_played = COALESCE((
           SELECT sum(s.hands_played) FROM public.player_stats s WHERE s.user_id = v_user
         ), 0)
   WHERE p.id = v_user;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.zz_closed_period_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'closed' AND NOT COALESCE(public.fn_is_platform_admin(), false) THEN
      RAISE EXCEPTION 'PERIOD_CLOSED: settlement period % is closed and cannot be deleted', OLD.id;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status = 'closed' AND NOT COALESCE(public.fn_is_platform_admin(), false) THEN
    IF NEW.status                 IS DISTINCT FROM OLD.status
       OR NEW.club_id             IS DISTINCT FROM OLD.club_id
       OR NEW.union_id            IS DISTINCT FROM OLD.union_id
       OR NEW.start_at            IS DISTINCT FROM OLD.start_at
       OR NEW.end_at              IS DISTINCT FROM OLD.end_at
       OR NEW.settled_at          IS DISTINCT FROM OLD.settled_at
       OR NEW.total_rake_collected     IS DISTINCT FROM OLD.total_rake_collected
       OR NEW.total_commissions_paid   IS DISTINCT FROM OLD.total_commissions_paid
       OR NEW.total_player_winnings    IS DISTINCT FROM OLD.total_player_winnings
       OR NEW.total_player_losses      IS DISTINCT FROM OLD.total_player_losses
       OR NEW.total_bbj_contributions  IS DISTINCT FROM OLD.total_bbj_contributions
    THEN
      RAISE EXCEPTION
        'PERIOD_CLOSED: settlement period % is closed. Correct it forward with an adjusting entry; do not edit a closed period.',
        OLD.id;
    END IF;
  END IF;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_diamond_journal_classifier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_type text := COALESCE(NEW.transaction_type, NEW.type, 'unknown');
  v_stack text; v_writer text; v_filled boolean := false;
BEGIN
  IF NEW.issuance_class IS NULL THEN
    v_filled := true;
    NEW.issuance_class := CASE
      WHEN v_type = 'purchase' THEN 'purchased'
      WHEN v_type = 'refund' OR right(v_type, 7) = '_refund' THEN 'refund'
      WHEN v_type IN ('transfer', 'diamond_gift_received', 'live_gift_received', 'diamond_received',
                      'diamond_gift_sent', 'live_gift_sent', 'spend_transfer') THEN 'transferred'
      WHEN v_type = 'adjustment' THEN 'admin'
      WHEN v_type = 'mint' THEN 'admin'
      WHEN v_type = 'burn' THEN 'deletion'
      WHEN v_type IN ('union_grant', 'signup_bonus') THEN 'promotional'
      WHEN COALESCE(NEW.amount, 0) < 0 THEN 'spend'
      WHEN EXISTS (SELECT 1 FROM public.diamond_reward_catalog c WHERE c.action_key = v_type)
           OR COALESCE(NEW.description, '') LIKE 'Diamond Rewards v2:%' THEN 'promotional'
      ELSE 'earned'
    END;
  END IF;
  IF NEW.counterparty IS NULL THEN
    v_filled := true;
    NEW.counterparty := CASE NEW.issuance_class
      WHEN 'purchased' THEN 'purchase_clearing'
      WHEN 'refund' THEN CASE WHEN v_type IN ('refund', 'stripe') THEN 'purchase_clearing' ELSE 'revenue:' || v_type END
      WHEN 'transferred' THEN 'player:' || COALESCE(NEW.metadata->>'recipient_id', NEW.metadata->>'sender_id', 'unknown')
      WHEN 'admin' THEN 'adjustment'
      WHEN 'deletion' THEN 'retired'
      WHEN 'spend' THEN 'revenue:' || v_type
      ELSE 'promo_budget:' || public.fn_ca_diamond_engine_of(NEW.type, NEW.transaction_type, NEW.source, NEW.description, NEW.reference_id)
    END;
  END IF;
  IF v_filled THEN
    BEGIN
      GET DIAGNOSTICS v_stack = PG_CONTEXT;
      SELECT (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] INTO v_writer
        FROM regexp_split_to_table(COALESCE(v_stack, ''), E'\n') WITH ORDINALITY AS t(ln, ord)
       WHERE t.ln ~ 'function (?:public\.)?[A-Za-z0-9_]+\('
         AND (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] <> 'fn_ca_diamond_journal_classifier'
       ORDER BY t.ord LIMIT 1;
      PERFORM public.fn_ca_diamond_incident(
        'DR12:journal_row_unclassified_by_writer', 'info', NEW.user_id, NEW.amount,
        COALESCE(v_writer, '(no function frame)'),
        jsonb_build_object('type', NEW.type, 'transaction_type', NEW.transaction_type,
                           'description', left(NEW.description, 120), 'reference_id', NEW.reference_id,
                           'classified_as', NEW.issuance_class, 'counterparty', NEW.counterparty,
                           'note', 'the writer left issuance_class or counterparty NULL; the classifier filled them. Fix the writer.'));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_vip_points_move_only_with_a_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_writer text := NULLIF(current_setting('app.vip_points_writer', true), '');
BEGIN
  IF NEW.current_points < 0 THEN
    RAISE EXCEPTION 'vip_points.current_points cannot go negative (% for %)', NEW.current_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF (NEW.current_points <> 0 OR NEW.lifetime_points <> 0) AND v_writer IS NULL THEN
      RAISE EXCEPTION 'a vip_points row is born at zero unless a ledger writer (fn_award_vip_credit) creates it with its first leg'
        USING ERRCODE = 'P0403';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.lifetime_points < OLD.lifetime_points THEN
    RAISE EXCEPTION 'vip_points.lifetime_points cannot shrink (% -> % for %)', OLD.lifetime_points, NEW.lifetime_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF (NEW.current_points IS DISTINCT FROM OLD.current_points OR NEW.lifetime_points IS DISTINCT FROM OLD.lifetime_points)
     AND v_writer IS NULL THEN
    RAISE EXCEPTION
      'vip_points for % moves only through fn_award_vip_credit or fn_redeem_vip_points, which write the leg in the same transaction. A balance with no leg is the defect this guard exists for.',
      NEW.user_id USING ERRCODE = 'P0403';
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_attach_bounty_ledger_obligation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_obligation_id uuid;
  /* A REVEALED MYSTERY BOUNTY MAY NAME ITS OWN OBLIGATION (2026-09-10).
     A paid mystery chest is a bounty ledger entry like any other and its
     provenance is the mystery obligation. Only a row that says so may name
     one; a regular bounty still cannot borrow a mystery generation. */
  v_mystery_ok boolean := COALESCE(NEW.is_mystery_revealed, false);
BEGIN
  IF NEW.bounty_obligation_id IS NULL THEN
    IF COALESCE(v_context,'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_obligation_id := v_context::uuid;
      SELECT o.id INTO NEW.bounty_obligation_id
        FROM public.tournament_bounty_obligations o
       WHERE o.id=v_obligation_id AND o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND (o.mode<>'mystery_chest' OR v_mystery_ok);
      IF NEW.bounty_obligation_id IS NULL THEN
        RAISE EXCEPTION 'bounty ledger context does not match its exact generation'
          USING ERRCODE='check_violation';
      END IF;
    ELSIF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND o.mode<>'mystery_chest' AND o.state='pending'
    ) THEN
      RAISE EXCEPTION 'generation-bound bounty ledger insert has no exact obligation context'
        USING ERRCODE='check_violation';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.id=NEW.bounty_obligation_id AND o.tournament_id=NEW.tournament_id
       AND o.eliminated_user_id=NEW.eliminated_player_id
       AND (o.mode<>'mystery_chest' OR v_mystery_ok)
  ) THEN
    RAISE EXCEPTION 'bounty ledger names a mismatched obligation generation'
      USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ack_bounty_obligation_from_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.tournament_bounty_obligations o
     SET state = 'settled', settled_at = COALESCE(settled_at, now()), last_error = NULL
   WHERE o.id=NEW.bounty_obligation_id AND o.mode <> 'mystery_chest' AND o.state='pending'
     AND public.fn_bounty_obligation_has_complete_marker(o.id);
  RETURN NEW;
END;
$function$;
