CREATE OR REPLACE FUNCTION public.fn_cash_seat_move_set_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- ONE AUTHORITY. The column default is gone; every insert gets its deadline
  -- from the table it is leaving.
  NEW.expires_at := coalesce(NEW.created_at, now())
                  + public.fn_cash_seat_move_window(NEW.from_table_id);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_cash_game_floor_from_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_def jsonb;
BEGIN
  IF NEW.ruleset_snapshot IS NULL THEN
    RETURN NEW;
  END IF;

  -- THE TEMPLATE IS A PROMISE TO THE PLAYER (2026-09-09). The four fields the
  -- lobby blurb names come from fn_cash_template_defaults on EVERY write, not
  -- only at creation. "No Antes, No Bombs, No VPIP Floor" cannot be true of a
  -- game whose snapshot says otherwise, whoever wrote that snapshot.
  --
  -- `||` and not jsonb_set for `bombs`: the object is replaced WHOLE, so a
  -- stale member inside it (a trigger left over from a template change) cannot
  -- survive underneath a corrected `enabled`.
  v_def := public.fn_cash_template_defaults(NEW.template_name, NEW.variant);

  NEW.ruleset_snapshot := NEW.ruleset_snapshot
    || jsonb_build_object(
         'vpip_floor',   v_def->'vpip_floor',
         'vpip_window',  v_def->'vpip_window',
         'regular_ante', v_def->'regular_ante',
         'bombs',        v_def->'bombs');

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_manifest_is_restated_not_edited()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE
  v_reason text := NULLIF(current_setting('app.manifest_restatement', true), '');
  v_changed boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'DELETE on ca_ledger_day_manifests is forbidden: an attested day stays attested. If its rows legitimately changed, restate it through fn_ca_ledger_day_manifest(day, reason).'
      USING ERRCODE = 'P0403';
  END IF;

  v_changed :=
       NEW.sha256     IS DISTINCT FROM OLD.sha256
    OR NEW.row_count  IS DISTINCT FROM OLD.row_count
    OR NEW.first_seq  IS DISTINCT FROM OLD.first_seq
    OR NEW.last_seq   IS DISTINCT FROM OLD.last_seq
    OR NEW.net_amount IS DISTINCT FROM OLD.net_amount
    OR NEW.day        IS DISTINCT FROM OLD.day;

  IF NOT v_changed THEN
    RETURN NEW;                       -- bookkeeping only (last_checked_at)
  END IF;

  IF NEW.day IS DISTINCT FROM OLD.day THEN
    RAISE EXCEPTION 'a manifest cannot be moved to another day' USING ERRCODE = 'P0403';
  END IF;

  IF v_reason IS NULL THEN
    RAISE EXCEPTION
      'UPDATE of an attested field on ca_ledger_day_manifests (%) is forbidden: a manifest is restated, never edited. Call fn_ca_ledger_day_manifest(day, reason), which keeps the old value.',
      OLD.day
      USING ERRCODE = 'P0403';
  END IF;

  /* The restatement exists by construction. Nobody has to remember. */
  INSERT INTO public.ca_ledger_day_manifest_restatements
    (day, old_row_count, new_row_count, old_sha256, new_sha256, reason, restated_by, application)
  VALUES
    (OLD.day, OLD.row_count, NEW.row_count, OLD.sha256, NEW.sha256, v_reason,
     current_user, current_setting('application_name', true));

  NEW.restated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_diamond_game_config_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.diamond_game_config_history (host_id, game, changed_by, before, after)
  VALUES (NEW.host_id, NEW.game, COALESCE(NEW.updated_by, auth.uid()),
          CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, to_jsonb(NEW));
  RETURN NEW;
END $function$;
