CREATE OR REPLACE FUNCTION public.trg_freeze_satellite_settlement_batch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_gate text := COALESCE(
    current_setting('app.atomic_satellite_settlement',true),'');
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'an atomic satellite settlement receipt cannot be deleted'
      USING ERRCODE='check_violation';
  END IF;
  IF ROW(NEW.tournament_id,NEW.winner_user_id,NEW.target_tournament_id,
         NEW.plan_fingerprint,NEW.entitlement_count,NEW.award_depth,
         NEW.amount_owed,NEW.source,NEW.prepared_at)
     IS DISTINCT FROM
     ROW(OLD.tournament_id,OLD.winner_user_id,OLD.target_tournament_id,
         OLD.plan_fingerprint,OLD.entitlement_count,OLD.award_depth,
         OLD.amount_owed,OLD.source,OLD.prepared_at) THEN
    RAISE EXCEPTION 'an atomic satellite plan identity cannot change'
      USING ERRCODE='check_violation';
  END IF;
  IF OLD.settled_at IS NOT NULL
     AND ROW(NEW.settled_at,NEW.outcomes)
         IS DISTINCT FROM ROW(OLD.settled_at,OLD.outcomes) THEN
    RAISE EXCEPTION 'a settled satellite receipt is immutable'
      USING ERRCODE='check_violation';
  END IF;
  IF v_gate<>OLD.tournament_id::text THEN
    RAISE EXCEPTION 'satellite batch writes belong to the atomic finalizer'
      USING ERRCODE='insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_serialize_engine_maintenance_break_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  /* PostgreSQL takes ACCESS EXCLUSIVE before firing a TRUNCATE trigger. Waiting
     for the advisory boundary from there would invert the canonical order
     against an admitted entry that next reads this table. This singleton has
     no legitimate truncate path, so refuse immediately instead of deadlocking. */
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'engine_maintenance_break may not be truncated'
      USING ERRCODE = '0A000';
  END IF;
  /* One exclusive writer boundary. The matching entry paths take this key in
     shared mode, so purchases stay concurrent with each other but can never
     straddle a maintenance-row commit. Transaction scope prevents a pooled
     connection from retaining the lock. */
  PERFORM pg_advisory_xact_lock(530090, 1);
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_validate_tournament_table_origin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_parent_status text;
BEGIN
  SELECT t.status::text INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = NEW.tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament table origin lost parent tournament %', NEW.tournament_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.origin_kind = 'capacity' THEN
    IF upper(v_parent_status) = 'RUNNING'
       AND NOT EXISTS (
         SELECT 1
           FROM public.tournament_capacity_table_receipts c
          WHERE c.table_id = NEW.table_id
            AND c.tournament_id = NEW.tournament_id
       ) THEN
      PERFORM public.fn_stage_a_bridge_legacy_capacity_receipt(
        NEW.table_id,
        NEW.tournament_id
      );
    END IF;

    IF upper(v_parent_status) <> 'RUNNING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_capacity_table_receipts c
          WHERE c.table_id = NEW.table_id
            AND c.tournament_id = NEW.tournament_id
       ) THEN
      RAISE EXCEPTION
        'TOURNAMENT_CAPACITY_RECEIPT_REQUIRED: RUNNING table % must create its canonical capacity receipt in the same transaction',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'launch' THEN
    IF upper(v_parent_status) <> 'REGISTERING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_launch_receipts r
          WHERE r.tournament_id = NEW.tournament_id
            AND r.launch_id = NEW.launch_id
            AND r.lease_generation = NEW.launch_lease_generation
            AND r.completed_at IS NULL
       ) THEN
      RAISE EXCEPTION
        'STALE_TOURNAMENT_LAUNCH_TABLE: table % does not belong to the exact incomplete launch receipt',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'prelaunch' THEN
    IF upper(v_parent_status) = 'RUNNING'
       OR EXISTS (
         SELECT 1
           FROM public.tournament_launch_receipts r
          WHERE r.tournament_id = NEW.tournament_id
       ) THEN
      RAISE EXCEPTION
        'TOURNAMENT_PRELAUNCH_ORIGIN_STALE: table % crossed a launch boundary in its birth transaction',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'legacy' THEN
    /* Only the pre-trigger migration backfill can create this honestly.  ACLs
       exclude every application role, and the runtime classifier has no
       legacy branch. */
    RETURN NEW;
  ELSE
    RAISE EXCEPTION 'unknown tournament table origin %', NEW.origin_kind
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$;
