    RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.guard_wallet_balance_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stack   TEXT;
  v_bypass  TEXT;
  v_allowed TEXT[] := ARRAY[
    'atomic_credit_wallet_and_log','atomic_deduct_wallet_and_log','atomic_wallet_transfer',
    'atomic_chip_transfer','fn_idempotent_credit_wallet','fn_idempotent_deduct_wallet',
    'fn_idempotent_wallet_transfer','atomic_table_buyin','atomic_table_cashout',
    'atomic_table_rebuy','atomic_table_addon','atomic_table_withdraw','atomic_seat_horse','player_leave_table','atomic_tournament_register',
    'atomic_tournament_unregister','atomic_cancel_tournament','distribute_tournament_prizes',
    'process_tournament_rebuy',
    'atomic_pay_player_rakeback','credit_agent_commission',
    'credit_player_rakeback','fn_cancel_cashout','fn_reject_cashout',
    'fn_clawback_chips_atomic','distribute_chips','mint_club_chips','add_chips','add_to_promo_wallet',
    'credit_player_wallet','deduct_player_wallet','wallet_internal_transfer','wallet_user_transfer',
    'create_user_wallets','reconcile_ledger_nightly',
    -- added 2026-08-15 with the chip-removal authority policy
    'fn_admin_remove_player_chips','fn_approve_cashout_atomic','fn_cancel_cashout_atomic',
    -- added 2026-08-21 with the diamond-backed Chip Mint (Dan's directive)
    'fn_mint_chips_from_diamonds',
    -- added 2026-08-23 with the Club Bank Cashier (Dan directive)
    'fn_club_bank_send',
    'fn_club_bank_claim_back', 'fn_promo_wallet_send',
    'fn_club_bank_reverse'
    -- removed 2026-08-31 (phase 6): execute_commission_payout, which credited a
    -- wallet, debited nothing and never marked the commission settled.
    -- removed 2026-09-01 (phase 7): atomic_pay_agent_settlement, a staff payout
    -- that decremented a column nothing incremented.
  ];
  v_fn TEXT;
BEGIN
  v_bypass := current_setting('app.bypass_wallet_guard', true);
  IF v_bypass = 'on' THEN RETURN NEW; END IF;
  GET DIAGNOSTICS v_stack = PG_CONTEXT;
  FOREACH v_fn IN ARRAY v_allowed LOOP
    IF v_stack ~ ('function (public\.)?' || v_fn || '\(') THEN
      RETURN NEW;
    END IF;
  END LOOP;
  RAISE EXCEPTION
    'Direct balance mutation on %.% is forbidden by Phase 4.1.6a guard. '
    'All balance changes must flow through the whitelisted SECURITY DEFINER '
    'RPCs (atomic_*, fn_idempotent_*, distribute_chips, mint_club_chips, etc.) '
    'that log to chip_ledger. Admin override: '
    'SELECT set_config(''app.bypass_wallet_guard'', ''on'', true);',
    TG_TABLE_SCHEMA, TG_TABLE_NAME
    USING ERRCODE = 'insufficient_privilege';
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_sync_mfa_required_on_club_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.owner_id IS NOT NULL THEN
        UPDATE public.profiles
           SET mfa_required = TRUE
         WHERE id = NEW.owner_id
           AND mfa_required = FALSE;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_audit_club_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor   uuid := auth.uid();
  v_before  jsonb := '{}'::jsonb;
  v_after   jsonb := '{}'::jsonb;
  v_old     jsonb;
  v_new     jsonb;
  v_key     text;
  -- `settings`, `tagline` and `lobby_message` are new here. The rules a member
  -- is held to live inside `settings`, and a rewrite used to leave no trace at
  -- all: no row, no actor, no before.
  v_watched text[] := ARRAY[
    'name','description','is_public','requires_approval',
    'default_rake_percent','rake_cap',
    'allow_straddle','allow_run_it_twice','allow_rabbit_hunt',
    'min_buyin_bb','max_buyin_bb','logo_url',
    'bbj_rake_enabled','spins_enabled','spins_preseed_amount','spins_wallet_funding',
    'settings','tagline','lobby_message'];
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  v_old := to_jsonb(OLD);
  v_new := to_jsonb(NEW);
  FOREACH v_key IN ARRAY v_watched LOOP
    IF (v_old -> v_key) IS DISTINCT FROM (v_new -> v_key) THEN
      v_before := v_before || jsonb_build_object(v_key, v_old -> v_key);
      v_after  := v_after  || jsonb_build_object(v_key, v_new -> v_key);
    END IF;
  END LOOP;

  IF v_after = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  -- The same target and the same swallow the original used. An audit row must
  -- never be the reason a club cannot be saved, and this migration is here to
  -- widen what is watched, not to change where it is written.
  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(NEW.id, v_actor), 'update_club_settings',
       'club', NEW.id, NEW.id, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_audit_club_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid := auth.uid();
  v_action text;
  v_before jsonb;
  v_after  jsonb;
  v_club   uuid;
  v_target uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_club   := OLD.club_id;
    v_target := OLD.user_id;
    v_action := CASE WHEN v_actor = OLD.user_id THEN 'member_left'
                     ELSE 'kick_member' END;
    v_before := jsonb_build_object('role', OLD.role, 'status', OLD.status);
    v_after  := NULL;
  ELSE
    v_club   := NEW.club_id;
    v_target := NEW.user_id;
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      v_action := 'role_change';
      v_before := jsonb_build_object('role', OLD.role);
      v_after  := jsonb_build_object('role', NEW.role);
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
      v_action := CASE
        WHEN NEW.status = 'banned' THEN 'banned'
        WHEN OLD.status = 'banned' THEN 'unban_member'
        ELSE 'member_status_change' END;
      v_before := jsonb_build_object('status', OLD.status);
      v_after  := jsonb_build_object('status', NEW.status);
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(v_club, v_actor),
       v_action, 'member', v_target, v_club, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trail insert failed for club % member %: %',
      v_club, v_target, SQLERRM;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_audit_club_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RETURN OLD;
  END IF;
  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id, before_state)
    VALUES
      (v_actor,
       CASE WHEN v_actor = OLD.owner_id THEN 'owner' ELSE 'system' END,
       'delete_club', 'club', OLD.id,
       NULL,
       jsonb_build_object('name', OLD.name, 'member_count', OLD.member_count));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trail insert failed for club delete %: %', OLD.id, SQLERRM;
  END;
  RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_members_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    -- fn_club_set_member_role sets this for the duration of its own UPDATE.
    IF COALESCE(current_setting('app.club_role_change', true), '') <> 'on'
       -- migrations, seeds and server-side jobs run as these and are trusted
       AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
      RAISE EXCEPTION
        'club_members.role must be changed through fn_club_set_member_role (attempted % -> %, as %)',
        OLD.role, NEW.role, current_user
        USING ERRCODE = '42501',
              HINT = 'The grant matrix lives in fn_club_grantable_roles. A direct '
                     'update would bypass it, which is what this trigger exists to stop.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_spin_pool_follows_union_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.union_id IS NOT NULL AND OLD.union_id IS DISTINCT FROM NEW.union_id THEN
    PERFORM public.fn_close_club_wallets_on_union_join(NEW.id, NEW.union_id);
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_union_totals_follow_club_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT uc.union_id
      FROM newrows n
      JOIN oldrows o ON o.id = n.id
      JOIN union_clubs uc ON uc.club_id = n.id
     WHERE COALESCE(n.member_count, 0)      IS DISTINCT FROM COALESCE(o.member_count, 0)
        OR COALESCE(n.admin_count, 0)       IS DISTINCT FROM COALESCE(o.admin_count, 0)
        OR COALESCE(n.super_agent_count, 0) IS DISTINCT FROM COALESCE(o.super_agent_count, 0)
        OR COALESCE(n.agent_count, 0)       IS DISTINCT FROM COALESCE(o.agent_count, 0)
  LOOP
    PERFORM public.recompute_union_levels(r.union_id, true);
  END LOOP;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_members_no_agent_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cursor uuid;
  v_hops   int := 0;
begin
  if new.agent_id is null then
    return new;
  end if;

  if new.agent_id = new.user_id then
    raise exception
      'club_members.agent_id: a member cannot be their own upline (club %, member %)',
      new.club_id, new.user_id
      using errcode = '23514';
  end if;

  v_cursor := new.agent_id;
  while v_cursor is not null and v_hops < 64 loop
    if v_cursor = new.user_id then
      raise exception
        'club_members.agent_id: % cannot sit under % - that would close a cycle in club %',
        new.user_id, new.agent_id, new.club_id
        using errcode = '23514';
    end if;
    select cm.agent_id
      into v_cursor
      from public.club_members cm
     where cm.club_id = new.club_id
       and cm.user_id = v_cursor;
    if not found then
      exit;
    end if;
    v_hops := v_hops + 1;
  end loop;

  if v_hops >= 64 then
    raise exception
      'club_members.agent_id: the upline chain above % is deeper than 64 levels or already loops',
      new.agent_id
      using errcode = '23514';
  end if;

  return new;
end
$function$;
CREATE OR REPLACE FUNCTION public.fn_club_members_ledger_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d     numeric;
  actor uuid;
  cat   text;
  tid   uuid;
  st    text;
  msg   text;
  cp    text;
  cpid  uuid;
BEGIN
  /* THE AUTOSKIP CONTRACT IS ONE CONTRACT (2026-09-09). Every other journal
     writer on this platform stands down when the caller sets
     app.ledger_autoskip_<table>, because the caller is writing the leg itself
     with the period, the key and the metadata that only it knows. This writer
     never learned that clause. So a settlement that suppressed the clubs
     trigger and wrote its own named leg still got an anonymous twin from this
     side, and the movement reached the journal twice: on 2026-09-09 round 2
     moved 20,377.49 of commission and recorded 40,754.98 of legs. Standing
     down here is what makes one movement, one leg true for the busiest
     balance column on the platform. */
  IF current_setting('app.ledger_autoskip_club_members', true) = '1' THEN
    RETURN NEW;
  END IF;

  d := COALESCE(NEW.chip_balance, 0) - COALESCE(OLD.chip_balance, 0);

  IF d = 0 THEN
    RETURN NEW;
  END IF;

  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');

  BEGIN
    tid := NULLIF(current_setting('app.ledger_tournament', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    tid := NULL;
  END;

  /* THE COUNTERPARTY IS DECLARED, NEVER INFERRED (2026-08-31). */
  cp := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    cpid := NULL;
  END;

  BEGIN
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, tournament_id, description)
    VALUES (
      actor,
      CASE WHEN d > 0 THEN cp              ELSE 'player_wallet' END,
      CASE WHEN d > 0 THEN cpid            ELSE NEW.user_id     END,
      CASE WHEN d > 0 THEN 'player_wallet' ELSE cp              END,
      CASE WHEN d > 0 THEN NEW.user_id     ELSE cpid            END,
      abs(d), cat, NEW.club_id, tid,
      'auto-audited club_members.chip_balance delta ' || d::text);

  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_membership_approval_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_requires boolean;
  v_owner uuid;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  v_uid := auth.uid();

  IF NEW.user_id IS DISTINCT FROM v_uid THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(requires_approval, false), owner_id
    INTO v_requires, v_owner
    FROM clubs WHERE id = NEW.club_id;

  IF NOT FOUND OR NOT v_requires THEN
    RETURN NEW;
  END IF;

  IF v_owner = v_uid OR is_club_admin(NEW.club_id, v_uid) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.status := 'pending';
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'This club requires owner approval. Your request is pending review.'
    USING ERRCODE = 'check_violation';
END;
$function$;
