CREATE OR REPLACE FUNCTION public.fn_audit_club_entry_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_action text; v_club uuid; v_target uuid; v_actor uuid; v_details jsonb;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    v_action:='club_created'; v_club:=NEW.id; v_target:=NEW.id;
    v_actor:=COALESCE(auth.uid(),NEW.owner_id);
    v_details:=jsonb_build_object('club_code',NEW.club_id,'requires_approval',NEW.requires_approval);
  ELSIF TG_TABLE_NAME='club_members' THEN
    v_club:=NEW.club_id; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_action:=CASE WHEN TG_OP='INSERT' THEN 'club_join_'||NEW.status ELSE 'club_join_status_changed' END;
    v_details:=jsonb_build_object('status',NEW.status,'previous_status',CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END);
  ELSE
    v_action:='player_search_privacy_changed'; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_details:=jsonb_build_object('discoverable',NEW.discoverable,'show_presence',NEW.show_presence,'show_current_table',NEW.show_current_table);
  END IF;
  INSERT INTO public.audit_trail(
    club_id,actor_id,actor_role,action,target_type,target_id,after_state
  ) VALUES(
    v_club,v_actor,'system',v_action,TG_TABLE_NAME,v_target,jsonb_strip_nulls(v_details)
  );
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_club_members_staff_earn_no_rakeback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Dan 2026-08-31: "CO-OWNERS AND ADMINS GET NO RAKE BACK."
  -- player_rakeback_pct is the first branch of fn_player_rakeback_rate, so a
  -- non-zero value here is money. owner is deliberately not covered.
  NEW.player_rakeback_pct := 0;
  NEW.rakeback_rate       := 0;
  NEW.commission_rate     := 0;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_autoledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid;
  v_club uuid; v_union uuid; v_entity uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN NULL ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE NULL END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_seed_new_club_opening_bank()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF COALESCE(NEW.is_union, false) THEN
    RETURN NEW;
  END IF;

  -- THE OPENING GRANT IS DENOMINATED IN CHIPS. Handing it to a club that plays in another asset
  -- would create a hundred thousand chips inside it, register them against the chip supply, and
  -- put a diamond club in the chip trial balance - none of it asked for by anyone. The platform
  -- club is funded by fn_ca_mint(diamonds, destination = house) instead (standard 3.2).
  IF COALESCE(NEW.asset, 'chips') <> 'chips' THEN
    RETURN NEW;
  END IF;

  -- THE MINT (2026-09-03): the opening grant is issued from the same account
  -- fn_ca_mint issues from, so the journal row reads
  -- issuance_reserve -> club_treasury, category mint, like every other mint.
  NEW.chip_treasury := 100000;
  PERFORM public.fn_ca_declare_ledger(
    'mint', 'issuance_reserve', NULL, NULL,
    'club-opening-grant:' || NEW.id::text);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_record_new_club_opening_bank()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_chip_id uuid;
  v_supply numeric;
  v_op text := 'club-opening-grant:' || NEW.id::text;
  v_owner_label text;
BEGIN
  -- The seeder above refuses to set a chip treasury on a non-chip club, so this would return
  -- early on the amount test anyway. It is stated rather than inferred, so that setting the
  -- treasury by hand on a diamond club cannot quietly re-arm a chip mint.
  IF COALESCE(NEW.is_union, false)
     OR COALESCE(NEW.asset, 'chips') <> 'chips'
     OR COALESCE(NEW.chip_treasury, 0) <> 100000 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.chip_transactions (
    club_id, amount, transaction_type, notes, balance_after, metadata
  ) VALUES (
    NEW.id,
    100000,
    'club_opening_grant',
    'New Club Opening Bank',
    100000,
    jsonb_build_object(
      'source', 'the_mint',
      'destination', 'club_bank',
      'club_owner_id', NEW.owner_id,
      'club_code', NEW.club_id,
      'opening_balance', 100000,
      'mint_op_id', v_op
    )
  );

  /* THE REGISTER (2026-09-03): the row fn_ca_mint would have written. The
     journal row was written by the clubs auto-ledger when the treasury was
     set at INSERT (issuance_reserve -> club_treasury, key = v_op). */
  SELECT id INTO v_chip_id FROM public.chip_ledger
   WHERE idempotency_key = v_op
   ORDER BY created_at DESC LIMIT 1;
  IF v_chip_id IS NULL THEN
    SELECT id INTO v_chip_id FROM public.chip_ledger
     WHERE category = 'mint' AND from_type = 'issuance_reserve'
       AND to_type = 'club_treasury' AND to_entity_id = NEW.id AND amount = 100000
     ORDER BY created_at DESC LIMIT 1;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + 100000
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_owner_label FROM public.profiles p WHERE p.id = NEW.owner_id;

  BEGIN
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount,
       balance_before, balance_after, supply_after, reason,
       performed_by, performed_by_label, chip_ledger_id)
    VALUES
      (v_op, 'mint', 'chips', 'club', NEW.id, NEW.name, 100000,
       0, 100000, v_supply,
       'New Club Opening Bank: 100,000 chips from the Mint on creation, playable inside this club only',
       NEW.owner_id, v_owner_label, v_chip_id);
  EXCEPTION WHEN unique_violation THEN
    NULL;  -- the same club's grant is already on the register
  END;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_require_explicit_club_membership_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_source text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  IF v_source NOT IN ('join_club', 'club_owner_create') THEN
    RAISE EXCEPTION 'MEMBERSHIP_REQUIRES_JOIN: Club Members Can Only Be Added Through Join A Club'
      USING ERRCODE = '42501';
  END IF;
