$function$;
CREATE OR REPLACE FUNCTION public.fn_ca_autoledger_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; oldv numeric;
  v_club uuid; v_union uuid; v_entity uuid; actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN OLD;
  END IF;

  o := to_jsonb(OLD);
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (o->>'id')::uuid
    WHEN o ? 'club_id' THEN NULLIF(o->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (o->>'id')::uuid
    WHEN o ? 'union_id' THEN NULLIF(o->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME IN ('agents','club_members') THEN NULLIF(o->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(o->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := round(COALESCE(NULLIF(o->>col,'')::numeric, 0), 2);
    CONTINUE WHEN oldv = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance)
      VALUES (actor,
        acct, v_entity, TG_TABLE_NAME || '.' || col,
        'chip_retirement', NULL, NULL,
        abs(oldv), CASE WHEN oldv > 0 THEN 'burn' ELSE 'correction' END,
        v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' balance ' || oldv::text
          || ' retired on row delete',
        oldv, 0);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ca_reject_automated_user_club_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_user_id uuid;
  v_automated boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
    v_automated := COALESCE(NEW.is_bot, false);
  ELSIF TG_TABLE_NAME = 'agents' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'table_seats' THEN
    -- A historical/departed seat remains immutable evidence. Only a live seat
    -- can put an automated player back onto a user-created club table.
    IF NEW.left_at IS NOT NULL THEN RETURN NEW; END IF;
    SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'tournament_players' THEN
    SELECT t.club_id INTO v_club_id
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    v_user_id := NEW.user_id;
  ELSE
    RAISE EXCEPTION 'Unsupported Automated-Club Guard Table: %', TG_TABLE_NAME;
  END IF;

  v_automated := v_automated OR COALESCE(
    (SELECT p.is_horse FROM public.profiles p WHERE p.id = v_user_id), false
  );

  IF v_automated AND NOT public.fn_ca_house_board_allows_automation(v_club_id) THEN
    RAISE EXCEPTION 'AUTOMATED_PLAYER_HOUSE_BOARD_ONLY: Automated Players Cannot Enter A User-Created Club'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_deep_stack_society_cannot_be_deleted_by_accident()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed boolean := COALESCE(current_setting('app.deep_stack_teardown', true), '') = 'on';
  v_query   text;
BEGIN
  SELECT a.query INTO v_query
    FROM pg_stat_activity a WHERE a.pid = pg_backend_pid();

  INSERT INTO public.deep_stack_delete_attempts
    (source_table, allowed, db_user, db_role, application, client_addr, backend_pid, running_query, old_row)
  VALUES
    (TG_TABLE_NAME, v_allowed, session_user, current_user,
     current_setting('application_name', true), host(COALESCE(inet_client_addr(), '0.0.0.0'::inet)),
     pg_backend_pid(), left(COALESCE(v_query, ''), 4000), to_jsonb(OLD));

  IF NOT v_allowed THEN
    RAISE EXCEPTION
      'DEEP_STACK_PROTECTED: this row belongs to Deep Stack Society (club 11192) and is not deletable'
      USING ERRCODE = '42501',
            HINT = 'The whole club was deleted once with no audit trail. Set app.deep_stack_teardown = ''on'' for your transaction if you really mean it.';
  END IF;

  RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_mark_new_club_opening_checklist()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF COALESCE(NEW.is_union, false) = false
     AND NEW.opening_checklist_started_at IS NULL THEN
    NEW.opening_checklist_started_at := clock_timestamp();
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_refuse_while_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  col  TEXT;
  changed BOOLEAN := FALSE;
  v_claims TEXT;
BEGIN
  IF TG_OP = 'UPDATE' AND TG_NARGS > 0 THEN
    FOREACH col IN ARRAY TG_ARGV LOOP
      IF to_jsonb(NEW) -> col IS DISTINCT FROM to_jsonb(OLD) -> col THEN
        changed := TRUE;
        EXIT;
      END IF;
    END LOOP;
    IF NOT changed THEN
      RETURN NEW;
    END IF;
  END IF;

  -- ONBOARDING NEVER FREEZES (to-do #2563 item 1). A membership row carrying
  -- no chips is identity, not money. This table, INSERT only, zero balance.
  IF TG_TABLE_NAME = 'club_members' AND TG_OP = 'INSERT'
     AND COALESCE((to_jsonb(NEW) ->> 'chip_balance')::numeric, 0) = 0 THEN
    RETURN NEW;
  END IF;

  IF public.fn_freeze_bypass_active() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- CHIP STANDARD (2026-09-05): A JOURNAL ROW IS THE RECORD OF A WRITE, NOT A
  -- WRITE. When a balance write was permitted (a money table outside this
  -- guard, or a permitted role), its chip_ledger leg is written by the
  -- autoledger inside that same statement, at trigger depth 2 or more.
  -- Refusing the leg while the write stands is the one outcome the standard
  -- cannot allow: 104 BBJ bank moves (9.69 chips) lost their legs this way at :55 and
  -- :00 up to 09-05 06:58 (ca_ledger_write_failures, sqlstate 55006), each one an unexplained movement on the BBJ meter. A direct
  -- INSERT on chip_ledger from a client (depth 1) is still refused.
  IF TG_TABLE_NAME = 'chip_ledger' AND pg_trigger_depth() > 1 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  BEGIN
    v_claims := current_setting('request.jwt.claims', TRUE);
    IF v_claims IS NOT NULL AND v_claims <> ''
       AND (v_claims::jsonb ->> 'role') = 'service_role' THEN
      RETURN COALESCE(NEW, OLD);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: the platform is on a scheduled maintenance break. % on % was refused; it will succeed when play resumes.',
      TG_OP, TG_TABLE_NAME
      USING ERRCODE = '55006',
            HINT = 'Scheduled maintenance breaks run from :55 to :00. Nothing is lost - retry after the break.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_emit_management_content_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club uuid; v_union uuid; v_type text; v_id uuid; v_role text := 'host';
  v_before jsonb; v_after jsonb;
BEGIN
  IF TG_TABLE_NAME = 'game_ticker_settings' THEN
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id, OLD.club_id);
    v_union := COALESCE(NEW.union_id, OLD.union_id);
    v_type := 'ticker_settings_changed'; v_id := COALESCE(NEW.id, OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('settings',OLD.settings) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('settings',NEW.settings) END;
  ELSIF TG_TABLE_NAME = 'clubs' THEN
    IF NEW.tagline IS NOT DISTINCT FROM OLD.tagline
       AND NEW.lobby_message IS NOT DISTINCT FROM OLD.lobby_message
       AND NEW.description IS NOT DISTINCT FROM OLD.description THEN
      RETURN NULL;
    END IF;
    v_club := NEW.id; v_type := 'club_identity_changed'; v_id := NEW.id;
    v_before := jsonb_build_object('tagline',OLD.tagline,'lobby_message',OLD.lobby_message,'description',OLD.description);
    v_after := jsonb_build_object('tagline',NEW.tagline,'lobby_message',NEW.lobby_message,'description',NEW.description);
  ELSE
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','management_revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','management_revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id,OLD.club_id);
    v_type := 'announcement_changed'; v_id := COALESCE(NEW.id,OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object(
      'title',OLD.title,'content',OLD.content,'is_pinned',OLD.is_pinned,'is_active',OLD.is_active) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object(
      'title',NEW.title,'content',NEW.content,'is_pinned',NEW.is_pinned,'is_active',NEW.is_active) END;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    v_type,v_club,v_union,NULL,TG_TABLE_NAME,v_id,NULL,
    jsonb_build_object('operation',lower(TG_OP)));

  IF auth.uid() IS NOT NULL THEN
    IF v_union IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=auth.uid() THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner'
                  WHEN m.role='admin' THEN 'admin' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m
          ON m.club_id=c.id AND m.user_id=auth.uid()
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state
    ) VALUES (
      auth.uid(),COALESCE(v_role,'host'),v_type,TG_TABLE_NAME,v_id,v_club,v_before,v_after);
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_emit_management_access_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_recipient uuid;
  v_club uuid;
  v_union uuid;
  v_operation text := lower(TG_OP);
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    IF TG_OP = 'UPDATE'
       AND NEW.role IS NOT DISTINCT FROM OLD.role
       AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
       AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
       AND NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN
      RETURN NULL;
    END IF;

    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', OLD.club_id, NULL, OLD.user_id,
        'club', OLD.club_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'before'));
    END IF;
    IF TG_OP IN ('UPDATE', 'INSERT')
       AND (TG_OP = 'INSERT'
            OR NEW.user_id IS DISTINCT FROM OLD.user_id
            OR NEW.club_id IS DISTINCT FROM OLD.club_id
            OR NEW.role IS DISTINCT FROM OLD.role
            OR NEW.status IS DISTINCT FROM OLD.status
            OR NEW.is_active IS DISTINCT FROM OLD.is_active) THEN
      -- When the row identity did not move, one after-event is sufficient.
      IF TG_OP = 'INSERT'
         OR NEW.user_id IS DISTINCT FROM OLD.user_id
         OR NEW.club_id IS DISTINCT FROM OLD.club_id THEN
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.club_id, NULL, NEW.user_id,
          'club', NEW.club_id, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'after'));
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'union_admins' THEN
    IF TG_OP = 'UPDATE'
       AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
       AND NEW.union_id IS NOT DISTINCT FROM OLD.union_id
       AND NEW.role IS NOT DISTINCT FROM OLD.role THEN
      RETURN NULL;
    END IF;

    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', NULL, OLD.union_id, OLD.user_id,
        'union', OLD.union_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'before'));
    END IF;
    IF TG_OP = 'INSERT'
       OR (TG_OP = 'UPDATE' AND (
         NEW.user_id IS DISTINCT FROM OLD.user_id
         OR NEW.union_id IS DISTINCT FROM OLD.union_id)) THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', NULL, NEW.union_id, NEW.user_id,
        'union', NEW.union_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'after'));
    END IF;

  ELSE
    -- union_clubs. UPDATE was omitted from the original trigger entirely.
    -- Each side gets its own recipient set and its own union scope.
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      v_club := OLD.club_id;
      v_union := OLD.union_id;
      FOR v_recipient IN
        SELECT c.owner_id FROM public.clubs c WHERE c.id = v_club
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = v_club
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', v_club, v_union, v_recipient,
          'club', v_club, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'before'));
      END LOOP;
    END IF;

    IF TG_OP IN ('UPDATE', 'INSERT') THEN
      v_club := NEW.club_id;
      v_union := NEW.union_id;
      FOR v_recipient IN
        SELECT c.owner_id FROM public.clubs c WHERE c.id = v_club
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = v_club
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', v_club, v_union, v_recipient,
          'club', v_club, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'after'));
      END LOOP;
    END IF;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_emit_club_union_access_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_recipient uuid;
  v_union uuid;
  v_side text;
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, OLD.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'before'));
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, NEW.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'after'));
  END IF;

  IF NEW.union_id IS DISTINCT FROM OLD.union_id THEN
    FOR v_union, v_side IN
      SELECT OLD.union_id, 'before' WHERE OLD.union_id IS NOT NULL
      UNION ALL
      SELECT NEW.union_id, 'after' WHERE NEW.union_id IS NOT NULL
    LOOP
      FOR v_recipient IN
        SELECT OLD.owner_id
        UNION SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, v_union, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', v_side));
      END LOOP;
    END LOOP;

    -- Leaving a union has a new standalone scope. Its operators still need an
    -- authoritative refresh even though there is no new union recipient set.
    IF NEW.union_id IS NULL THEN
      FOR v_recipient IN
        SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, NULL, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', 'after'));
      END LOOP;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
